{
  "name": "CricScore Pro AI",
  "description": "Professional ICC-standard cricket scoring engine with AI-powered commentary and insights."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { MatchSetup } from './components/MatchSetup';
import { ScoringDashboard } from './components/ScoringDashboard';
import { MatchState, Player, Team } from './types';
import { MatchSummary } from './components/MatchSummary';

const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'scoring' | 'summary'>('setup');
  const [matchState, setMatchState] = useState<MatchState | null>(null);

  // Initialize a new match
  const handleStartMatch = (
    homeTeamName: string,
    awayTeamName: string,
    overs: number,
    homePlayers: string[],
    awayPlayers: string[]
  ) => {
    const homeTeam: Team = {
      name: homeTeamName,
      players: homePlayers.map((name, id) => ({ id: `h${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: true, // Simplified: Home always bats first in this MVP
    };

    const awayTeam: Team = {
      name: awayTeamName,
      players: awayPlayers.map((name, id) => ({ id: `a${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: false,
    };

    // Initial State
    const initialState: MatchState = {
      battingTeam: homeTeam,
      bowlingTeam: awayTeam,
      totalOvers: overs,
      currentOver: 0,
      currentBall: 0, // legal balls in current over
      totalRuns: 0,
      wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: homeTeam.players[0].id,
      nonStrikerId: homeTeam.players[1].id,
      currentBowlerId: awayTeam.players[awayTeam.players.length - 1].id, // Default last player bowls
      ballHistory: [],
      matchStatus: 'LIVE',
      messages: []
    };

    setMatchState(initialState);
    setView('scoring');
  };

  const handleFinishMatch = () => {
    setView('summary');
  };

  return (
    <div className="h-screen w-full bg-gray-900 text-white flex flex-col font-sans">
      {view === 'setup' && <MatchSetup onStart={handleStartMatch} />}
      {view === 'scoring' && matchState && (
        <ScoringDashboard 
          matchState={matchState} 
          setMatchState={setMatchState} 
          onFinish={handleFinishMatch}
        />
      )}
      {view === 'summary' && matchState && (
        <MatchSummary matchState={matchState} onRestart={() => setView('setup')} />
      )}
    </div>
  );
};

export default App;

export interface Player {
  id: string;
  name: string;
  // Batting stats
  runs: number;
  balls: number;
  fours: number;
  sixes: number;
  isOut: boolean;
  dismissalType?: string;
  dismissalBowler?: string;
  // Bowling stats
  ballsBowled: number;
  runsConceded: number;
  wickets: number;
  maidens: number;
}

export interface Team {
  name: string;
  players: Player[];
  isBatting: boolean;
}

export interface Extras {
  wides: number;
  noBalls: number;
  byes: number;
  legByes: number;
}

export enum ExtraType {
  NONE = 'None',
  WIDE = 'Wide',
  NO_BALL = 'No Ball',
  BYE = 'Bye',
  LEG_BYE = 'Leg Bye',
}

export enum WicketType {
  BOWLED = 'Bowled',
  CAUGHT = 'Caught',
  LBW = 'LBW',
  RUN_OUT = 'Run Out',
  STUMPED = 'Stumped',
  HIT_WICKET = 'Hit Wicket',
}

export interface BallEvent {
  runs: number; // Runs off bat
  extraRuns: number; // Runs from extras
  extraType: ExtraType;
  isWicket: boolean;
  wicketType?: WicketType;
  batsmanId: string;
  bowlerId: string;
  description: string;
  timestamp: number;
  isLegalBall: boolean;
}

export interface MatchState {
  battingTeam: Team;
  bowlingTeam: Team;
  totalOvers: number;
  currentOver: number;
  currentBall: number; // Legal balls in current over (0-5)
  totalRuns: number;
  wickets: number;
  extras: Extras;
  strikerId: string;
  nonStrikerId: string;
  currentBowlerId: string;
  ballHistory: BallEvent[];
  matchStatus: 'LIVE' | 'COMPLETED';
  messages: { text: string; type: 'info' | 'ai' }[];
}

import { MatchState, BallEvent, ExtraType, WicketType, Player } from '../types';

export const getPlayer = (players: Player[], id: string) => players.find(p => p.id === id);

export const calculateEconomy = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 6).toFixed(2);
};

export const calculateStrikeRate = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 100).toFixed(2);
};

/**
 * Main pure function to update state based on a scoring event
 */
export const processBall = (
  currentState: MatchState,
  runs: number,
  extraType: ExtraType,
  isWicket: boolean,
  wicketType?: WicketType,
  newBatsmanId?: string // Required if wicket falls
): MatchState => {
  const newState = JSON.parse(JSON.stringify(currentState)) as MatchState;

  const striker = getPlayer(newState.battingTeam.players, newState.strikerId)!;
  const bowler = getPlayer(newState.bowlingTeam.players, newState.currentBowlerId)!;

  let runsScored = runs;
  let extrasConceded = 0;
  let isLegalBall = true;

  // 1. Handle Extras logic
  if (extraType === ExtraType.WIDE) {
    extrasConceded += 1 + runs; // 1 for wide + any runs taken
    newState.extras.wides += 1 + runs;
    isLegalBall = false;
    bowler.runsConceded += 1 + runs;
    // Wide does not count to batsman ball faced
  } else if (extraType === ExtraType.NO_BALL) {
    extrasConceded += 1;
    newState.extras.noBalls += 1;
    isLegalBall = false;
    bowler.runsConceded += 1;

    // Runs off bat count for batsman on No Ball
    striker.runs += runs;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;
    striker.balls++; // Counts as ball faced
    bowler.runsConceded += runs;
    runsScored += runs; 

  } else if (extraType === ExtraType.BYE) {
    extrasConceded += runs;
    newState.extras.byes += runs;
    striker.balls++; // Counts as ball faced
    // Runs don't count to bowler, but ball does
    isLegalBall = true;
  } else if (extraType === ExtraType.LEG_BYE) {
    extrasConceded += runs;
    newState.extras.legByes += runs;
    striker.balls++; 
    isLegalBall = true;
  } else {
    // Regular ball
    striker.runs += runs;
    striker.balls++;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;

    bowler.runsConceded += runs;
    runsScored += runs;
  }

  // Update Bowler Stats
  if (isLegalBall) {
    bowler.ballsBowled++;
    newState.currentBall++;
  }

  // Total Score Update
  newState.totalRuns += runsScored + extrasConceded;

  // 2. Handle Wicket
  if (isWicket) {
    newState.wickets++;
    // Dismiss the striker (or non-striker for run out, simplified to striker for now unless complex UI)
    // For Run Out, it could be either end, but for MVP assuming striker is out or non-striker logic handled externally.
    // Standard rule: Bowler gets wicket unless run out
    if (wicketType !== WicketType.RUN_OUT) {
      bowler.wickets++;
    }

    striker.isOut = true;
    striker.dismissalType = wicketType;
    striker.dismissalBowler = bowler.name;

    // Set new striker
    if (newBatsmanId) {
      newState.strikerId = newBatsmanId;
    }
  }

  // 3. Strike Rotation
  // Swap if runs is odd (1, 3, 5)
  // Important: On No Ball + 1 run, they cross. On Wide + 1 run, they cross.
  // Note: If Wicket falls, crossing rule applies. For MVP, we assume new batsman takes strike unless crossed (complex).
  // Simplified: If runs are odd, swap.
  const totalRunActivity = runs; // Runs run by physical running (approx)
  if (totalRunActivity % 2 !== 0) {
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;
  }

  // 4. Record Event
  const event: BallEvent = {
    runs,
    extraRuns: extrasConceded,
    extraType,
    isWicket,
    wicketType,
    batsmanId: striker.id,
    bowlerId: bowler.id,
    description: `${runs} run${runs !== 1 ? 's' : ''} ${extraType !== ExtraType.NONE ? `(${extraType})` : ''} ${isWicket ? 'WICKET!' : ''}`,
    timestamp: Date.now(),
    isLegalBall
  };
  newState.ballHistory.push(event);

  // 5. Over Completion
  if (newState.currentBall >= 6) {
    newState.currentOver++;
    newState.currentBall = 0;

    // Switch strike at end of over
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;

    // Check maiden
    // Logic for maiden would go here (checking last 6 events for this bowler)

    // Force bowler change requirement logic in UI
  }

  // 6. Match Status
  if (newState.wickets >= 10 || newState.currentOver >= newState.totalOvers) {
    newState.matchStatus = 'COMPLETED';
  }

  return newState;
};

import { GoogleGenAI } from "@google/genai";
import { MatchState, BallEvent } from '../types';

// NOTE: Ideally this comes from process.env.API_KEY, but user needs to provide it.
// We will assume the environment is set up or handle gracefully.
const API_KEY = process.env.API_KEY || '';

let ai: GoogleGenAI | null = null;
if (API_KEY) {
  ai = new GoogleGenAI({ apiKey: API_KEY });
}

export const generateCommentary = async (lastBall: BallEvent, state: MatchState): Promise<string> => {
  if (!ai) return "Gemini API Key missing.";

  const prompt = `
    Context: Cricket Match. 
    Score: ${state.totalRuns}/${state.wickets} in ${state.currentOver}.${state.currentBall} overs.
    Last Event: ${lastBall.description}.
    Batsman: ${lastBall.runs} runs scored.

    Write a short, exciting, professional cricket commentary line (max 15 words) for this specific ball. 
    Style: Ian Bishop or Ravi Shastri.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text.trim();
  } catch (error) {
    console.error("Gemini Error:", error);
    return "What a delivery!";
  }
};

export const askRuleQuestion = async (query: string): Promise<string> => {
  if (!ai) return "AI service unavailable.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `Answer this cricket rule question briefly based on ICC Playing Conditions: ${query}`,
    });
    return response.text.trim();
  } catch (error) {
    return "Unable to fetch rule.";
  }
};

export const generateMatchSummary = async (state: MatchState): Promise<string> => {
  if (!ai) return "AI service unavailable.";

  const summaryData = {
    score: `${state.totalRuns}/${state.wickets}`,
    overs: `${state.currentOver}.${state.currentBall}`,
    topBatters: state.battingTeam.players.sort((a,b) => b.runs - a.runs).slice(0, 2).map(p => `${p.name} (${p.runs})`),
    keyEvents: state.ballHistory.filter(b => b.isWicket || b.runs >= 4).length
  };

  const prompt = `Write a 2-sentence post-match summary for a cricket match. Data: ${JSON.stringify(summaryData)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    return "Match concluded.";
  }
};

import React, { useState } from 'react';

interface Props {
  onStart: (home: string, away: string, overs: number, homePlayers: string[], awayPlayers: string[]) => void;
}

export const MatchSetup: React.FC<Props> = ({ onStart }) => {
  const [homeTeam, setHomeTeam] = useState('India');
  const [awayTeam, setAwayTeam] = useState('Australia');
  const [overs, setOvers] = useState(20);

  // Simplified roster for demo
  const defaultPlayers = (prefix: string) => Array.from({ length: 11 }, (_, i) => `${prefix} Player ${i + 1}`);

  return (
    <div className="flex flex-col items-center justify-center h-full p-6 bg-gradient-to-br from-gray-900 to-blue-900">
