          <div>
            <label className="block text-xs font-semibold uppercase text-gray-400 mb-1">Away Team</label>
            <input 
              value={awayTeam} 
              onChange={(e) => setAwayTeam(e.target.value)} 
              className="w-full bg-gray-700 border border-gray-600 rounded p-3 text-white focus:ring-2 focus:ring-green-500 outline-none"
            />
          </div>

