              value={overs} 
              onChange={(e) => setOvers(Number(e.target.value))}
              className="w-full bg-gray-700 border border-gray-600 rounded p-3 text-white focus:ring-2 focus:ring-green-500 outline-none"
            >
              <option value={2}>2 Overs (Test)</option>
              <option value={5}>5 Overs (Blitz)</option>
              <option value={10}>10 Overs</option>
              <option value={20}>20 Overs (T20)</option>
              <option value={50}>50 Overs (ODI)</option>
            </select>
          </div>

          <button 
            onClick={() => onStart(homeTeam, awayTeam, overs, defaultPlayers(homeTeam), defaultPlayers(awayTeam))}
            className="w-full mt-6 bg-green-500 hover:bg-green-600 text-white font-bold py-4 rounded-xl shadow-lg transform transition active:scale-95"
          >
            Start Match
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MatchState, ExtraType, WicketType, Player } from '../types';
import { processBall, getPlayer, calculateEconomy, calculateStrikeRate } from '../utils/cricketLogic';
import { generateCommentary, askRuleQuestion } from '../services/geminiService';
import { Mic, Info, ArrowRight, Zap, RefreshCw } from 'lucide-react';

interface Props {
  matchState: MatchState;
  setMatchState: (state: MatchState) => void;
  onFinish: () => void;
}

export const ScoringDashboard: React.FC<Props> = ({ matchState, setMatchState, onFinish }) => {
  const [wicketModalOpen, setWicketModalOpen] = useState(false);
  const [extraType, setExtraType] = useState<ExtraType>(ExtraType.NONE);
  const [commentary, setCommentary] = useState<string>("Match Started. Waiting for first ball.");
  const [aiLoading, setAiLoading] = useState(false);
  const [bowlerSelectOpen, setBowlerSelectOpen] = useState(false);
  const [batsmanSelectOpen, setBatsmanSelectOpen] = useState(false);

  // Refs to handle scrolling or auto-focus
  const timelineRef = useRef<HTMLDivElement>(null);

  const striker = getPlayer(matchState.battingTeam.players, matchState.strikerId);
  const nonStriker = getPlayer(matchState.battingTeam.players, matchState.nonStrikerId);
  const bowler = getPlayer(matchState.bowlingTeam.players, matchState.currentBowlerId);

  // Check for bowler change needed
  useEffect(() => {
    if (matchState.currentBall === 0 && matchState.currentOver > 0 && matchState.ballHistory.length > 0) {
      setBowlerSelectOpen(true);
    }
  }, [matchState.currentOver]);

  // Check for match completion
  useEffect(() => {
    if (matchState.matchStatus === 'COMPLETED') {
      onFinish();
    }
  }, [matchState.matchStatus]);

  const handleScore = async (runs: number, isWicket: boolean, wType?: WicketType) => {
    // If wicket, we need to pick next batsman later, but for MVP we auto-assign next available or show modal
    let nextBatsmanId = undefined;

    if (isWicket) {
      // Simple logic: Find next batsman who hasn't batted
      const nextBat = matchState.battingTeam.players.find(p => !p.isOut && p.id !== matchState.strikerId && p.id !== matchState.nonStrikerId);
      if (nextBat) nextBatsmanId = nextBat.id;
      else {
        // All out
        onFinish();
        return;
      }
    }

    const newState = processBall(matchState, runs, extraType, isWicket, wType, nextBatsmanId);
    setMatchState(newState);

    // Reset inputs
    setExtraType(ExtraType.NONE);
    setWicketModalOpen(false);

    // AI Commentary Trigger
    setAiLoading(true);
    const lastEvent = newState.ballHistory[newState.ballHistory.length - 1];
    generateCommentary(lastEvent, newState).then(text => {
      setCommentary(text);
      setAiLoading(false);
    });
  };

  const handleChangeBowler = (bowlerId: string) => {
    const newState = { ...matchState, currentBowlerId: bowlerId };
    setMatchState(newState);
    setBowlerSelectOpen(false);
  };

  return (
    <div className="flex flex-col h-full bg-gray-900 relative">
      {/* Header / Scoreboard */}
      <div className="bg-gray-800 p-4 pb-6 shadow-xl z-10">
        <div className="flex justify-between items-start mb-4">
           <div>
             <h2 className="text-sm text-gray-400 font-semibold">{matchState.battingTeam.name} vs {matchState.bowlingTeam.name}</h2>
             <div className="flex items-baseline mt-1">
               <span className="text-4xl font-bold text-white tracking-tighter">
                 {matchState.totalRuns}<span className="text-gray-500">/</span>{matchState.wickets}
               </span>
               <span className="ml-3 text-lg text-gray-400 font-mono">
                 {matchState.currentOver}.{matchState.currentBall} <span className="text-xs">OVERS</span>
               </span>
             </div>
             <div className="text-xs text-gray-400 mt-1">
                Run Rate: {((matchState.totalRuns / (matchState.currentOver * 6 + matchState.currentBall || 1)) * 6).toFixed(2)}
             </div>
           </div>
           <div className="text-right">
             <div className="bg-gray-700 rounded-lg p-2 min-w-[120px]">
                <div className="text-xs text-green-400 font-bold mb-1 flex items-center justify-end">
                  TARGET: {matchState.battingTeam.isBatting ? 'SET' : '150'} {/* Placeholder logic */}
                  <Zap size={10} className="ml-1" />
                </div>
                <div className="text-xs text-gray-300">
                  Extras: {matchState.extras.wides + matchState.extras.noBalls + matchState.extras.byes + matchState.extras.legByes}
                </div>
             </div>
           </div>
        </div>

        {/* Current Players */}
        <div className="grid grid-cols-2 gap-3 text-sm">
          <div className="bg-gray-700/50 p-2 rounded border border-gray-600">
            <div className="flex justify-between items-center text-green-300 font-semibold">
              <span>{striker?.name}*</span>
              <span>{striker?.runs} ({striker?.balls})</span>
            </div>
            <div className="flex justify-between items-center text-gray-400 text-xs mt-1">
              <span>{nonStriker?.name}</span>
              <span>{nonStriker?.runs} ({nonStriker?.balls})</span>
            </div>
          </div>
          <div className="bg-gray-700/50 p-2 rounded border border-gray-600">
             <div className="text-blue-300 font-semibold flex justify-between">
                <span>{bowler?.name}</span>
                <span>{bowler?.wickets}-{bowler?.runsConceded}</span>
             </div>
             <div className="text-xs text-gray-400 mt-1 flex justify-between">
                <span>{matchState.currentOver}.{matchState.currentBall} ov</span>
                <span>Eco: {calculateEconomy(bowler?.runsConceded || 0, bowler?.ballsBowled || 1)}</span>
             </div>
          </div>
        </div>
      </div>

      {/* Ball Timeline */}
      <div className="bg-gray-950 p-2 overflow-x-auto whitespace-nowrap border-b border-gray-800 no-scrollbar flex items-center" ref={timelineRef}>
        <span className="text-xs font-bold text-gray-500 mr-2 sticky left-0 bg-gray-950 pl-2">THIS OVER:</span>
        {matchState.ballHistory.slice(-12).reverse().map((ball, idx) => (
          <div key={idx} className={`inline-flex items-center justify-center w-8 h-8 rounded-full text-xs font-bold mr-2 border 
            ${ball.isWicket ? 'bg-red-900 border-red-600 text-red-100' : 
              ball.runs >= 4 ? 'bg-green-900 border-green-600 text-green-100' : 
              'bg-gray-800 border-gray-700 text-gray-300'}`}>
            {ball.isWicket ? 'W' : ball.extraType !== ExtraType.NONE ? (ball.runs + ball.extraRuns) + (ball.extraType[0]) : ball.runs}
          </div>
        ))}
      </div>

      {/* AI Commentary */}
      <div className="px-4 py-3 bg-gradient-to-r from-gray-900 to-blue-900/20 border-b border-gray-800 flex items-center min-h-[60px]">
        <Mic size={16} className={`text-blue-400 mr-3 ${aiLoading ? 'animate-pulse' : ''}`} />
        <p className="text-sm text-blue-100 italic font-medium leading-relaxed">
          "{commentary}"
        </p>
      </div>

      {/* Main Controls Area - Takes remaining height */}
      <div className="flex-1 p-4 grid grid-cols-4 gap-3 content-end pb-8">

        {/* Extras Toggles */}
        <div className="col-span-4 flex justify-between gap-2 mb-2">
           {[ExtraType.WIDE, ExtraType.NO_BALL, ExtraType.BYE, ExtraType.LEG_BYE].map((type) => (
             <button
                key={type}
                onClick={() => setExtraType(extraType === type ? ExtraType.NONE : type)}
                className={`flex-1 py-2 text-xs font-bold uppercase rounded transition-colors border ${
                  extraType === type 
                  ? 'bg-yellow-600 border-yellow-500 text-white' 
                  : 'bg-gray-800 border-gray-700 text-gray-400'
                }`}
             >
               {type}
             </button>
           ))}
        </div>

        {/* Scoring Buttons */}
        <button onClick={() => handleScore(0, false)} className="btn-score bg-gray-700 text-white">0</button>
        <button onClick={() => handleScore(1, false)} className="btn-score bg-gray-700 text-white">1</button>
        <button onClick={() => handleScore(2, false)} className="btn-score bg-gray-700 text-white">2</button>
        <button onClick={() => handleScore(3, false)} className="btn-score bg-gray-700 text-white">3</button>

        <button onClick={() => handleScore(4, false)} className="btn-score bg-green-600 text-white border-green-500">4</button>
        <button onClick={() => handleScore(6, false)} className="btn-score bg-green-600 text-white border-green-500">6</button>

        <button onClick={() => setWicketModalOpen(true)} className="col-span-2 bg-red-600 text-white font-bold rounded-xl text-xl shadow-lg active:scale-95 transition-transform">
          OUT
        </button>

        <button 
          onClick={() => {
            // Quick access to rule book
            setAiLoading(true);
            askRuleQuestion("What is the penalty for a slow over rate?").then(ans => {
               alert(ans);
               setAiLoading(false);
            });
          }} 
          className="col-span-4 mt-2 py-3 bg-gray-800 text-gray-400 text-xs rounded-lg flex items-center justify-center gap-2 border border-dashed border-gray-700"
        >
          <Info size={14} /> Ask AI Umpire
        </button>
      </div>

