export interface Player {
  id: string;
  name: string;
  // Batting stats
  runs: number;
  balls: number; // Balls faced
  fours: number;
  sixes: number;
  isOut: boolean;
  dismissalType?: string;
  dismissalBowler?: string;
  // Bowling stats
  ballsBowled: number;
  runsConceded: number;
  wickets: number;
  maidens: number;
}

export interface Team {
  name: string;
  players: Player[];
  isBatting: boolean;
}

export interface Extras {
  wides: number;
  noBalls: number;
  byes: number;
  legByes: number;
}

export enum ExtraType {
  NONE = 'None',
  WIDE = 'Wide',
  NO_BALL = 'No Ball',
  BYE = 'Bye',
  LEG_BYE = 'Leg Bye',
}

export enum WicketType {
  BOWLED = 'Bowled',
  CAUGHT = 'Caught',
  LBW = 'LBW',
  RUN_OUT = 'Run Out',
  STUMPED = 'Stumped',
  HIT_WICKET = 'Hit Wicket',
}

export interface BallEvent {
  runs: number; // Runs off bat
  extraRuns: number; // Runs from extras
  extraType: ExtraType;
  isWicket: boolean;
  wicketType?: WicketType;
  batsmanId: string;
  bowlerId: string;
  description: string;
  timestamp: number;
  isLegalBall: boolean;
}

export interface MatchState {
  battingTeam: Team;
  bowlingTeam: Team;
  tossWinner: string;
  tossDecision: 'bat' | 'bowl';
  totalOvers: number;
  currentOver: number;
  currentBall: number; // Legal balls in current over (0-5)
  totalRuns: number;
  wickets: number;
  extras: Extras;
  strikerId: string;
  nonStrikerId: string;
  currentBowlerId: string;
  ballHistory: BallEvent[];
  matchStatus: 'LIVE' | 'COMPLETED';
}

import { MatchState, BallEvent, ExtraType, WicketType, Player } from '../types';

export const getPlayer = (players: Player[], id: string) => players.find(p => p.id === id);

export const calculateEconomy = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 6).toFixed(2);
};

export const calculateStrikeRate = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 100).toFixed(2);
};

/**
 * Main pure function to update state based on a scoring event
 */
export const processBall = (
  currentState: MatchState,
  runs: number,
  extraType: ExtraType,
  isWicket: boolean,
  wicketType?: WicketType,
  newBatsmanId?: string // Required if wicket falls
): MatchState => {
  const newState = JSON.parse(JSON.stringify(currentState)) as MatchState;

  const striker = getPlayer(newState.battingTeam.players, newState.strikerId)!;
  const bowler = getPlayer(newState.bowlingTeam.players, newState.currentBowlerId)!;

  let runsScored = runs; // Runs credited to batsman
  let extrasConceded = 0;
  let isLegalBall = true;

  // 1. Handle Extras logic
  if (extraType === ExtraType.WIDE) {
    // Wide: 1 run extra + any ran runs are also extras (usually).
    // In this engine: 'runs' arg = runs RAN by players.
    // Total runs = 1 (wide) + runs.
    extrasConceded += 1 + runs; 
    newState.extras.wides += 1 + runs;
    isLegalBall = false;
    bowler.runsConceded += 1 + runs;
    // Wide does not count to batsman balls faced
    runsScored = 0; // No runs to batsman on wide usually

  } else if (extraType === ExtraType.NO_BALL) {
    // No Ball: 1 run extra.
    extrasConceded += 1;
    newState.extras.noBalls += 1;
    isLegalBall = false;
    bowler.runsConceded += 1;

    // Runs off bat count for batsman on No Ball
    // Important: ICC Law 2.11 - No Ball does NOT count as ball faced.
    striker.runs += runs;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;

    // Do NOT increment striker.balls for No Ball

    bowler.runsConceded += runs;
    runsScored = runs; 

  } else if (extraType === ExtraType.BYE) {
    extrasConceded += runs;
    newState.extras.byes += runs;
    striker.balls++; // Counts as ball faced
    isLegalBall = true;
    runsScored = 0; // Runs to extras, not batsman

  } else if (extraType === ExtraType.LEG_BYE) {
    extrasConceded += runs;
    newState.extras.legByes += runs;
    striker.balls++; 
    isLegalBall = true;
    runsScored = 0;

  } else {
    // Regular ball
    striker.runs += runs;
    striker.balls++;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;

    bowler.runsConceded += runs;
    runsScored = runs;
  }

  // Update Bowler Stats (Legal balls only)
  if (isLegalBall) {
    bowler.ballsBowled++;
    newState.currentBall++;
  }

  // Total Score Update
  newState.totalRuns += runsScored + extrasConceded;

  // 2. Handle Wicket
  if (isWicket) {
    newState.wickets++;

    // Credit wicket to bowler?
    // Not for Run Out
    if (wicketType !== WicketType.RUN_OUT) {
      bowler.wickets++;
    }

    striker.isOut = true;
    striker.dismissalType = wicketType;
    striker.dismissalBowler = bowler.name;

    // Set new striker
    if (newBatsmanId) {
      newState.strikerId = newBatsmanId;
    }
  }

  // 3. Strike Rotation
  // Swap if physical runs (runs ran) is odd.
  // Standard balls: runs = runs ran.
  // Wide: runs = runs ran.
  // No Ball: runs = runs ran (off bat).
  // Byes/Leg Byes: runs = runs ran.
  // Boundary (4/6): runs ran is 0 implicitly for crossing purposes (no cross), but handled by input. 
  // Assumption: Input '4' means boundary. Input '1' means run.
  // If user enters '3' run, they cross.
  // Note: On Wicket, we assume new batsman takes strike unless Run Out crossed logic is applied. MVP simplifies to new batsman on strike.

  if (runs % 2 !== 0) {
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;
  }

  // 4. Record Event
  const event: BallEvent = {
    runs,
    extraRuns: extrasConceded,
    extraType,
    isWicket,
    wicketType,
    batsmanId: striker.id,
    bowlerId: bowler.id,
    description: `${runs} run${runs !== 1 ? 's' : ''} ${extraType !== ExtraType.NONE ? `(${extraType})` : ''} ${isWicket ? 'WICKET!' : ''}`,
    timestamp: Date.now(),
    isLegalBall
  };
  newState.ballHistory.push(event);

  // 5. Over Completion
  if (newState.currentBall >= 6) {
    newState.currentOver++;
    newState.currentBall = 0;

    // Switch strike at end of over
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;
  }

  // 6. Match Status
  if (newState.wickets >= 10 || newState.currentOver >= newState.totalOvers) {
    newState.matchStatus = 'COMPLETED';
  }

  return newState;
};

import React, { useState } from 'react';

interface Props {
  onNext: (home: string, away: string, overs: number, homePlayers: string[], awayPlayers: string[]) => void;
}

export const MatchSetup: React.FC<Props> = ({ onNext }) => {
  const [homeTeam, setHomeTeam] = useState('India');
  const [awayTeam, setAwayTeam] = useState('Australia');
  const [overs, setOvers] = useState(20);

