                   </div>
                   <div className="mt-3 pt-2 border-t border-gray-700 text-xs text-center text-gray-400">
                      Toss won by <span className="text-tiger-gold">{match.tossWinner}</span> ({match.tossDecision})
                   </div>
                 </div>
               ))
             )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Trophy, BarChart2 } from 'lucide-react';

interface Props {
  onNext: (home: string, away: string, overs: number, homePlayers: string[], awayPlayers: string[]) => void;
  onViewStats: () => void;
}

export const MatchSetup: React.FC<Props> = ({ onNext, onViewStats }) => {
  const [homeTeam, setHomeTeam] = useState('Taxila Tigers');
  const [awayTeam, setAwayTeam] = useState('Opponent');
  const [overs, setOvers] = useState(20);

  const [homeSquad, setHomeSquad] = useState(
    Array.from({ length: 11 }, (_, i) => `Tiger Player ${i + 1}`).join('\n')
