  const [awaySquad, setAwaySquad] = useState(
    Array.from({ length: 11 }, (_, i) => `Player ${i + 1}`).join('\n')
  );

  const [activeTab, setActiveTab] = useState<'details' | 'squads'>('details');

  const handleNext = () => {
    const hPlayers = homeSquad.split('\n').filter(p => p.trim() !== '');
    const aPlayers = awaySquad.split('\n').filter(p => p.trim() !== '');

    if (hPlayers.length < 2 || aPlayers.length < 2) {
      alert("Please ensure at least 2 players per team.");
      return;
    }

    onNext(homeTeam, awayTeam, overs, hPlayers, aPlayers);
