              <img 
                src="https://files.oaiusercontent.com/file-2p5s5S4jKqvqYw" 
                alt="Taxila Tigers" 
                className="w-full h-full rounded-full object-cover border-4 border-black"
                onError={(e) => {
                  // Fallback if image fails to load
                  e.currentTarget.style.display = 'none';
                  e.currentTarget.parentElement!.innerHTML = '<div class="w-full h-full rounded-full bg-black flex items-center justify-center text-3xl">🐯</div>'
                }}
              />
           </div>
           <h1 className="text-3xl font-black text-center text-tiger-gold uppercase tracking-tight">Taxila Tigers</h1>
           <p className="text-gray-500 text-sm tracking-widest uppercase">Official Scoring App</p>
        </div>

        {/* Stats Button */}
        <button 
           onClick={onViewStats}
