          >
            Squads
          </button>
        </div>

        {activeTab === 'details' ? (
          <div className="space-y-4 bg-gray-800 p-6 rounded-2xl shadow-xl border border-gray-700">
             <div>
                <label className="block text-xs font-semibold uppercase text-tiger-gold mb-1">Home Team</label>
                <input 
                  value={homeTeam} 
                  onChange={(e) => setHomeTeam(e.target.value)} 
                  className="w-full bg-tiger-black border border-gray-600 rounded p-3 text-white focus:ring-2 focus:ring-tiger-gold outline-none font-bold"
                />
