import React, { useState } from 'react';
import { MatchSetup } from './components/MatchSetup';
import { TossScreen } from './components/TossScreen';
import { ScoringDashboard } from './components/ScoringDashboard';
import { StatsDashboard } from './components/StatsDashboard';
import { MatchState, Player, Team } from './types';
import { MatchSummary } from './components/MatchSummary';

// Temp storage for setup data before toss
interface SetupData {
  homeTeam: string;
  awayTeam: string;
  overs: number;
  homePlayers: string[];
  awayPlayers: string[];
}

const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'toss' | 'scoring' | 'summary' | 'stats'>('setup');
  const [matchState, setMatchState] = useState<MatchState | null>(null);
  const [setupData, setSetupData] = useState<SetupData | null>(null);
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);

  // Undo History Stack (Max 50 states to save memory)
  const [history, setHistory] = useState<MatchState[]>([]);

  const handleSetupComplete = (
    homeTeam: string,
    awayTeam: string,
    overs: number,
    homePlayers: string[],
    awayPlayers: string[]
  ) => {
    setSetupData({ homeTeam, awayTeam, overs, homePlayers, awayPlayers });
    setView('toss');
  };

  const handleTossComplete = (winner: string, decision: 'bat' | 'bowl') => {
    if (!setupData) return;

    // Determine Batting and Bowling Teams based on Toss
    const isHomeBattingFirst = (winner === setupData.homeTeam && decision === 'bat') || (winner === setupData.awayTeam && decision === 'bowl');

    const battingTeamPlayers = isHomeBattingFirst ? setupData.homePlayers : setupData.awayPlayers;
    const bowlingTeamPlayers = isHomeBattingFirst ? setupData.awayPlayers : setupData.homePlayers;
    const battingTeamName = isHomeBattingFirst ? setupData.homeTeam : setupData.awayTeam;
    const bowlingTeamName = isHomeBattingFirst ? setupData.awayTeam : setupData.homeTeam;

    const battingTeam: Team = {
      name: battingTeamName,
      players: battingTeamPlayers.map((name, id) => ({ id: `bat${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: true,
    };

    const bowlingTeam: Team = {
      name: bowlingTeamName,
      players: bowlingTeamPlayers.map((name, id) => ({ id: `bowl${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: false,
    };

    const initialState: MatchState = {
      battingTeam,
      bowlingTeam,
      tossWinner: winner,
      tossDecision: decision,
      totalOvers: setupData.overs,
      currentOver: 0,
      currentBall: 0,
      totalRuns: 0,
      wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: battingTeam.players[0].id,
      nonStrikerId: battingTeam.players[1].id,
      currentBowlerId: bowlingTeam.players[bowlingTeam.players.length - 1].id,
      ballHistory: [],
      matchStatus: 'LIVE',
    };

    setMatchState(initialState);
    setHistory([]);
    setView('scoring');
  };

  const handleUpdateScore = (newState: MatchState) => {
    if (matchState) {
      setHistory(prev => [...prev, matchState].slice(-50)); // Keep last 50 states
    }
    setMatchState(newState);
  };

  const handleUndo = () => {
    if (history.length === 0) return;
    const previousState = history[history.length - 1];
    setHistory(prev => prev.slice(0, -1));
    setMatchState(previousState);
  };

  const handleSaveAndExit = (finalState: MatchState) => {
    setMatchHistory(prev => [...prev, finalState]);
    setView('setup');
  };

  return (
    <div className="h-screen w-full bg-tiger-black text-white flex flex-col font-sans">
      {view === 'setup' && (
        <MatchSetup 
          onNext={handleSetupComplete} 
          onViewStats={() => setView('stats')}
        />
      )}

      {view === 'toss' && setupData && (
        <TossScreen 
          homeTeam={setupData.homeTeam} 
          awayTeam={setupData.awayTeam} 
          onTossComplete={handleTossComplete}
          onBack={() => setView('setup')}
        />
      )}

      {view === 'scoring' && matchState && (
        <ScoringDashboard 
          matchState={matchState} 
          setMatchState={handleUpdateScore} 
          onUndo={handleUndo}
          canUndo={history.length > 0}
          onFinish={() => setView('summary')}
        />
      )}

      {view === 'summary' && matchState && (
        <MatchSummary 
          matchState={matchState} 
          onSaveAndExit={handleSaveAndExit} 
        />
      )}

      {view === 'stats' && (
        <StatsDashboard 
          matchHistory={matchHistory} 
          onBack={() => setView('setup')} 
        />
      )}
    </div>
  );
};

export default App;

export interface Player {
  id: string;
  name: string;
  // Batting stats
  runs: number;
  balls: number; // Balls faced
  fours: number;
  sixes: number;
  isOut: boolean;
  dismissalType?: string;
  dismissalBowler?: string;
  dismissalFielder?: string; // Name of fielder who caught/run-out
  // Bowling stats
  ballsBowled: number;
  runsConceded: number;
  wickets: number;
  maidens: number;
}

export interface Team {
  name: string;
  players: Player[]; // This refers to the Playing XI
  isBatting: boolean;
}

export interface Extras {
  wides: number;
  noBalls: number;
  byes: number;
  legByes: number;
}

export enum ExtraType {
  NONE = 'None',
  WIDE = 'Wide',
  NO_BALL = 'No Ball',
  BYE = 'Bye',
  LEG_BYE = 'Leg Bye',
}

export enum WicketType {
  BOWLED = 'Bowled',
  CAUGHT = 'Caught',
  LBW = 'LBW',
  RUN_OUT = 'Run Out',
  STUMPED = 'Stumped',
  HIT_WICKET = 'Hit Wicket',
}

export interface BallEvent {
  runs: number; // Runs off bat
  extraRuns: number; // Runs from extras
  extraType: ExtraType;
  isWicket: boolean;
  wicketType?: WicketType;
  batsmanId: string;
  bowlerId: string;
  description: string;
  timestamp: number;
  isLegalBall: boolean;
  inningsNumber: 1 | 2;
}

export interface WicketDetails {
  type: WicketType;
  fielderName?: string;
  isStrikerOut: boolean;
}

export interface MatchState {
  battingTeam: Team;
  bowlingTeam: Team;
  tossWinner: string;
  tossDecision: 'bat' | 'bowl';
  totalOvers: number;
  currentOver: number;
  currentBall: number; // Legal balls in current over (0-5)
  totalRuns: number;
  wickets: number;
  extras: Extras;
  strikerId: string;
  nonStrikerId: string;
  currentBowlerId: string;
  ballHistory: BallEvent[];
  matchStatus: 'LIVE' | 'INNINGS_BREAK' | 'COMPLETED';

  // New fields for 2 innings support
  inningsNumber: 1 | 2;
  target?: number; // Only for 2nd innings
  firstInningsScore?: {
    runs: number;
    wickets: number;
    overs: string;
    teamName: string;
  };
}

import { MatchState, BallEvent, ExtraType, WicketType, Player, WicketDetails } from '../types';

export const getPlayer = (players: Player[], id: string) => players.find(p => p.id === id);

export const calculateEconomy = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 6).toFixed(2);
};

export const calculateStrikeRate = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 100).toFixed(2);
};

/**
 * Main pure function to update state based on a scoring event
 */
export const processBall = (
  currentState: MatchState,
  runs: number,
  extraType: ExtraType,
  isWicket: boolean,
  wicketDetails: WicketDetails | undefined,
  newBatsmanId?: string
): MatchState => {
  const newState = JSON.parse(JSON.stringify(currentState)) as MatchState;

  const striker = getPlayer(newState.battingTeam.players, newState.strikerId)!;
  const nonStriker = getPlayer(newState.battingTeam.players, newState.nonStrikerId)!;
  const bowler = getPlayer(newState.bowlingTeam.players, newState.currentBowlerId)!;

  let runsScored = runs; 
  let extrasConceded = 0;
  let isLegalBall = true;

  // 1. Handle Extras logic
  if (extraType === ExtraType.WIDE) {
    extrasConceded += 1 + runs; 
    newState.extras.wides += 1 + runs;
    isLegalBall = false;
    bowler.runsConceded += 1 + runs;
    runsScored = 0; 
  } else if (extraType === ExtraType.NO_BALL) {
    extrasConceded += 1;
    newState.extras.noBalls += 1;
    isLegalBall = false;
    bowler.runsConceded += 1;

    striker.runs += runs;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;

    bowler.runsConceded += runs;
    runsScored = runs; 
  } else if (extraType === ExtraType.BYE) {
    extrasConceded += runs;
    newState.extras.byes += runs;
    striker.balls++; 
    isLegalBall = true;
    runsScored = 0; 
  } else if (extraType === ExtraType.LEG_BYE) {
    extrasConceded += runs;
    newState.extras.legByes += runs;
    striker.balls++; 
    isLegalBall = true;
    runsScored = 0;
  } else {
    // Regular ball
    striker.runs += runs;
    striker.balls++;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;

    bowler.runsConceded += runs;
    runsScored = runs;
  }

  // Update Bowler Stats (Legal balls only)
  if (isLegalBall) {
    bowler.ballsBowled++;
    newState.currentBall++;
  }

  // Total Score Update
  newState.totalRuns += runsScored + extrasConceded;

  // 2. Handle Wicket
  if (isWicket && wicketDetails) {
    newState.wickets++;

    // Determine who is out
    const victim = wicketDetails.isStrikerOut ? striker : nonStriker;

    if (wicketDetails.type !== WicketType.RUN_OUT) {
      bowler.wickets++;
    }

    victim.isOut = true;
    victim.dismissalType = wicketDetails.type;
    victim.dismissalBowler = bowler.name;
    if (wicketDetails.fielderName) {
      victim.dismissalFielder = wicketDetails.fielderName;
    }

    if (newBatsmanId) {
      if (wicketDetails.isStrikerOut) {
        newState.strikerId = newBatsmanId;
      } else {
        newState.nonStrikerId = newBatsmanId;
      }
    }
  }

  // 3. Strike Rotation
  if (runs % 2 !== 0) {
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;
  }

  // 4. Record Event
  let description = `${runs} run${runs !== 1 ? 's' : ''}`;
  if (extraType !== ExtraType.NONE) description += ` (${extraType})`;
  if (isWicket && wicketDetails) {
    description += ` WICKET (${wicketDetails.type})`;
    if (wicketDetails.fielderName) description += ` by ${wicketDetails.fielderName}`;
  }

  const event: BallEvent = {
    runs,
    extraRuns: extrasConceded,
    extraType,
    isWicket,
    wicketType: wicketDetails?.type,
    batsmanId: striker.id,
    bowlerId: bowler.id,
    description,
    timestamp: Date.now(),
    isLegalBall,
    inningsNumber: newState.inningsNumber
  };
  newState.ballHistory.push(event);

  // 5. Over Completion
  if (newState.currentBall >= 6) {
    newState.currentOver++;
    newState.currentBall = 0;
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;
  }

  // 6. Match Status Logic (End of Innings/Match)

  // Check if All Out or Overs Done
  const isAllOut = newState.wickets >= 10; // Standard cricket. Setup might allow less but assuming 10.
  const isOversDone = newState.currentOver >= newState.totalOvers;

  // Check 2nd Innings Win
  const isTargetChased = newState.inningsNumber === 2 && newState.target && newState.totalRuns >= newState.target;

  if (newState.inningsNumber === 1) {
    if (isAllOut || isOversDone) {
      newState.matchStatus = 'INNINGS_BREAK';
      newState.firstInningsScore = {
        runs: newState.totalRuns,
        wickets: newState.wickets,
        overs: `${newState.currentOver}.${newState.currentBall}`,
        teamName: newState.battingTeam.name
      };
    }
  } else {
    // Innings 2
    if (isTargetChased) {
      newState.matchStatus = 'COMPLETED';
    } else if (isAllOut || isOversDone) {
       // Match end, target not reached
       newState.matchStatus = 'COMPLETED';
    }
  }

  return newState;
};

