import React, { useState } from 'react';
import { CheckCircle2, Circle } from 'lucide-react';

interface Props {
  homeTeamName: string;
  awayTeamName: string;
  homeSquad: string[];
  awaySquad: string[];
  onConfirm: (homeXI: string[], awayXI: string[]) => void;
  onBack: () => void;
}

export const SquadSelection: React.FC<Props> = ({ 
  homeTeamName, awayTeamName, homeSquad, awaySquad, onConfirm, onBack 
}) => {
  const [selectedHome, setSelectedHome] = useState<string[]>(homeSquad.slice(0, 11));
  const [selectedAway, setSelectedAway] = useState<string[]>(awaySquad.slice(0, 11));
  const [activeTab, setActiveTab] = useState<'home' | 'away'>('home');

  const toggleSelection = (player: string, isHome: boolean) => {
    const list = isHome ? selectedHome : selectedAway;
    const setList = isHome ? setSelectedHome : setSelectedAway;

    if (list.includes(player)) {
      setList(list.filter(p => p !== player));
    } else {
      if (list.length >= 11) {
        alert("You can only select 11 players.");
        return;
      }
      setList([...list, player]);
    }
  };

  const handleConfirm = () => {
    if (selectedHome.length !== 11 || selectedAway.length !== 11) {
      alert("Please select exactly 11 players for both teams.");
      return;
    }
    onConfirm(selectedHome, selectedAway);
  };

  return (
    <div className="flex flex-col h-full bg-tiger-black text-white p-4">
      <div className="mb-4 text-center">
        <h2 className="text-xl font-bold text-tiger-gold uppercase tracking-wider">Select Playing XI</h2>
        <p className="text-gray-400 text-xs mt-1">Select 11 players from the squad</p>
      </div>

      <div className="flex mb-4 bg-gray-800 p-1 rounded-lg">
        <button 
          onClick={() => setActiveTab('home')}
          className={`flex-1 py-2 rounded-md text-sm font-bold transition-all flex items-center justify-center gap-2 ${activeTab === 'home' ? 'bg-tiger-gold text-black shadow' : 'text-gray-400'}`}
        >
          {homeTeamName} <span className="text-[10px] bg-black/20 px-2 rounded-full">{selectedHome.length}/11</span>
        </button>
        <button 
          onClick={() => setActiveTab('away')}
          className={`flex-1 py-2 rounded-md text-sm font-bold transition-all flex items-center justify-center gap-2 ${activeTab === 'away' ? 'bg-tiger-gold text-black shadow' : 'text-gray-400'}`}
        >
          {awayTeamName} <span className="text-[10px] bg-black/20 px-2 rounded-full">{selectedAway.length}/11</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto space-y-2 bg-gray-900/50 p-2 rounded-xl border border-gray-800">
        {(activeTab === 'home' ? homeSquad : awaySquad).map((player, idx) => {
          const isSelected = (activeTab === 'home' ? selectedHome : selectedAway).includes(player);
          return (
            <button
              key={idx}
              onClick={() => toggleSelection(player, activeTab === 'home')}
              className={`w-full p-3 rounded-lg flex justify-between items-center transition-all ${isSelected ? 'bg-gray-800 border border-tiger-gold' : 'bg-gray-800/50 border border-gray-700 hover:bg-gray-800'}`}
            >
              <span className={`font-semibold ${isSelected ? 'text-white' : 'text-gray-500'}`}>{player}</span>
              {isSelected ? <CheckCircle2 className="text-tiger-gold" size={20} /> : <Circle className="text-gray-600" size={20} />}
            </button>
          );
        })}
      </div>

      <div className="mt-4 flex gap-4">
        <button onClick={onBack} className="flex-1 py-4 bg-gray-800 text-white rounded-xl font-bold">Back</button>
        <button 
          onClick={handleConfirm}
          className="flex-[2] py-4 bg-gradient-to-r from-tiger-gold to-tiger-orange text-black rounded-xl font-bold shadow-lg disabled:opacity-50"
          disabled={selectedHome.length !== 11 || selectedAway.length !== 11}
        >
          Confirm XI
        </button>
      </div>
    </div>
  );
};

