}

export interface SavedTeam {
  id: string;
  name: string;
  logoUrl?: string;
  squad: string[]; // Unlimited squad list
}

export interface Extras {
  wides: number;
  noBalls: number;
  byes: number;
  legByes: number;
}

export enum ExtraType {
  NONE = 'None',
  WIDE = 'Wide',
  NO_BALL = 'No Ball',
  BYE = 'Bye',
  LEG_BYE = 'Leg Bye',
}

export enum WicketType {
  BOWLED = 'Bowled',
  CAUGHT = 'Caught',
  LBW = 'LBW',
  RUN_OUT = 'Run Out',
  STUMPED = 'Stumped',
  HIT_WICKET = 'Hit Wicket',
}

export interface BallEvent {
  runs: number; // Runs off bat
  extraRuns: number; // Runs from extras
  extraType: ExtraType;
  isWicket: boolean;
  wicketType?: WicketType;
  batsmanId: string;
  bowlerId: string;
  description: string;
  timestamp: number;
  isLegalBall: boolean;
  inningsNumber: 1 | 2;
}

export interface WicketDetails {
  type: WicketType;
  fielderName?: string;
  isStrikerOut: boolean;
}

export interface MatchState {
  battingTeam: Team;
  bowlingTeam: Team;
  tossWinner: string;
  tossDecision: 'bat' | 'bowl';
  totalOvers: number;
  currentOver: number;
  currentBall: number; // Legal balls in current over (0-5)
  totalRuns: number;
  wickets: number;
  extras: Extras;
  strikerId: string;
  nonStrikerId: string;
  currentBowlerId: string;
  ballHistory: BallEvent[];
  matchStatus: 'LIVE' | 'INNINGS_BREAK' | 'COMPLETED';

  // New fields for 2 innings support
  inningsNumber: 1 | 2;
  target?: number; // Only for 2nd innings
  firstInningsScore?: {
    runs: number;
    wickets: number;
    overs: string;
    teamName: string;
  };
}

import { SavedTeam } from '../types';

const TEAMS_KEY = 'cricket_app_teams';

export const getSavedTeams = (): SavedTeam[] => {
  try {
    const data = localStorage.getItem(TEAMS_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error("Failed to load teams", error);
    return [];
  }
};

export const saveTeam = (team: SavedTeam) => {
  const teams = getSavedTeams();
  // Check if update or new
  const index = teams.findIndex(t => t.id === team.id);
  if (index >= 0) {
    teams[index] = team;
  } else {
    teams.push(team);
  }
  localStorage.setItem(TEAMS_KEY, JSON.stringify(teams));
};

export const deleteTeam = (teamId: string) => {
  const teams = getSavedTeams().filter(t => t.id !== teamId);
  localStorage.setItem(TEAMS_KEY, JSON.stringify(teams));
};

export const seedDefaultTeams = () => {
  const teams = getSavedTeams();
  if (teams.length === 0) {
    const defaultTeam: SavedTeam = {
      id: 'taxila-tigers-default',
      name: 'Taxila Tigers',
      logoUrl: 'https://files.oaiusercontent.com/file-2p5s5S4jKqvqYw',
      squad: Array.from({ length: 15 }, (_, i) => `Tiger Player ${i + 1}`)
    };
    saveTeam(defaultTeam);
  }
};

