    setLogoUrl('');
    setSquadText('');
  };

  const handleEdit = (team: SavedTeam) => {
    setEditingTeam(team);
    setName(team.name);
    setLogoUrl(team.logoUrl || '');
    setSquadText(team.squad.join('\n'));
  };

  const handleDelete = (id: string) => {
    if (confirm("Are you sure you want to delete this team?")) {
      deleteTeam(id);
      loadTeams();
    }
  };

  const handleSave = () => {
    if (!name.trim()) return alert("Team name is required");

    const squadList = squadText.split('\n').map(s => s.trim()).filter(s => s !== '');
    if (squadList.length < 11) return alert("Please add at least 11 players to the squad.");

    const newTeam: SavedTeam = {
      id: editingTeam?.id || Date.now().toString(),
      name,
      logoUrl,
      squad: squadList
    };

    saveTeam(newTeam);
    loadTeams();
    setEditingTeam(null);
  };

  if (editingTeam) {
    return (
      <div className="flex flex-col h-full bg-tiger-black text-white p-6 overflow-y-auto">
        <div className="flex items-center gap-4 mb-6">
          <button onClick={() => setEditingTeam(null)} className="p-2 rounded-full hover:bg-gray-800">
             <ArrowLeft size={24} />
          </button>
          <h2 className="text-xl font-bold text-tiger-gold">{editingTeam.name ? 'Edit Team' : 'Create New Team'}</h2>
        </div>

        <div className="space-y-6 max-w-2xl mx-auto w-full">
           <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 space-y-4">
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Team Name</label>
                <input 
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-gray-900 border border-gray-600 rounded-lg p-3 outline-none focus:border-tiger-gold"
                  placeholder="e.g. Taxila Tigers"
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Logo URL (Optional)</label>
                <div className="flex gap-2">
                   <div className="flex-1">
                      <input 
                        value={logoUrl}
                        onChange={(e) => setLogoUrl(e.target.value)}
                        className="w-full bg-gray-900 border border-gray-600 rounded-lg p-3 outline-none focus:border-tiger-gold text-sm"
                        placeholder="https://..."
                      />
                   </div>
                   {logoUrl && (
                     <div className="w-12 h-12 rounded-lg bg-black overflow-hidden border border-gray-600">
                        <img src={logoUrl} alt="Preview" className="w-full h-full object-cover" onError={(e) => e.currentTarget.style.display = 'none'} />
                     </div>
                   )}
                </div>
              </div>
           </div>

           <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 h-96 flex flex-col">
              <label className="block text-xs font-bold uppercase text-gray-500 mb-2 flex justify-between">
                <span>Squad List (One per line)</span>
                <span className="text-tiger-gold">{squadText.split('\n').filter(s => s.trim()).length} Players</span>
              </label>
              <textarea 
                value={squadText}
                onChange={(e) => setSquadText(e.target.value)}
                className="flex-1 w-full bg-gray-900 border border-gray-600 rounded-lg p-3 outline-none focus:border-tiger-gold font-mono text-sm leading-relaxed resize-none"
                placeholder={`Player 1\nPlayer 2\n...`}
              />
           </div>

           <button 
             onClick={handleSave}
             className="w-full py-4 bg-gradient-to-r from-tiger-gold to-tiger-orange text-black font-black uppercase rounded-xl shadow-lg flex items-center justify-center gap-2 hover:brightness-110"
           >
             <Save size={20} /> Save Team
           </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-tiger-black text-white p-6">
      <div className="flex items-center justify-between mb-6">
         <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2 rounded-full hover:bg-gray-800">
              <ArrowLeft size={24} />
            </button>
            <h2 className="text-xl font-bold text-white">Manage Teams</h2>
         </div>
         <button 
           onClick={handleCreateNew}
           className="bg-tiger-gold text-black px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-yellow-400"
         >
           <Plus size={16} /> Add Team
         </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 overflow-y-auto">
         {teams.length === 0 ? (
           <div className="col-span-2 text-center py-20 text-gray-500">
             No teams found. Create one to get started!
           </div>
         ) : (
           teams.map(team => (
             <div key={team.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex items-center justify-between group hover:border-tiger-gold/50 transition-all">
                <div className="flex items-center gap-4">
                   <div className="w-16 h-16 rounded-full bg-black border-2 border-gray-600 flex items-center justify-center overflow-hidden">
                      {team.logoUrl ? (
                        <img src={team.logoUrl} alt={team.name} className="w-full h-full object-cover" />
                      ) : (
                        <Users className="text-gray-600" />
                      )}
                   </div>
                   <div>
                      <h3 className="font-bold text-white text-lg">{team.name}</h3>
                      <p className="text-xs text-gray-400">{team.squad.length} Players in Squad</p>
