};

import React, { useState, useEffect } from 'react';
import { Trophy, BarChart2, Users, PlusCircle, Settings } from 'lucide-react';
import { getSavedTeams, seedDefaultTeams } from '../utils/storage';
import { SavedTeam } from '../types';

interface Props {
  onNext: (home: SavedTeam, away: SavedTeam, overs: number) => void;
  onViewStats: () => void;
  onManageTeams: () => void;
}

