import React, { useState } from 'react';
import { CheckCircle2, Circle, UserPlus, Users } from 'lucide-react';
import { SavedTeam } from '../types';

interface Props {
  homeTeam: SavedTeam;
  awayTeam: SavedTeam;
  onConfirm: (homeXI: string[], awayXI: string[], homeReserves: string[], awayReserves: string[]) => void;
  onBack: () => void;
}

export const SquadSelection: React.FC<Props> = ({ 
  homeTeam, awayTeam, onConfirm, onBack 
}) => {
  // State stores arrays of player names
  const [homePlaying, setHomePlaying] = useState<string[]>([]);
  const [homeReserves, setHomeReserves] = useState<string[]>([]);

  const [awayPlaying, setAwayPlaying] = useState<string[]>([]);
  const [awayReserves, setAwayReserves] = useState<string[]>([]);

  const [activeTab, setActiveTab] = useState<'home' | 'away'>('home');

  const toggleSelection = (player: string, isHome: boolean) => {
    const playing = isHome ? homePlaying : awayPlaying;
    const reserves = isHome ? homeReserves : awayReserves;
    const setPlaying = isHome ? setHomePlaying : setAwayPlaying;
    const setReserves = isHome ? setHomeReserves : setAwayReserves;

    // If already in playing, move to unselected
    if (playing.includes(player)) {
      setPlaying(playing.filter(p => p !== player));
      return;
    }

    // If already in reserves, move to unselected
    if (reserves.includes(player)) {
      setReserves(reserves.filter(p => p !== player));
      return;
    }

    // Logic to add: Fill playing (11) first, then reserves (2)
    if (playing.length < 11) {
      setPlaying([...playing, player]);
    } else if (reserves.length < 2) {
      setReserves([...reserves, player]);
    } else {
      alert("Selection Full! (11 Playing + 2 Reserves)");
    }
  };

  const handleConfirm = () => {
    if (homePlaying.length !== 11 || awayPlaying.length !== 11) {
      alert("You must select exactly 11 playing members for each team.");
      return;
    }
    // We strictly check playing 11, reserves are optional but prompt encouraged 2
    onConfirm(homePlaying, awayPlaying, homeReserves, awayReserves);
  };

  const currentTeam = activeTab === 'home' ? homeTeam : awayTeam;
  const currentPlaying = activeTab === 'home' ? homePlaying : awayPlaying;
  const currentReserves = activeTab === 'home' ? homeReserves : awayReserves;

  return (
    <div className="flex flex-col h-full bg-tiger-black text-white p-4">
      <div className="mb-4 text-center">
        <h2 className="text-xl font-bold text-tiger-gold uppercase tracking-wider">Select Squads</h2>
        <p className="text-gray-400 text-xs mt-1">Select 11 Playing & 2 Reserves</p>
      </div>

      <div className="flex mb-4 bg-gray-800 p-1 rounded-lg">
        <button 
          onClick={() => setActiveTab('home')}
          className={`flex-1 py-2 rounded-md text-sm font-bold transition-all flex items-center justify-center gap-2 ${activeTab === 'home' ? 'bg-tiger-gold text-black shadow' : 'text-gray-400'}`}
        >
          {homeTeam.name} 
          <span className="text-[10px] bg-black/20 px-2 rounded-full font-mono">{homePlaying.length + homeReserves.length}/13</span>
        </button>
        <button 
          onClick={() => setActiveTab('away')}
          className={`flex-1 py-2 rounded-md text-sm font-bold transition-all flex items-center justify-center gap-2 ${activeTab === 'away' ? 'bg-tiger-gold text-black shadow' : 'text-gray-400'}`}
        >
          {awayTeam.name} 
          <span className="text-[10px] bg-black/20 px-2 rounded-full font-mono">{awayPlaying.length + awayReserves.length}/13</span>
        </button>
      </div>

      {/* Stats Bar */}
      <div className="flex justify-between px-4 py-2 bg-gray-900 rounded-lg mb-2 text-xs font-bold uppercase tracking-wider">
         <div className="text-tiger-gold">Playing XI: {currentPlaying.length}/11</div>
         <div className="text-blue-400">Reserves: {currentReserves.length}/2</div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-2 bg-gray-900/50 p-2 rounded-xl border border-gray-800">
        {currentTeam.squad.map((player, idx) => {
          const isPlaying = currentPlaying.includes(player);
          const isReserve = currentReserves.includes(player);

          let statusColor = "bg-gray-800/50 border-gray-700 text-gray-500";
          let icon = <Circle size={20} />;

          if (isPlaying) {
             statusColor = "bg-tiger-gold/20 border-tiger-gold text-white";
             icon = <CheckCircle2 className="text-tiger-gold" size={20} />;
          } else if (isReserve) {
             statusColor = "bg-blue-900/30 border-blue-500 text-blue-200";
             icon = <UserPlus className="text-blue-400" size={20} />;
          }

          return (
            <button
              key={idx}
              onClick={() => toggleSelection(player, activeTab === 'home')}
              className={`w-full p-3 rounded-lg flex justify-between items-center transition-all border ${statusColor} hover:brightness-110`}
            >
              <span className="font-semibold">{player}</span>
              <div className="flex items-center gap-2">
                 {isPlaying && <span className="text-[10px] font-bold uppercase text-tiger-gold">Playing</span>}
                 {isReserve && <span className="text-[10px] font-bold uppercase text-blue-400">Reserve</span>}
                 {icon}
              </div>
            </button>
          );
        })}
      </div>

      <div className="mt-4 flex gap-4">
        <button onClick={onBack} className="flex-1 py-4 bg-gray-800 text-white rounded-xl font-bold">Back</button>
        <button 
          onClick={handleConfirm}
          className="flex-[2] py-4 bg-gradient-to-r from-tiger-gold to-tiger-orange text-black rounded-xl font-bold shadow-lg disabled:opacity-50"
          disabled={homePlaying.length !== 11 || awayPlaying.length !== 11}
        >
          Confirm Squads
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { MatchSetup } from './components/MatchSetup';
import { SquadSelection } from './components/SquadSelection';
import { TossScreen } from './components/TossScreen';
import { OpenerSelection } from './components/OpenerSelection';
import { ScoringDashboard } from './components/ScoringDashboard';
import { InningsBreak } from './components/InningsBreak';
import { StatsDashboard } from './components/StatsDashboard';
import { TeamManager } from './components/TeamManager';
import { MatchState, Player, Team, SavedTeam } from './types';
import { MatchSummary } from './components/MatchSummary';

interface SetupData {
  homeTeam: SavedTeam;
  awayTeam: SavedTeam;
  overs: number;
  homeXI?: string[]; 
  awayXI?: string[];
  homeReserves?: string[]; // Stored but not currently used in match logic
  awayReserves?: string[];
}

const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'team-manager' | 'squad-select' | 'toss' | 'openers' | 'scoring' | 'innings-break' | 'summary' | 'stats'>('setup');
  const [matchState, setMatchState] = useState<MatchState | null>(null);
  const [setupData, setSetupData] = useState<SetupData | null>(null);
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);
  const [history, setHistory] = useState<MatchState[]>([]);

  // 1. Initial Setup
  const handleSetupComplete = (
    homeTeam: SavedTeam,
    awayTeam: SavedTeam,
    overs: number
  ) => {
    setSetupData({ homeTeam, awayTeam, overs });
    setView('squad-select');
  };

  // 2. Select 11 Players + Reserves
  const handleSquadConfirm = (homeXI: string[], awayXI: string[], homeReserves: string[], awayReserves: string[]) => {
    setSetupData(prev => prev ? ({ ...prev, homeXI, awayXI, homeReserves, awayReserves }) : null);
    setView('toss');
  };

  // 3. Toss Logic
  const handleTossComplete = (winner: string, decision: 'bat' | 'bowl') => {
    if (!setupData || !setupData.homeXI || !setupData.awayXI) return;

    const isHomeBattingFirst = (winner === setupData.homeTeam.name && decision === 'bat') || (winner === setupData.awayTeam.name && decision === 'bowl');

    const battingTeamPlayers = isHomeBattingFirst ? setupData.homeXI : setupData.awayXI;
    const bowlingTeamPlayers = isHomeBattingFirst ? setupData.awayXI : setupData.homeXI;
    const battingTeamObj = isHomeBattingFirst ? setupData.homeTeam : setupData.awayTeam;
    const bowlingTeamObj = isHomeBattingFirst ? setupData.awayTeam : setupData.homeTeam;

    const battingTeam: Team = {
      name: battingTeamObj.name,
      logoUrl: battingTeamObj.logoUrl,
      players: battingTeamPlayers.map((name, id) => ({ id: `bat${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: true,
    };

    const bowlingTeam: Team = {
      name: bowlingTeamObj.name,
      logoUrl: bowlingTeamObj.logoUrl,
      players: bowlingTeamPlayers.map((name, id) => ({ id: `bowl${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: false,
    };

    const initialState: MatchState = {
      battingTeam,
      bowlingTeam,
      tossWinner: winner,
      tossDecision: decision,
      totalOvers: setupData.overs,
      currentOver: 0,
      currentBall: 0,
      totalRuns: 0,
      wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: '', 
      nonStrikerId: '', 
      currentBowlerId: '', 
      ballHistory: [],
      matchStatus: 'LIVE',
      inningsNumber: 1
    };

    setMatchState(initialState);
    setView('openers');
  };

  // 4. Start Innings
  const handleStartInnings = (strikerId: string, nonStrikerId: string, bowlerId: string) => {
    if (!matchState) return;
    setMatchState({
      ...matchState,
      strikerId,
      nonStrikerId,
      currentBowlerId: bowlerId,
      matchStatus: 'LIVE'
    });
    setView('scoring');
  };

  // 5. Innings/Match Flow
  const handleScoringFinish = () => {
    if (!matchState) return;
    if (matchState.matchStatus === 'INNINGS_BREAK') {
      setView('innings-break');
    } else if (matchState.matchStatus === 'COMPLETED') {
      setView('summary');
    }
  };

  // 6. Start 2nd Innings
  const handleStartSecondInnings = () => {
    if (!matchState) return;

    const oldBatting = matchState.battingTeam;
    const oldBowling = matchState.bowlingTeam;

    // Swap Roles
    const newBattingTeam: Team = { ...oldBowling, isBatting: true };
    const newBowlingTeam: Team = { ...oldBatting, isBatting: false };

    const newState: MatchState = {
      ...matchState,
      battingTeam: newBattingTeam,
      bowlingTeam: newBowlingTeam,
      totalRuns: 0,
      wickets: 0,
      currentOver: 0,
      currentBall: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: '',
      nonStrikerId: '',
      currentBowlerId: '',
      inningsNumber: 2,
      target: matchState.totalRuns + 1,
      matchStatus: 'LIVE'
    };

    setMatchState(newState);
    setHistory([]);
    setView('openers');
  };

  const handleUpdateScore = (newState: MatchState) => {
    if (matchState) setHistory(prev => [...prev, matchState].slice(-50));
    setMatchState(newState);
  };

  const handleUndo = () => {
    if (history.length === 0) return;
    const previousState = history[history.length - 1];
    setHistory(prev => prev.slice(0, -1));
    setMatchState(previousState);
  };

  const handleSaveAndExit = (finalState: MatchState) => {
    setMatchHistory(prev => [...prev, finalState]);
    setView('setup');
  };

  return (
    <div className="h-screen w-full bg-tiger-black text-white flex flex-col font-sans">
      {view === 'setup' && (
        <MatchSetup 
          onNext={handleSetupComplete} 
          onViewStats={() => setView('stats')}
          onManageTeams={() => setView('team-manager')}
        />
      )}

      {view === 'team-manager' && (
        <TeamManager onBack={() => setView('setup')} />
      )}

      {view === 'squad-select' && setupData && (
        <SquadSelection
           homeTeam={setupData.homeTeam}
           awayTeam={setupData.awayTeam}
           onConfirm={handleSquadConfirm}
           onBack={() => setView('setup')}
        />
      )}

      {view === 'toss' && setupData && (
        <TossScreen 
          homeTeam={setupData.homeTeam.name} 
          awayTeam={setupData.awayTeam.name} 
          onTossComplete={handleTossComplete}
          onBack={() => setView('setup')}
        />
      )}

      {view === 'openers' && matchState && (
        <OpenerSelection
          inningsNumber={matchState.inningsNumber}
          battingTeamName={matchState.battingTeam.name}
          bowlingTeamName={matchState.bowlingTeam.name}
          battingPlayers={matchState.battingTeam.players}
          bowlingPlayers={matchState.bowlingTeam.players}
          onStart={handleStartInnings}
        />
      )}

      {view === 'scoring' && matchState && (
        <ScoringDashboard 
          matchState={matchState} 
          setMatchState={handleUpdateScore} 
          onUndo={handleUndo}
          canUndo={history.length > 0}
          onFinish={handleScoringFinish}
        />
      )}

      {view === 'innings-break' && matchState && (
        <InningsBreak 
          matchState={matchState}
          onStartSecondInnings={handleStartSecondInnings}
        />
      )}

      {view === 'summary' && matchState && (
        <MatchSummary 
          matchState={matchState} 
          onSaveAndExit={handleSaveAndExit} 
        />
      )}

      {view === 'stats' && (
        <StatsDashboard 
          matchHistory={matchHistory} 
          onBack={() => setView('setup')} 
        />
      )}
    </div>
  );
};

