interface Props {
  matchHistory: MatchState[];
  onBack: () => void;
}

export const StatsDashboard: React.FC<Props> = ({ matchHistory, onBack }) => {
  const [activeTab, setActiveTab] = useState<'players' | 'matches'>('players');
  const [sortBy, setSortBy] = useState<'runs' | 'wickets'>('runs');
  const HOME_TEAM_NAME = 'Taxila Tigers';

  // Pass the home team name filter to the aggregator
  const playerStats = useMemo(() => aggregateStats(matchHistory, HOME_TEAM_NAME), [matchHistory]);

  const sortedPlayers = useMemo(() => {
    return [...playerStats].sort((a, b) => {
      if (sortBy === 'runs') return b.runs - a.runs;
      return b.wickets - a.wickets;
    });
  }, [playerStats, sortBy]);

  // Helper to determine match result string
  const getMatchResult = (match: MatchState) => {
    if (match.matchStatus !== 'COMPLETED') return { text: 'In Progress / Abandoned', color: 'text-gray-500' };

    // In our 2-innings logic:
    // firstInningsScore holds the score of the team that batted first.
    // match.battingTeam holds the team that batted second (chasing).

    if (!match.firstInningsScore) return { text: 'Result Unknown', color: 'text-gray-500' };

    const teamBattingFirst = match.firstInningsScore.teamName;
    const teamBattingSecond = match.battingTeam.name;
    const scoreFirst = match.firstInningsScore.runs;
    const scoreSecond = match.totalRuns;

    let winner = '';
    let margin = '';

    if (scoreSecond > scoreFirst) {
      winner = teamBattingSecond;
      margin = `${10 - match.wickets} wickets`;
    } else if (scoreFirst > scoreSecond) {
      winner = teamBattingFirst;
      margin = `${scoreFirst - scoreSecond} runs`;
    } else {
      return { text: 'Match Tied', color: 'text-gray-400' };
    }

    const isWin = winner === HOME_TEAM_NAME;

    // Construct text relative to Taxila Tigers
    if (winner === HOME_TEAM_NAME) {
       return { text: `Won by ${margin}`, color: 'text-green-400' };
    } else {
       // If the opponent won, we say "Loss by..."
       return { text: `Lost by ${margin}`, color: 'text-red-400' };
    }
  };

  return (
    <div className="flex flex-col h-full bg-tiger-black text-white font-sans">
      {/* Header */}
      <div className="bg-tiger-card p-4 border-b border-gray-700 flex items-center gap-4">
        <button onClick={onBack} className="p-2 rounded-full hover:bg-gray-700 transition-colors">
          <ArrowLeft size={20} className="text-tiger-gold" />
        </button>
        <h2 className="text-xl font-bold text-white">Taxila Tigers Statistics</h2>
      </div>

      {/* Tabs */}
      <div className="flex bg-gray-900 p-2">
        <button 
          onClick={() => setActiveTab('players')}
          className={`flex-1 py-3 font-bold text-sm uppercase tracking-wider border-b-2 transition-all ${activeTab === 'players' ? 'border-tiger-gold text-tiger-gold' : 'border-transparent text-gray-500'}`}
        >
          Player Stats
        </button>
        <button 
          onClick={() => setActiveTab('matches')}
          className={`flex-1 py-3 font-bold text-sm uppercase tracking-wider border-b-2 transition-all ${activeTab === 'matches' ? 'border-tiger-gold text-tiger-gold' : 'border-transparent text-gray-500'}`}
        >
          Match History
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        {activeTab === 'players' ? (
          <div className="space-y-4">
            <div className="flex gap-2 mb-4">
              <button 
                onClick={() => setSortBy('runs')}
                className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase border ${sortBy === 'runs' ? 'bg-tiger-gold text-black border-tiger-gold' : 'bg-transparent text-gray-400 border-gray-600'}`}
              >
                Top Run Scorers
              </button>
              <button 
                onClick={() => setSortBy('wickets')}
                className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase border ${sortBy === 'wickets' ? 'bg-tiger-gold text-black border-tiger-gold' : 'bg-transparent text-gray-400 border-gray-600'}`}
              >
                Top Wicket Takers
              </button>
            </div>

            {/* Table Header */}
            <div className="grid grid-cols-12 text-[10px] uppercase font-bold text-gray-500 px-2 mb-1">
              <div className="col-span-5">Player</div>
              <div className="col-span-2 text-center">Mat</div>
              <div className="col-span-2 text-center">{sortBy === 'runs' ? 'Runs' : 'Wkts'}</div>
              <div className="col-span-3 text-right">{sortBy === 'runs' ? 'High' : 'Best'}</div>
            </div>

            <div className="space-y-2">
              {sortedPlayers.length === 0 ? (
                 <div className="text-center text-gray-500 py-10">No stats available for {HOME_TEAM_NAME}.</div>
              ) : (
                sortedPlayers.map((p, idx) => (
                  <div key={p.name} className="grid grid-cols-12 items-center bg-gray-800 p-3 rounded-lg border border-gray-700 shadow-sm">
                    <div className="col-span-5 flex items-center gap-2">
                      <span className={`w-5 h-5 flex items-center justify-center rounded-full text-[10px] font-bold ${idx < 3 ? 'bg-tiger-gold text-black' : 'bg-gray-700 text-gray-400'}`}>
                        {idx + 1}
                      </span>
                      <span className="font-semibold text-sm truncate">{p.name}</span>
                    </div>
                    <div className="col-span-2 text-center text-gray-400 text-sm">{p.matches}</div>
                    <div className="col-span-2 text-center font-bold text-tiger-gold text-sm">
                      {sortBy === 'runs' ? p.runs : p.wickets}
                    </div>
                    <div className="col-span-3 text-right text-xs text-gray-400 font-mono">
                      {sortBy === 'runs' ? `${p.highestScore}` : `${p.bestBowling.wickets}/${p.bestBowling.runs}`}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        ) : (
          <div className="space-y-4">
             {matchHistory.length === 0 ? (
                <div className="text-center text-gray-500 py-10">No matches played yet.</div>
             ) : (
               matchHistory.slice().reverse().map((match, idx) => {
                 const result = getMatchResult(match);
                 const date = new Date(match.ballHistory[0]?.timestamp || Date.now()).toLocaleDateString();

                 return (
                   <div key={idx} className="bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-lg">
                     <div className="flex justify-between items-center mb-2">
                       <span className="text-[10px] font-bold text-gray-500 uppercase flex items-center gap-1">
                         <Calendar size={10} /> {date}
                       </span>
                       <span className={`text-[10px] px-2 py-0.5 rounded border font-bold uppercase ${result.color} bg-black/20 border-current`}>
                         {result.text}
                       </span>
                     </div>
                     <div className="flex justify-between items-end">
                        <div className="flex-1">
                           {/* Display Score Summary nicely */}
                           {match.firstInningsScore && (
                             <div className="flex justify-between text-xs text-gray-400 mb-1">
                               <span>{match.firstInningsScore.teamName}</span>
                               <span className="font-mono">{match.firstInningsScore.runs}/{match.firstInningsScore.wickets} ({match.firstInningsScore.overs})</span>
                             </div>
                           )}
                           <div className="flex justify-between text-sm font-bold text-white">
                               <span>{match.battingTeam.name}</span>
                               <span className="font-mono text-tiger-gold">{match.totalRuns}/{match.wickets} ({match.currentOver}.{match.currentBall})</span>
                           </div>
                        </div>
                     </div>
                     <div className="mt-3 pt-2 border-t border-gray-700 text-[10px] text-gray-500 flex justify-between">
                        <span>vs {match.battingTeam.name === HOME_TEAM_NAME ? match.bowlingTeam.name : match.battingTeam.name}</span>
                        <span>{match.totalOvers} Overs Match</span>
                     </div>
                   </div>
                 );
               })
             )}
          </div>
        )}
      </div>
    </div>
  );
};

