export const TeamManager: React.FC<Props> = ({ onBack }) => {
  const [teams, setTeams] = useState<SavedTeam[]>([]);
  const [editingTeam, setEditingTeam] = useState<SavedTeam | null>(null);

  // Form State
  const [name, setName] = useState('');
  const [logoUrl, setLogoUrl] = useState('');
  const [squadText, setSquadText] = useState('');

  useEffect(() => {
    loadTeams();
  }, []);

  const loadTeams = () => {
    setTeams(getSavedTeams());
  };

  const handleCreateNew = () => {
    setEditingTeam({
      id: Date.now().toString(),
      name: '',
      logoUrl: '',
      squad: []
    });
    setName('');
    setLogoUrl('');
    setSquadText('');
  };

  const handleEdit = (team: SavedTeam) => {
    setEditingTeam(team);
    setName(team.name);
    setLogoUrl(team.logoUrl || '');
    setSquadText(team.squad.join('\n'));
  };

  const handleDelete = (id: string) => {
    if (confirm("Are you sure you want to delete this team?")) {
      deleteTeam(id);
      loadTeams();
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Limit file size to 500KB to prevent localStorage quota exceeded errors
      if (file.size > 500 * 1024) {
        alert("Image is too large. Please upload a logo smaller than 500KB.");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        setLogoUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!name.trim()) return alert("Team name is required");

    const squadList = squadText.split('\n').map(s => s.trim()).filter(s => s !== '');
    if (squadList.length < 11) return alert("Please add at least 11 players to the squad.");

    const newTeam: SavedTeam = {
      id: editingTeam?.id || Date.now().toString(),
      name,
      logoUrl,
      squad: squadList
    };

    saveTeam(newTeam);
    loadTeams();
    setEditingTeam(null);
  };

  if (editingTeam) {
    return (
      <div className="flex flex-col h-full bg-tiger-black text-white p-6 overflow-y-auto">
        <div className="flex items-center gap-4 mb-6">
          <button onClick={() => setEditingTeam(null)} className="p-2 rounded-full hover:bg-gray-800">
             <ArrowLeft size={24} />
          </button>
          <h2 className="text-xl font-bold text-tiger-gold">{editingTeam.name ? 'Edit Team' : 'Create New Team'}</h2>
        </div>

        <div className="space-y-6 max-w-2xl mx-auto w-full">
           <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 space-y-4">
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Team Name</label>
                <input 
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-gray-900 border border-gray-600 rounded-lg p-3 outline-none focus:border-tiger-gold"
                  placeholder="e.g. Taxila Tigers"
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Team Logo</label>
                <div className="flex flex-col gap-4">
                   {/* Input Row */}
                   <div className="flex gap-2">
                      <input 
                        value={logoUrl}
                        onChange={(e) => setLogoUrl(e.target.value)}
                        className="flex-1 bg-gray-900 border border-gray-600 rounded-lg p-3 outline-none focus:border-tiger-gold text-sm"
                        placeholder="Paste URL or upload image..."
                      />
                      <label className="cursor-pointer bg-gray-700 hover:bg-gray-600 text-white px-4 rounded-lg flex items-center gap-2 transition-colors border border-gray-600">
                         <Upload size={18} />
                         <span className="text-xs font-bold uppercase hidden sm:inline">Upload</span>
                         <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                      </label>
                   </div>

                   {/* Preview Row */}
                   {logoUrl && (
                     <div className="flex items-center gap-4 bg-gray-900/50 p-3 rounded-xl border border-gray-700/50">
                        <div className="w-20 h-20 rounded-full bg-black overflow-hidden border-2 border-tiger-gold shadow-lg flex-shrink-0 relative group">
                           <img src={logoUrl} alt="Preview" className="w-full h-full object-cover" onError={(e) => e.currentTarget.style.display = 'none'} />
                        </div>
                        <div className="flex-1">
                           <p className="font-bold text-white text-sm">Logo Preview</p>
                           <p className="text-xs text-gray-500 mt-1">This logo will appear on the scorecard.</p>
                           <button onClick={() => setLogoUrl('')} className="text-red-400 hover:text-red-300 text-xs font-bold mt-2 uppercase flex items-center gap-1">
                              <Trash2 size={12} /> Remove
                           </button>
                        </div>
                     </div>
                   )}
                </div>
              </div>
           </div>

           <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 h-96 flex flex-col">
              <label className="block text-xs font-bold uppercase text-gray-500 mb-2 flex justify-between">
                <span>Squad List (One per line)</span>
                <span className="text-tiger-gold">{squadText.split('\n').filter(s => s.trim()).length} Players</span>
              </label>
              <textarea 
