const getApiKey = () => {
  try {
    // @ts-ignore
    return process.env.API_KEY || '';
  } catch (e) {
    return '';
  }
};

const API_KEY = getApiKey();

let ai: GoogleGenAI | null = null;
if (API_KEY) {
  ai = new GoogleGenAI({ apiKey: API_KEY });
}

export const generateCommentary = async (lastBall: BallEvent, state: MatchState): Promise<string> => {
  if (!ai) return "Gemini AI: Add API Key to env to enable commentary.";

  const prompt = `
    Context: Cricket Match. 
    Score: ${state.totalRuns}/${state.wickets} in ${state.currentOver}.${state.currentBall} overs.
    Last Event: ${lastBall.description}.
    Batsman: ${lastBall.runs} runs scored.

    Write a short, exciting, professional cricket commentary line (max 15 words) for this specific ball. 
    Style: Ian Bishop or Ravi Shastri.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text ? response.text.trim() : "What a play!";
  } catch (error) {
    console.log("Gemini Error:", error);
    return "What a delivery!";
  }
};

export const askRuleQuestion = async (query: string): Promise<string> => {
  if (!ai) return "AI service unavailable. Check API Key.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `Answer this cricket rule question briefly based on ICC Playing Conditions: ${query}`,
    });
    return response.text ? response.text.trim() : "Rule check failed.";
  } catch (error) {
    return "Unable to fetch rule.";
  }
};

export const generateMatchSummary = async (state: MatchState): Promise<string> => {
  if (!ai) return "AI service unavailable.";

  const summaryData = {
    score: `${state.totalRuns}/${state.wickets}`,
    overs: `${state.currentOver}.${state.currentBall}`,
    topBatters: state.battingTeam.players.sort((a,b) => b.runs - a.runs).slice(0, 2).map(p => `${p.name} (${p.runs})`),
    keyEvents: state.ballHistory.filter(b => b.isWicket || b.runs >= 4).length
  };

  const prompt = `Write a 2-sentence post-match summary for a cricket match. Data: ${JSON.stringify(summaryData)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text || "Match Completed.";
  } catch (error) {
    return "Match concluded.";
  }
};

import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, TextInput, Image, ScrollView, Alert, Modal } from 'react-native';
import { SavedTeam } from '../types';
import { getSavedTeams, saveTeam, deleteTeam } from '../utils/storage';
import { Plus, Trash2, Edit2, ArrowLeft, Save, Users, Upload } from 'lucide-react-native';

interface Props {
  onBack: () => void;
}

export const TeamManager: React.FC<Props> = ({ onBack }) => {
  const [teams, setTeams] = useState<SavedTeam[]>([]);
  const [editingTeam, setEditingTeam] = useState<SavedTeam | null>(null);

  // Form State
  const [name, setName] = useState('');
  const [logoUrl, setLogoUrl] = useState('');
  const [squadText, setSquadText] = useState('');

  useEffect(() => {
    loadTeams();
  }, []);

  const loadTeams = async () => {
    const saved = await getSavedTeams();
    setTeams(saved);
  };

  const handleCreateNew = () => {
    setEditingTeam({
      id: Date.now().toString(),
      name: '',
      logoUrl: '',
      squad: []
    });
    setName('');
    setLogoUrl('');
    setSquadText('');
  };

  const handleEdit = (team: SavedTeam) => {
    setEditingTeam(team);
    setName(team.name);
    setLogoUrl(team.logoUrl || '');
    setSquadText(team.squad.join('\n'));
  };

  const handleDelete = async (id: string) => {
    Alert.alert("Delete Team", "Are you sure you want to delete this team?", [
      { text: "Cancel", style: "cancel" },
      { 
        text: "Delete", 
        style: "destructive", 
        onPress: async () => {
          await deleteTeam(id);
          loadTeams();
        }
      }
    ]);
  };

  const handleSave = async () => {
    if (!name.trim()) return Alert.alert("Error", "Team name is required");

    const squadList = squadText.split('\n').map(s => s.trim()).filter(s => s !== '');
    if (squadList.length < 11) return Alert.alert("Error", "Please add at least 11 players to the squad.");

    const newTeam: SavedTeam = {
      id: editingTeam?.id || Date.now().toString(),
      name,
      logoUrl,
      squad: squadList
    };

    await saveTeam(newTeam);
    loadTeams();
    setEditingTeam(null);
  };

  if (editingTeam) {
    return (
      <View className="flex-1 bg-tiger-black">
        <View className="flex-row items-center gap-4 p-4 border-b border-gray-800">
          <TouchableOpacity onPress={() => setEditingTeam(null)} className="p-2 rounded-full bg-gray-800">
             <ArrowLeft size={24} color="white" />
          </TouchableOpacity>
          <Text className="text-xl font-bold text-tiger-gold">{editingTeam.name ? 'Edit Team' : 'Create New Team'}</Text>
        </View>

        <ScrollView className="flex-1 p-4" contentContainerStyle={{ paddingBottom: 40 }}>
           <View className="bg-gray-800 p-4 rounded-xl border border-gray-700 space-y-4 mb-4">
              <View>
                <Text className="text-xs font-bold uppercase text-gray-500 mb-1">Team Name</Text>
                <TextInput 
                  value={name}
                  onChangeText={setName}
                  className="w-full bg-gray-900 border border-gray-600 rounded-lg p-3 text-white"
                  placeholder="e.g. Taxila Tigers"
                  placeholderTextColor="#6b7280"
                />
              </View>
              <View>
                <Text className="text-xs font-bold uppercase text-gray-500 mb-2">Team Logo URL</Text>
                <TextInput 
                  value={logoUrl}
                  onChangeText={setLogoUrl}
                  className="bg-gray-900 border border-gray-600 rounded-lg p-3 text-white text-sm"
                  placeholder="Paste image URL..."
                  placeholderTextColor="#6b7280"
                />

                {/* Preview Row */}
                {logoUrl ? (
                  <View className="flex-row items-center gap-4 bg-gray-900/50 p-3 rounded-xl border border-gray-700/50 mt-4">
                     <View className="w-20 h-20 rounded-full bg-black overflow-hidden border-2 border-tiger-gold shadow-lg">
                        <Image source={{ uri: logoUrl }} className="w-full h-full" resizeMode="cover" />
                     </View>
                     <View className="flex-1">
                        <Text className="font-bold text-white text-sm">Logo Preview</Text>
                        <TouchableOpacity onPress={() => setLogoUrl('')} className="mt-2">
                           <Text className="text-red-400 text-xs font-bold uppercase">Remove</Text>
                        </TouchableOpacity>
                     </View>
                  </View>
                ) : null}
              </View>
           </View>

           <View className="bg-gray-800 p-4 rounded-xl border border-gray-700 h-96 mb-6">
              <View className="flex-row justify-between mb-2">
                <Text className="text-xs font-bold uppercase text-gray-500">Squad List (One per line)</Text>
                <Text className="text-tiger-gold font-bold">{squadText.split('\n').filter(s => s.trim()).length} Players</Text>
              </View>
              <TextInput 
                value={squadText}
                onChangeText={setSquadText}
                multiline
                textAlignVertical="top"
                className="flex-1 w-full bg-gray-900 border border-gray-600 rounded-lg p-3 text-white font-mono text-sm leading-6"
                placeholder={`Player 1\nPlayer 2\n...`}
                placeholderTextColor="#6b7280"
              />
           </View>

           <TouchableOpacity 
             onPress={handleSave}
             className="w-full py-4 bg-tiger-gold rounded-xl shadow-lg flex-row items-center justify-center gap-2 mb-8"
           >
             <Save size={20} color="black" /> 
             <Text className="text-black font-black uppercase">Save Team</Text>
           </TouchableOpacity>
        </ScrollView>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-tiger-black p-4">
      <View className="flex-row items-center justify-between mb-6 mt-2">
         <View className="flex-row items-center gap-4">
            <TouchableOpacity onPress={onBack} className="p-2 rounded-full bg-gray-800">
              <ArrowLeft size={24} color="white" />
            </TouchableOpacity>
            <Text className="text-xl font-bold text-white">Manage Teams</Text>
         </View>
         <TouchableOpacity 
           onPress={handleCreateNew}
           className="bg-tiger-gold px-4 py-2 rounded-lg flex-row items-center gap-2"
         >
           <Plus size={16} color="black" /> 
           <Text className="text-black font-bold text-sm">Add</Text>
         </TouchableOpacity>
      </View>

      <ScrollView className="flex-1">
         {teams.length === 0 ? (
           <Text className="text-center py-20 text-gray-500">No teams found. Create one to get started!</Text>
         ) : (
           teams.map(team => (
             <View key={team.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex-row items-center justify-between mb-4">
                <View className="flex-row items-center gap-4 flex-1">
                   <View className="w-16 h-16 rounded-full bg-black border-2 border-gray-600 items-center justify-center overflow-hidden">
                      {team.logoUrl ? (
                        <Image source={{ uri: team.logoUrl }} className="w-full h-full" resizeMode="cover" />
                      ) : (
                        <Users size={24} color="#4b5563" />
                      )}
                   </View>
                   <View className="flex-1">
                      <Text className="font-bold text-white text-lg">{team.name}</Text>
                      <Text className="text-xs text-gray-400">{team.squad.length} Players in Squad</Text>
                   </View>
                </View>
                <View className="flex-row gap-2">
                   <TouchableOpacity onPress={() => handleEdit(team)} className="p-3 rounded-lg bg-gray-700">
                     <Edit2 size={16} color="#60a5fa" />
                   </TouchableOpacity>
                   <TouchableOpacity onPress={() => handleDelete(team.id)} className="p-3 rounded-lg bg-gray-700">
                     <Trash2 size={16} color="#f87171" />
                   </TouchableOpacity>
                </View>
             </View>
           ))
         )}
      </ScrollView>
    </View>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Modal, Alert } from 'react-native';
import { MatchState, ExtraType, WicketType, Player, WicketDetails } from '../types';
import { processBall, getPlayer } from '../utils/cricketLogic';
import { generateCommentary, askRuleQuestion } from '../services/geminiService';
import { Mic, Info, RotateCcw, ChevronDown, Trophy } from 'lucide-react-native';

interface Props {
  matchState: MatchState;
  setMatchState: (state: MatchState) => void;
  onUndo: () => void;
  canUndo: boolean;
  onFinish: () => void;
}

export const ScoringDashboard: React.FC<Props> = ({ matchState, setMatchState, onUndo, canUndo, onFinish }) => {
  // Modal States
  const [wicketModalOpen, setWicketModalOpen] = useState(false);
  const [bowlerSelectOpen, setBowlerSelectOpen] = useState(false);

  // Wicket Flow States
  const [selectedWicketType, setSelectedWicketType] = useState<WicketType | null>(null);
  const [selectedFielder, setSelectedFielder] = useState<string>('');
  const [whoIsOut, setWhoIsOut] = useState<'striker' | 'nonStriker'>('striker');

  const [extraType, setExtraType] = useState<ExtraType>(ExtraType.NONE);
  const [commentary, setCommentary] = useState<string>("Waiting for next ball...");
  const [aiLoading, setAiLoading] = useState(false);

  const striker = getPlayer(matchState.battingTeam.players, matchState.strikerId);
  const nonStriker = getPlayer(matchState.battingTeam.players, matchState.nonStrikerId);
  const bowler = getPlayer(matchState.bowlingTeam.players, matchState.currentBowlerId);

  // Auto-prompt for bowler change
  useEffect(() => {
    if (matchState.currentBall === 0 && matchState.currentOver > 0 && matchState.ballHistory.length > 0) {
      setBowlerSelectOpen(true);
    }
  }, [matchState.currentOver]);

  // Handle innings break or match end
  useEffect(() => {
    if (matchState.matchStatus === 'COMPLETED' || matchState.matchStatus === 'INNINGS_BREAK') {
      onFinish();
    }
  }, [matchState.matchStatus]);

  const resetWicketState = () => {
    setWicketModalOpen(false);
    setSelectedWicketType(null);
    setSelectedFielder('');
    setWhoIsOut('striker');
  };

  const handleScore = (runs: number) => {
    processAndSetState(runs, false, undefined);
  };

  const handleWicketConfirm = () => {
    if (!selectedWicketType) return;

    const wicketDetails: WicketDetails = {
      type: selectedWicketType,
      fielderName: selectedFielder || undefined,
      isStrikerOut: whoIsOut === 'striker'
    };

    processAndSetState(0, true, wicketDetails);
    resetWicketState();
  };

  const processAndSetState = (runs: number, isWicket: boolean, wicketDetails: WicketDetails | undefined) => {
    let nextBatsmanId = undefined;

    if (isWicket) {
      // Find next batsman who is not out and not currently batting
      const nextBat = matchState.battingTeam.players.find(p => !p.isOut && p.id !== matchState.strikerId && p.id !== matchState.nonStrikerId);
      if (nextBat) nextBatsmanId = nextBat.id;
    }

    const newState = processBall(matchState, runs, extraType, isWicket, wicketDetails, nextBatsmanId);
    setMatchState(newState);

    setExtraType(ExtraType.NONE);

    setAiLoading(true);
    const lastEvent = newState.ballHistory[newState.ballHistory.length - 1];
    generateCommentary(lastEvent, newState).then(text => {
      setCommentary(text);
      setAiLoading(false);
    });
  };

  const handleChangeBowler = (bowlerId: string) => {
    const newState = { ...matchState, currentBowlerId: bowlerId };
    setMatchState(newState);
    setBowlerSelectOpen(false);
  };

  const getLabel = (runVal: number) => {
    if (extraType === ExtraType.WIDE) return `WD + ${runVal}`;
    if (extraType === ExtraType.NO_BALL) return `NB + ${runVal}`;
    if (extraType === ExtraType.BYE) return `${runVal} B`;
    if (extraType === ExtraType.LEG_BYE) return `${runVal} LB`;
    return runVal.toString();
  };

  const needsFielder = selectedWicketType === WicketType.CAUGHT || selectedWicketType === WicketType.RUN_OUT || selectedWicketType === WicketType.STUMPED;

  return (
    <View className="flex-1 bg-tiger-black">

      {/* HEADER */}
      <View className="bg-gray-900 border-b border-gray-700">
        <View className="px-4 py-2 flex-row justify-between items-center bg-black/40">
          <Text className="text-xs font-bold text-gray-400 uppercase">{matchState.battingTeam.name} vs {matchState.bowlingTeam.name}</Text>
          <View className="flex-row gap-2">
             <Text className="text-xs text-red-500 font-bold">• LIVE</Text>
          </View>
        </View>

        <View className="px-4 py-4 flex-row items-end justify-between">
          <View>
            <View className="flex-row items-baseline gap-2">
              <Text className="text-5xl font-black text-white">
                {matchState.totalRuns}/{matchState.wickets}
              </Text>
              <Text className="text-xl text-tiger-gold font-mono">
                {matchState.currentOver}.{matchState.currentBall} <Text className="text-sm text-gray-500">ov</Text>
              </Text>
            </View>
            <View className="flex-row gap-2 mt-1">
                 <Text className="text-xs text-gray-400">Extras: {matchState.extras.wides + matchState.extras.noBalls + matchState.extras.byes + matchState.extras.legByes}</Text>
                 {matchState.target && (
                    <Text className="text-xs text-tiger-gold font-bold ml-2">
                      Need {matchState.target - matchState.totalRuns}
                    </Text>
                 )}
            </View>
          </View>

          <View className="items-end gap-2">
            <TouchableOpacity 
                onPress={onUndo} 
                disabled={!canUndo}
                className={`px-3 py-1.5 rounded flex-row items-center gap-1 ${canUndo ? 'bg-gray-700' : 'bg-gray-800'}`}
            >
              <RotateCcw size={12} color={canUndo ? "white" : "gray"} /> 
              <Text className={`text-xs font-bold uppercase ${canUndo ? 'text-white' : 'text-gray-500'}`}>Undo</Text>
            </TouchableOpacity>
            <TouchableOpacity 
              onPress={() => setBowlerSelectOpen(true)}
              className="px-3 py-1.5 rounded bg-tiger-gold/10 border border-tiger-gold/30"
            >
              <Text className="text-tiger-gold text-xs font-bold uppercase">Change Bowler</Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* BATTER BOWLER STRIP */}
        <View className="flex-row border-t border-gray-700 bg-gray-800">
          <View className="flex-1 p-2 border-r border-gray-700 border-l-4 border-l-tiger-gold">
               <View className="flex-row items-center gap-1">
                 <Text className="text-sm font-bold text-white">{striker?.name}</Text>
                 <Trophy size={10} color="#fbbf24" fill="#fbbf24" />
               </View>
               <View className="flex-row justify-between mt-1">
                  <Text className="text-[10px] text-gray-400 uppercase">Striker</Text>
                  <Text className="text-sm font-bold text-tiger-gold">{striker?.runs} ({striker?.balls})</Text>
               </View>
          </View>

          <View className="flex-1 p-2 border-r border-gray-700 opacity-60">
            <Text className="text-sm font-semibold text-gray-300">{nonStriker?.name}</Text>
            <View className="flex-row justify-between mt-1">
               <Text className="text-[10px] text-gray-400 uppercase">Non-Striker</Text>
               <Text className="text-xs text-gray-400">{nonStriker?.runs} ({nonStriker?.balls})</Text>
            </View>
          </View>

          <View className="flex-1 p-2 bg-gray-900/40">
               <Text className="text-sm font-bold text-white text-right">{bowler?.name}</Text>
               <View className="flex-row justify-between mt-1">
                  <Text className="text-[10px] text-gray-400 uppercase">Bowler</Text>
                  <Text className="text-xs font-bold text-blue-400">{bowler?.wickets}-{bowler?.runsConceded} <Text className="font-normal text-gray-500">({Math.floor((bowler?.ballsBowled || 0)/6)}.{ (bowler?.ballsBowled || 0)%6 })</Text></Text>
               </View>
          </View>
        </View>
      </View>

      {/* TIMELINE */}
      <View className="bg-black/60 border-b border-gray-800 py-2">
        <ScrollView horizontal showsHorizontalScrollIndicator={false} className="px-2">
          <Text className="text-[10px] font-bold text-gray-500 uppercase mr-3 self-center">Last 12:</Text>
          {matchState.ballHistory.slice(-12).reverse().map((ball, idx) => (
            <View key={idx} className={`w-7 h-7 items-center justify-center rounded-full mr-2 border border-opacity-30 
              ${ball.isWicket ? 'bg-red-500/20 border-red-500' : 
                ball.runs >= 4 ? 'bg-tiger-gold border-tiger-gold' : 
                'bg-gray-800 border-gray-600'}`}>
              <Text className={`text-[10px] font-bold ${ball.isWicket ? 'text-red-400' : ball.runs >= 4 ? 'text-black' : 'text-gray-300'}`}>
                {ball.isWicket ? 'W' : ball.extraType !== ExtraType.NONE ? (ball.runs + ball.extraRuns) + (ball.extraType[0]) : ball.runs}
              </Text>
            </View>
          ))}
        </ScrollView>
      </View>

      {/* COMMENTARY */}
      <View className="px-4 py-3 bg-tiger-gold/5 border-b border-tiger-gold/10 flex-row items-start gap-2">
        <Mic size={14} color="#fbbf24" style={{ marginTop: 2 }} />
        <Text className="text-xs text-gray-300 leading-5 font-medium flex-1">
          {aiLoading ? "Thinking..." : commentary}
        </Text>
      </View>

      {/* CONTROLS */}
      <View className="flex-1 p-4 justify-end gap-3 bg-gray-900">
        {/* Extras Row */}
        <View className="flex-row gap-2 justify-between">
           {[ExtraType.WIDE, ExtraType.NO_BALL, ExtraType.BYE, ExtraType.LEG_BYE].map((type) => (
             <TouchableOpacity
                key={type}
                onPress={() => setExtraType(extraType === type ? ExtraType.NONE : type)}
                className={`flex-1 py-3 rounded-lg border items-center ${
                  extraType === type 
                  ? 'bg-tiger-orange border-tiger-gold' 
                  : 'bg-gray-800 border-gray-700'
                }`}
             >
               <Text className={`text-[10px] font-bold uppercase ${extraType === type ? 'text-white' : 'text-gray-400'}`}>
                  {type === ExtraType.NO_BALL ? 'NB' : type}
               </Text>
             </TouchableOpacity>
           ))}
        </View>

        {/* Main Keypad */}
        <View className="flex-row flex-wrap gap-2 justify-between">
          {[0, 1, 2, 3].map(run => (
            <TouchableOpacity key={run} onPress={() => handleScore(run)} className="w-[22%] h-14 rounded-lg bg-gray-800 border-b-4 border-gray-950 items-center justify-center">
               <Text className="text-xl font-bold text-white">{getLabel(run)}</Text>
            </TouchableOpacity>
          ))}
          <TouchableOpacity onPress={() => handleScore(4)} className="w-[22%] h-14 rounded-lg bg-tiger-gold border-b-4 border-tiger-orange items-center justify-center">
             <Text className="text-2xl font-black text-black">4</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={() => handleScore(6)} className="w-[22%] h-14 rounded-lg bg-tiger-gold border-b-4 border-tiger-orange items-center justify-center">
             <Text className="text-2xl font-black text-black">6</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={() => setWicketModalOpen(true)} className="flex-1 h-14 rounded-lg bg-red-600 border-b-4 border-red-800 items-center justify-center">
             <Text className="text-xl font-bold text-white tracking-widest">WICKET</Text>
          </TouchableOpacity>
        </View>

        <TouchableOpacity 
          onPress={() => {
            setAiLoading(true);
            askRuleQuestion("What is the fielding restriction in powerplay?").then(ans => {
               Alert.alert("AI Umpire", ans);
               setAiLoading(false);
            });
          }} 
          className="mt-2 w-full py-3 bg-gray-800/50 rounded-lg flex-row items-center justify-center gap-2 border border-dashed border-gray-700"
        >
          <Info size={14} color="gray" /> 
          <Text className="text-gray-500 text-xs">Ask AI Umpire</Text>
        </TouchableOpacity>
      </View>

      {/* WICKET MODAL */}
      <Modal visible={wicketModalOpen} transparent animationType="slide">
        <View className="flex-1 bg-black/90 justify-end">
          <View className="bg-gray-900 rounded-t-3xl p-6 h-[75%]">
            <View className="flex-row justify-between items-center mb-6">
               <Text className="text-xl font-bold text-red-500">Wicket Fall</Text>
               <TouchableOpacity onPress={resetWicketState}>
                  <Text className="text-gray-400 font-bold">Cancel</Text>
               </TouchableOpacity>
            </View>

            <ScrollView>
               <Text className="text-xs font-bold text-gray-500 uppercase mb-3">Dismissal Type</Text>
               <View className="flex-row flex-wrap gap-2 mb-6">
                  {Object.values(WicketType).map((w) => (
                    <TouchableOpacity 
                      key={w}
                      onPress={() => {
                        setSelectedWicketType(w);
                        if(w === WicketType.BOWLED || w === WicketType.LBW || w === WicketType.HIT_WICKET) {
                          setSelectedFielder('');
                        }
                      }}
                      className={`px-4 py-3 rounded-lg border ${selectedWicketType === w ? 'bg-red-600 border-red-500' : 'bg-gray-800 border-gray-700'}`}
                    >
                      <Text className={`font-bold ${selectedWicketType === w ? 'text-white' : 'text-gray-400'}`}>{w}</Text>
                    </TouchableOpacity>
                  ))}
               </View>

               {selectedWicketType && (
                 <View>
                    {selectedWicketType === WicketType.RUN_OUT && (
                       <View className="mb-6">
                         <Text className="text-xs font-bold text-gray-500 uppercase mb-3">Who is Out?</Text>
                         <View className="flex-row gap-2">
                           <TouchableOpacity onPress={() => setWhoIsOut('striker')} className={`flex-1 p-3 rounded-lg border ${whoIsOut === 'striker' ? 'bg-blue-600 border-blue-500' : 'bg-gray-800 border-gray-700'}`}>
                             <Text className="text-white font-bold text-center">{striker?.name}</Text>
                           </TouchableOpacity>
                           <TouchableOpacity onPress={() => setWhoIsOut('nonStriker')} className={`flex-1 p-3 rounded-lg border ${whoIsOut === 'nonStriker' ? 'bg-blue-600 border-blue-500' : 'bg-gray-800 border-gray-700'}`}>
                             <Text className="text-white font-bold text-center">{nonStriker?.name}</Text>
                           </TouchableOpacity>
                         </View>
                       </View>
                    )}

                    {needsFielder && (
                      <View>
                         <Text className="text-xs font-bold text-gray-500 uppercase mb-3">Fielder Involved</Text>
                         <View className="flex-row flex-wrap gap-2">
                            {matchState.bowlingTeam.players.map(p => (
                              <TouchableOpacity
                                key={p.id}
                                onPress={() => setSelectedFielder(p.name)}
                                className={`px-3 py-2 rounded border ${selectedFielder === p.name ? 'bg-blue-600 border-blue-500' : 'bg-gray-800 border-gray-700'}`}
                              >
                                <Text className={selectedFielder === p.name ? 'text-white font-bold' : 'text-gray-400'}>{p.name}</Text>
                              </TouchableOpacity>
                            ))}
                         </View>
                      </View>
                    )}
                 </View>
               )}
            </ScrollView>

            <TouchableOpacity 
               disabled={!selectedWicketType || (needsFielder && !selectedFielder)}
               onPress={handleWicketConfirm}
               className={`w-full py-4 rounded-xl mt-4 items-center ${!selectedWicketType ? 'bg-gray-800' : 'bg-red-600'}`}
            >
               <Text className={`font-bold text-lg ${!selectedWicketType ? 'text-gray-500' : 'text-white'}`}>CONFIRM WICKET</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {/* BOWLER SELECT MODAL */}
      <Modal visible={bowlerSelectOpen} transparent animationType="fade">
        <View className="flex-1 bg-black/90 justify-center p-6">
           <View className="bg-gray-900 rounded-2xl border border-gray-800 p-6 max-h-[60%]">
             <Text className="text-xl font-bold text-white text-center mb-1">Select New Bowler</Text>
             <Text className="text-xs text-gray-500 text-center mb-4">Previous over completed</Text>
             <ScrollView>
                {matchState.bowlingTeam.players.filter(p => p.id !== matchState.currentBowlerId).map(p => (
                  <TouchableOpacity
                    key={p.id}
                    onPress={() => handleChangeBowler(p.id)}
                    className="p-4 bg-gray-800 rounded-xl mb-2 flex-row justify-between items-center border border-gray-700"
                  >
                    <View>
                       <Text className="font-bold text-white">{p.name}</Text>
                       <Text className="text-xs text-gray-500">{p.wickets} wkts • {Math.floor(p.ballsBowled/6)}.{p.ballsBowled%6} ov</Text>
                    </View>
                    <ChevronDown className="-rotate-90" size={16} color="gray" />
                  </TouchableOpacity>
                ))}
             </ScrollView>
           </View>
        </View>
      </Modal>
    </View>
  );
};

import React, { useState, useMemo } from 'react';
import { View, Text, TouchableOpacity, ScrollView } from 'react-native';
import { MatchState } from '../types';
import { aggregateStats } from '../utils/statsLogic';
import { ArrowLeft, Calendar } from 'lucide-react-native';

interface Props {
  matchHistory: MatchState[];
  onBack: () => void;
}

export const StatsDashboard: React.FC<Props> = ({ matchHistory, onBack }) => {
  const [activeTab, setActiveTab] = useState<'players' | 'matches'>('players');
  const [sortBy, setSortBy] = useState<'runs' | 'wickets'>('runs');
  const HOME_TEAM_NAME = 'Taxila Tigers';

  const playerStats = useMemo(() => aggregateStats(matchHistory, HOME_TEAM_NAME), [matchHistory]);

  const sortedPlayers = useMemo(() => {
    return [...playerStats].sort((a, b) => {
      if (sortBy === 'runs') return b.runs - a.runs;
      return b.wickets - a.wickets;
    });
  }, [playerStats, sortBy]);

  const maxRuns = Math.max(...playerStats.map(p => p.runs), 1);

  const getMatchResult = (match: MatchState) => {
    if (match.matchStatus !== 'COMPLETED') return { text: 'In Progress', color: 'text-gray-500' };
    if (!match.firstInningsScore) return { text: 'Unknown', color: 'text-gray-500' };

    const scoreFirst = match.firstInningsScore.runs;
    const scoreSecond = match.totalRuns;
    const firstBatTeam = match.firstInningsScore.teamName;

    let winner = scoreFirst > scoreSecond ? firstBatTeam : match.battingTeam.name;
    const isWin = winner === HOME_TEAM_NAME;

    return isWin 
      ? { text: 'WON', color: 'text-green-400 bg-green-900/20 border-green-500' } 
      : { text: 'LOST', color: 'text-red-400 bg-red-900/20 border-red-500' };
  };

  return (
    <View className="flex-1 bg-tiger-black">
      <View className="flex-row items-center gap-4 p-4 border-b border-gray-800">
        <TouchableOpacity onPress={onBack} className="p-2 rounded-full bg-gray-800">
          <ArrowLeft size={20} color="#fbbf24" />
        </TouchableOpacity>
        <Text className="text-xl font-bold text-white">Taxila Tigers Stats</Text>
      </View>

      <View className="flex-row bg-gray-900 p-2">
        <TouchableOpacity onPress={() => setActiveTab('players')} className={`flex-1 py-3 border-b-2 items-center ${activeTab === 'players' ? 'border-tiger-gold' : 'border-transparent'}`}>
           <Text className={`font-bold text-xs uppercase ${activeTab === 'players' ? 'text-tiger-gold' : 'text-gray-500'}`}>Player Stats</Text>
        </TouchableOpacity>
        <TouchableOpacity onPress={() => setActiveTab('matches')} className={`flex-1 py-3 border-b-2 items-center ${activeTab === 'matches' ? 'border-tiger-gold' : 'border-transparent'}`}>
           <Text className={`font-bold text-xs uppercase ${activeTab === 'matches' ? 'text-tiger-gold' : 'text-gray-500'}`}>Matches</Text>
        </TouchableOpacity>
      </View>

      <ScrollView className="flex-1 p-4">
        {activeTab === 'players' ? (
          <View>
             <View className="flex-row gap-2 mb-4">
                <TouchableOpacity onPress={() => setSortBy('runs')} className={`flex-1 py-2 rounded border items-center ${sortBy === 'runs' ? 'bg-tiger-gold border-tiger-gold' : 'border-gray-700'}`}>
                   <Text className={`text-xs font-bold uppercase ${sortBy === 'runs' ? 'text-black' : 'text-gray-400'}`}>Runs</Text>
                </TouchableOpacity>
                <TouchableOpacity onPress={() => setSortBy('wickets')} className={`flex-1 py-2 rounded border items-center ${sortBy === 'wickets' ? 'bg-tiger-gold border-tiger-gold' : 'border-gray-700'}`}>
                   <Text className={`text-xs font-bold uppercase ${sortBy === 'wickets' ? 'text-black' : 'text-gray-400'}`}>Wickets</Text>
                </TouchableOpacity>
             </View>

             {sortedPlayers.map((p, idx) => (
                <View key={idx} className="bg-gray-800 p-4 rounded-xl mb-3 border border-gray-700">
                   <View className="flex-row justify-between mb-2">
                      <View className="flex-row items-center gap-2">
                         <View className="bg-gray-700 w-6 h-6 rounded-full items-center justify-center"><Text className="text-xs text-white font-bold">{idx + 1}</Text></View>
                         <Text className="font-bold text-white text-base">{p.name}</Text>
                      </View>
                      <View className="items-end">
                         <Text className="font-bold text-tiger-gold text-lg">{sortBy === 'runs' ? p.runs : p.wickets}</Text>
                         <Text className="text-[10px] text-gray-500 uppercase">{sortBy === 'runs' ? 'Runs' : 'Wickets'}</Text>
                      </View>
                   </View>

                   {/* Simple Bar Chart Visualization */}
                   {sortBy === 'runs' && (
                     <View className="h-2 bg-gray-700 rounded-full overflow-hidden mt-1">
                        <View className="h-full bg-tiger-orange" style={{ width: `${(p.runs / maxRuns) * 100}%` }} />
                     </View>
                   )}

                   <View className="flex-row justify-between mt-3 pt-2 border-t border-gray-700">
                      <Text className="text-xs text-gray-400">Matches: {p.matches}</Text>
                      <Text className="text-xs text-gray-400">{sortBy === 'runs' ? `High: ${p.highestScore}` : `Best: ${p.bestBowling.wickets}/${p.bestBowling.runs}`}</Text>
                   </View>
                </View>
             ))}
          </View>
        ) : (
          <View>
             {matchHistory.slice().reverse().map((match, idx) => {
               const res = getMatchResult(match);
               const date = new Date(match.ballHistory[0]?.timestamp || Date.now()).toLocaleDateString();
               return (
                 <View key={idx} className="bg-gray-800 rounded-xl p-4 border border-gray-700 mb-3">
                   <View className="flex-row justify-between mb-2">
                     <View className="flex-row items-center gap-1">
                        <Calendar size={12} color="gray" />
                        <Text className="text-xs text-gray-500 font-bold">{date}</Text>
                     </View>
                     <View className={`px-2 py-0.5 rounded border ${res.color.split(' ').slice(1).join(' ')}`}>
                        <Text className={`text-[10px] font-bold uppercase ${res.color.split(' ')[0]}`}>{res.text}</Text>
                     </View>
                   </View>
                   <View className="flex-row justify-between items-end">
                      <View>
                         {match.firstInningsScore && (
                           <Text className="text-xs text-gray-400 mb-1">{match.firstInningsScore.teamName}: {match.firstInningsScore.runs}/{match.firstInningsScore.wickets}</Text>
                         )}
                         <Text className="text-lg font-bold text-white">{match.battingTeam.name}: <Text className="text-tiger-gold">{match.totalRuns}/{match.wickets}</Text></Text>
                      </View>
                   </View>
                 </View>
               );
             })}
          </View>
        )}
      </ScrollView>
    </View>
  );
};

import React, { useEffect, useState } from 'react';
