        <Text className="text-gray-400 font-medium">{matchState.battingTeam.name} Innings Closed</Text>
      </View>

      <ScrollView className="flex-1 p-6">
        <View className="bg-gray-800 rounded-xl overflow-hidden border border-gray-700 mb-6">
           <View className="bg-gray-900 px-4 py-3 border-b border-gray-700 flex-row justify-between">
              <Text className="font-bold text-gray-300">Batting Scorecard</Text>
              <Text className="text-xs text-gray-500 uppercase">R (B)</Text>
           </View>
           {batStats.map((p, idx) => (
             <View key={p.id} className={`px-4 py-3 flex-row justify-between items-center ${idx < batStats.length -1 ? 'border-b border-gray-700/50' : ''}`}>
                <View>
                  <Text className="font-semibold text-sm text-gray-200">{p.name}</Text>
                  <Text className="text-xs text-gray-500 italic">{getDismissalText(p)}</Text>
