        <View className="flex-row gap-4 mb-8">
          <TouchableOpacity onPress={() => onSaveAndExit(matchState)} className="flex-1 bg-tiger-gold py-4 rounded-xl flex-row items-center justify-center gap-2">
             <Save size={18} color="black" /> 
             <Text className="text-black font-bold uppercase">Save & Exit</Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
