import React, { useState } from 'react';
import { View, Text, TouchableOpacity, ScrollView } from 'react-native';
import { Player } from '../types';

interface Props {
  battingTeamName: string;
  bowlingTeamName: string;
  battingPlayers: Player[];
  bowlingPlayers: Player[];
  onStart: (strikerId: string, nonStrikerId: string, bowlerId: string) => void;
  inningsNumber: 1 | 2;
}

// Simple Selection Pill Component
const SelectPill = ({ label, selected, onSelect, options, disabledOption }: any) => (
  <View className="mb-4">
    <Text className="text-xs font-bold text-gray-500 uppercase mb-2">{label}</Text>
    <ScrollView horizontal showsHorizontalScrollIndicator={false}>
      {options.map((p: any) => {
        const isSelected = selected === p.id;
        const isDisabled = disabledOption === p.id;
        if (isDisabled) return null;

        return (
          <TouchableOpacity 
            key={p.id} 
            onPress={() => onSelect(p.id)}
            className={`mr-2 px-4 py-3 rounded-lg border ${isSelected ? 'bg-tiger-gold border-tiger-gold' : 'bg-gray-800 border-gray-700'}`}
          >
            <Text className={`font-bold ${isSelected ? 'text-black' : 'text-gray-300'}`}>{p.name}</Text>
          </TouchableOpacity>
        )
      })}
    </ScrollView>
  </View>
);

export const OpenerSelection: React.FC<Props> = ({ 
  battingTeamName, bowlingTeamName, battingPlayers, bowlingPlayers, onStart, inningsNumber 
}) => {
  const [strikerId, setStrikerId] = useState<string>('');
  const [nonStrikerId, setNonStrikerId] = useState<string>('');
  const [bowlerId, setBowlerId] = useState<string>('');

  const isValid = strikerId && nonStrikerId && bowlerId && strikerId !== nonStrikerId;
  const availableBatters = battingPlayers.filter(p => !p.isOut);

  return (
    <View className="flex-1 bg-tiger-black p-6 justify-center">
      <View className="items-center mb-8">
         <Text className="text-2xl font-black text-tiger-gold uppercase tracking-widest">Start Innings {inningsNumber}</Text>
         <Text className="text-gray-400">Select opening players</Text>
      </View>

      <View className="bg-gray-900 p-6 rounded-2xl border border-gray-800 space-y-2">
         <Text className="text-sm font-bold text-white uppercase mb-2">{battingTeamName} Batters</Text>
         <SelectPill 
           label="Striker" 
           selected={strikerId} 
           onSelect={setStrikerId} 
           options={availableBatters} 
           disabledOption={nonStrikerId} 
         />
         <SelectPill 
           label="Non-Striker" 
           selected={nonStrikerId} 
           onSelect={setNonStrikerId} 
           options={availableBatters} 
           disabledOption={strikerId} 
         />

         <View className="h-4" />

         <Text className="text-sm font-bold text-white uppercase mb-2">{bowlingTeamName} Bowler</Text>
         <SelectPill 
           label="Opening Bowler" 
           selected={bowlerId} 
           onSelect={setBowlerId} 
           options={bowlingPlayers} 
         />
      </View>

      <TouchableOpacity 
        disabled={!isValid}
        onPress={() => isValid && onStart(strikerId, nonStrikerId, bowlerId)}
        className={`w-full py-4 rounded-xl mt-8 shadow-lg items-center ${isValid ? 'bg-green-600' : 'bg-gray-800'}`}
      >
        <Text className={`font-black uppercase tracking-widest ${isValid ? 'text-white' : 'text-gray-600'}`}>Start Play</Text>
      </TouchableOpacity>
    </View>
  );
};

import React, { useState } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Alert } from 'react-native';
import { CheckCircle2, Circle, UserPlus } from 'lucide-react-native';
import { SavedTeam } from '../types';

interface Props {
  homeTeam: SavedTeam;
  awayTeam: SavedTeam;
  onConfirm: (homeXI: string[], awayXI: string[], homeReserves: string[], awayReserves: string[]) => void;
  onBack: () => void;
}

export const SquadSelection: React.FC<Props> = ({ 
  homeTeam, awayTeam, onConfirm, onBack 
}) => {
  const [homePlaying, setHomePlaying] = useState<string[]>([]);
  const [homeReserves, setHomeReserves] = useState<string[]>([]);

  const [awayPlaying, setAwayPlaying] = useState<string[]>([]);
  const [awayReserves, setAwayReserves] = useState<string[]>([]);

  const [activeTab, setActiveTab] = useState<'home' | 'away'>('home');

  const toggleSelection = (player: string, isHome: boolean) => {
    const playing = isHome ? homePlaying : awayPlaying;
    const reserves = isHome ? homeReserves : awayReserves;
    const setPlaying = isHome ? setHomePlaying : setAwayPlaying;
    const setReserves = isHome ? setHomeReserves : setAwayReserves;

    if (playing.includes(player)) {
      setPlaying(playing.filter(p => p !== player));
      return;
    }
    if (reserves.includes(player)) {
      setReserves(reserves.filter(p => p !== player));
      return;
    }

    if (playing.length < 11) {
      setPlaying([...playing, player]);
    } else if (reserves.length < 2) {
      setReserves([...reserves, player]);
    } else {
      Alert.alert("Full", "11 Playing + 2 Reserves Max.");
    }
  };

  const handleConfirm = () => {
    if (homePlaying.length !== 11 || awayPlaying.length !== 11) {
      Alert.alert("Invalid Squad", "You must select exactly 11 playing members for each team.");
      return;
    }
    onConfirm(homePlaying, awayPlaying, homeReserves, awayReserves);
  };

  const currentTeam = activeTab === 'home' ? homeTeam : awayTeam;
  const currentPlaying = activeTab === 'home' ? homePlaying : awayPlaying;
  const currentReserves = activeTab === 'home' ? homeReserves : awayReserves;

  return (
    <View className="flex-1 bg-tiger-black p-4">
      <View className="mb-4 items-center">
        <Text className="text-xl font-bold text-tiger-gold uppercase tracking-wider">Select Squads</Text>
        <Text className="text-gray-400 text-xs mt-1">Select 11 Playing & 2 Reserves</Text>
      </View>

      <View className="flex-row mb-4 bg-gray-800 p-1 rounded-lg">
        <TouchableOpacity 
          onPress={() => setActiveTab('home')}
          className={`flex-1 py-2 rounded-md items-center justify-center flex-row gap-2 ${activeTab === 'home' ? 'bg-tiger-gold' : 'bg-transparent'}`}
        >
          <Text className={`text-sm font-bold ${activeTab === 'home' ? 'text-black' : 'text-gray-400'}`}>{homeTeam.name}</Text>
          <View className="bg-black/20 px-2 rounded-full"><Text className="text-[10px] text-white">{homePlaying.length}/11</Text></View>
        </TouchableOpacity>
        <TouchableOpacity 
          onPress={() => setActiveTab('away')}
          className={`flex-1 py-2 rounded-md items-center justify-center flex-row gap-2 ${activeTab === 'away' ? 'bg-tiger-gold' : 'bg-transparent'}`}
        >
          <Text className={`text-sm font-bold ${activeTab === 'away' ? 'text-black' : 'text-gray-400'}`}>{awayTeam.name}</Text>
          <View className="bg-black/20 px-2 rounded-full"><Text className="text-[10px] text-white">{awayPlaying.length}/11</Text></View>
        </TouchableOpacity>
      </View>

      <ScrollView className="flex-1 bg-gray-900/50 p-2 rounded-xl border border-gray-800 mb-4">
        {currentTeam.squad.map((player, idx) => {
          const isPlaying = currentPlaying.includes(player);
          const isReserve = currentReserves.includes(player);

          let borderColor = "border-gray-700";
          let textColor = "text-gray-500";

          if (isPlaying) {
             borderColor = "border-tiger-gold bg-tiger-gold/10";
             textColor = "text-white";
          } else if (isReserve) {
             borderColor = "border-blue-500 bg-blue-900/20";
             textColor = "text-blue-200";
          }

          return (
            <TouchableOpacity
              key={idx}
              onPress={() => toggleSelection(player, activeTab === 'home')}
              className={`w-full p-3 mb-2 rounded-lg flex-row justify-between items-center border ${borderColor}`}
            >
              <Text className={`font-semibold ${textColor}`}>{player}</Text>
              <View className="flex-row items-center gap-2">
                 {isPlaying && <Text className="text-[10px] font-bold uppercase text-tiger-gold">Playing</Text>}
                 {isReserve && <Text className="text-[10px] font-bold uppercase text-blue-400">Reserve</Text>}
                 {isPlaying ? <CheckCircle2 color="#fbbf24" size={20} /> : <Circle color="#4b5563" size={20} />}
              </View>
            </TouchableOpacity>
          );
        })}
      </ScrollView>

      <View className="flex-row gap-4">
        <TouchableOpacity onPress={onBack} className="flex-1 py-4 bg-gray-800 rounded-xl items-center justify-center">
            <Text className="text-white font-bold">Back</Text>
        </TouchableOpacity>
        <TouchableOpacity 
          onPress={handleConfirm}
          className={`flex-[2] py-4 rounded-xl items-center justify-center ${homePlaying.length !== 11 || awayPlaying.length !== 11 ? 'bg-gray-800 opacity-50' : 'bg-tiger-gold'}`}
          disabled={homePlaying.length !== 11 || awayPlaying.length !== 11}
        >
          <Text className="text-black font-bold uppercase">Confirm Squads</Text>
        </TouchableOpacity>
      </View>
    </View>
  );
};

import React, { useState } from 'react';
