    const bowlingLogo = isHomeBatting ? setupData.away.logoUrl : setupData.home.logoUrl;

    const createPlayers = (names: string[]): Player[] => names.map(name => ({
      id: Math.random().toString(36).substr(2, 9),
      name,
      runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false,
      ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0
    }));

    const initialState: MatchState = {
      battingTeam: { name: battingTeamName, players: createPlayers(battingSquad), isBatting: true, logoUrl: battingLogo },
      bowlingTeam: { name: bowlingTeamName, players: createPlayers(bowlingSquad), isBatting: false, logoUrl: bowlingLogo },
      tossWinner: winner,
      tossDecision: decision,
      totalOvers: setupData.overs,
      currentOver: 0,
      currentBall: 0,
      totalRuns: 0,
      wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: '',
      nonStrikerId: '',
      currentBowlerId: '',
      ballHistory: [],
      matchStatus: 'LIVE',
      inningsNumber: 1
    };

    setMatchState(initialState);
    setView('openers');
  };

  // 4. OPENERS -> SCORING
  const handleStartInnings = (strikerId: string, nonStrikerId: string, bowlerId: string) => {
    if (!matchState) return;
    setMatchState({
      ...matchState,
      strikerId,
      nonStrikerId,
      currentBowlerId: bowlerId
    });
    setUndoStack([]); // Clear undo on new innings start
    setView('scoring');
  };

  // 5. SCORING -> BREAK / FINISH
  const handleMatchFinish = () => {
     if (matchState?.matchStatus === 'INNINGS_BREAK') {
       setView('break');
     } else {
       setView('summary');
     }
  };

  // 6. BREAK -> OPENERS (Innings 2)
  const startSecondInnings = () => {
    if (!matchState || !setupData || !squads) return;

    // Swap Teams
    const oldBatting = matchState.battingTeam;
    const oldBowling = matchState.bowlingTeam;

    // Reset players for new roles
    // We need fresh stats for the new innings but keep names. 
    // In a full app, we'd track match stats vs innings stats. Here we simple reset for the new inning context.
    // However, to keep it simple, we just swap the objects and reset score counters.

    const newBatting = { ...oldBowling, isBatting: true };
    const newBowling = { ...oldBatting, isBatting: false };

    // Reset individual inning stats
    newBatting.players.forEach(p => { p.runs=0; p.balls=0; p.fours=0; p.sixes=0; p.isOut=false; });
    newBowling.players.forEach(p => { p.ballsBowled=0; p.runsConceded=0; p.wickets=0; });

    const nextState: MatchState = {
      ...matchState,
      battingTeam: newBatting,
      bowlingTeam: newBowling,
      currentOver: 0,
      currentBall: 0,
      totalRuns: 0,
      wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      ballHistory: [], // Clear ball by ball for UI (keep history elsewhere if needed)
      matchStatus: 'LIVE',
      inningsNumber: 2,
      target: matchState.totalRuns + 1,
      strikerId: '',
      nonStrikerId: '',
      currentBowlerId: ''
    };

    setMatchState(nextState);
    setView('openers');
  };

  const handleStateUpdate = (newState: MatchState) => {
    if (matchState) setUndoStack([...undoStack, matchState]);
    setMatchState(newState);
  };

  const handleUndo = () => {
    if (undoStack.length > 0) {
      const prev = undoStack[undoStack.length - 1];
      setMatchState(prev);
      setUndoStack(undoStack.slice(0, -1));
    }
  };

  const handleSaveAndExit = async (finalState: MatchState) => {
    // Save to history
    const newHistory = [...matchHistory, finalState];
    setMatchHistory(newHistory);
    // Persist if needed (skipping for brevity)
    setView('setup');
    setMatchState(null);
  };

  return (
    <SafeAreaView className="flex-1 bg-tiger-black pt-8">
      <StatusBar barStyle="light-content" backgroundColor="#0f172a" />

      {view === 'setup' && (
        <MatchSetup 
          onNext={handleSetupComplete} 
          onViewStats={() => setView('stats')}
          onManageTeams={() => setView('teams')}
        />
      )}

      {view === 'teams' && <TeamManager onBack={() => setView('setup')} />}

      {view === 'stats' && <StatsDashboard matchHistory={matchHistory} onBack={() => setView('setup')} />}

      {view === 'squad' && setupData && (
        <SquadSelection 
          homeTeam={setupData.home} 
          awayTeam={setupData.away} 
          onConfirm={handleSquadConfirm}
          onBack={() => setView('setup')}
        />
      )}

      {view === 'toss' && setupData && (
        <TossScreen 
           homeTeam={setupData.home.name} 
           awayTeam={setupData.away.name} 
           onTossComplete={handleTossComplete}
           onBack={() => setView('squad')}
        />
      )}

      {view === 'openers' && matchState && (
        <OpenerSelection 
           battingTeamName={matchState.battingTeam.name}
           bowlingTeamName={matchState.bowlingTeam.name}
           battingPlayers={matchState.battingTeam.players}
           bowlingPlayers={matchState.bowlingTeam.players}
           inningsNumber={matchState.inningsNumber}
           onStart={handleStartInnings}
        />
      )}

      {view === 'scoring' && matchState && (
        <ScoringDashboard 
           matchState={matchState} 
           setMatchState={handleStateUpdate}
           onUndo={handleUndo}
           canUndo={undoStack.length > 0}
           onFinish={handleMatchFinish}
        />
      )}

      {view === 'break' && matchState && (
        <InningsBreak 
          matchState={matchState}
          onStartSecondInnings={startSecondInnings}
        />
      )}

      {view === 'summary' && matchState && (
        <MatchSummary 
           matchState={matchState}
           onSaveAndExit={handleSaveAndExit}
        />
      )}

    </SafeAreaView>
  );
};

