import { MatchState, BallEvent, ExtraType, WicketType, Player, WicketDetails } from '../types';

export const getPlayer = (players: Player[], id: string) => players.find(p => p.id === id);

export const calculateEconomy = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 6).toFixed(2);
};

export const calculateStrikeRate = (runs: number, balls: number) => {
  if (balls === 0) return 0;
  return ((runs / balls) * 100).toFixed(2);
};

/**
 * Main pure function to update state based on a scoring event
 */
export const processBall = (
  currentState: MatchState,
  runs: number,
  extraType: ExtraType,
  isWicket: boolean,
  wicketDetails: WicketDetails | undefined,
  newBatsmanId?: string
): MatchState => {
  const newState = JSON.parse(JSON.stringify(currentState)) as MatchState;

  const striker = getPlayer(newState.battingTeam.players, newState.strikerId)!;
  const nonStriker = getPlayer(newState.battingTeam.players, newState.nonStrikerId)!;
  const bowler = getPlayer(newState.bowlingTeam.players, newState.currentBowlerId)!;

  let runsScored = runs; 
  let extrasConceded = 0;
  let isLegalBall = true;

  // 1. Handle Extras logic
  if (extraType === ExtraType.WIDE) {
    extrasConceded += 1 + runs; 
    newState.extras.wides += 1 + runs;
    isLegalBall = false;
    bowler.runsConceded += 1 + runs;
    runsScored = 0; // Wides are extras, not batsman runs
  } else if (extraType === ExtraType.NO_BALL) {
    extrasConceded += 1;
    newState.extras.noBalls += 1;
    isLegalBall = false;
    bowler.runsConceded += 1;

    // Runs off bat count for batsman on No Ball
    striker.runs += runs;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;

    bowler.runsConceded += runs;
    runsScored = runs; 
  } else if (extraType === ExtraType.BYE) {
    extrasConceded += runs;
    newState.extras.byes += runs;
    striker.balls++; 
    isLegalBall = true;
    runsScored = 0; 
  } else if (extraType === ExtraType.LEG_BYE) {
    extrasConceded += runs;
    newState.extras.legByes += runs;
    striker.balls++; 
    isLegalBall = true;
    runsScored = 0;
  } else {
    // Regular ball
    striker.runs += runs;
    striker.balls++;
    if (runs === 4) striker.fours++;
    if (runs === 6) striker.sixes++;

    bowler.runsConceded += runs;
    runsScored = runs;
  }

  // Update Bowler Stats (Legal balls only)
  if (isLegalBall) {
    bowler.ballsBowled++;
    newState.currentBall++;
  }

  // Total Score Update
  newState.totalRuns += runsScored + extrasConceded;

  // 2. Handle Wicket
  let didStrikeRotateForRun = false;

  if (isWicket && wicketDetails) {
    newState.wickets++;

    // Determine who is out
    const victim = wicketDetails.isStrikerOut ? striker : nonStriker;

    // Run Outs don't get credited to bowler usually, others do
    if (wicketDetails.type !== WicketType.RUN_OUT) {
      bowler.wickets++;
    }

    victim.isOut = true;
    victim.dismissalType = wicketDetails.type;
    victim.dismissalBowler = bowler.name;
    if (wicketDetails.fielderName) {
      victim.dismissalFielder = wicketDetails.fielderName;
    }

    if (newBatsmanId) {
      // ICC Rule: New batter takes strike for Caught (unless end of over)
      if (wicketDetails.type === WicketType.CAUGHT) {
         newState.strikerId = newBatsmanId;
         // nonStrikerId remains the same (assuming they didn't cross, or if they did, they go back)
         // Note: If non-striker was out caught (unlikely but possible in weird scenarios), logic holds.
         if (!wicketDetails.isStrikerOut) {
            newState.nonStrikerId = newState.strikerId; // Logic fix: if non-striker out, original striker stays, new batter becomes non-striker? 
            // Actually, usually striker is out Caught.
            // If Striker out Caught: New Batter -> Striker. Non-Striker -> Non-Striker.
         }
      } 
      // For Run Outs, we need to respect the "Who is Out" selection
      else if (wicketDetails.type === WicketType.RUN_OUT) {
         if (wicketDetails.isStrikerOut) {
           newState.strikerId = newBatsmanId;
         } else {
           newState.nonStrikerId = newBatsmanId;
         }
      }
      // Bowled, LBW, Stumped -> Striker is out. New batter takes strike.
      else {
        if (wicketDetails.isStrikerOut) {
           newState.strikerId = newBatsmanId;
        } else {
           newState.nonStrikerId = newBatsmanId;
        }
      }
    }
  }

  // 3. Strike Rotation
  // Normal rotation for odd runs
  if (runs % 2 !== 0) {
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;
  }

  // 4. Record Event
  let description = `${runs} run${runs !== 1 ? 's' : ''}`;
  if (extraType !== ExtraType.NONE) description += ` (${extraType})`;
  if (isWicket && wicketDetails) {
    description += ` WICKET (${wicketDetails.type})`;
    if (wicketDetails.fielderName) description += ` by ${wicketDetails.fielderName}`;
  }

  const event: BallEvent = {
    runs,
    extraRuns: extrasConceded,
    extraType,
    isWicket,
    wicketType: wicketDetails?.type,
    batsmanId: striker.id,
    bowlerId: bowler.id,
    description,
    timestamp: Date.now(),
    isLegalBall,
    inningsNumber: newState.inningsNumber
  };
  newState.ballHistory.push(event);

  // 5. Over Completion
  if (newState.currentBall >= 6) {
    newState.currentOver++;
    newState.currentBall = 0;
    // Rotate strike at end of over
    const temp = newState.strikerId;
    newState.strikerId = newState.nonStrikerId;
    newState.nonStrikerId = temp;
  }

  // 6. Match Status Logic (End of Innings/Match)

  // Check if All Out or Overs Done
  const isAllOut = newState.wickets >= 10; 
  const isOversDone = newState.currentOver >= newState.totalOvers;

  // Check 2nd Innings Win
  const isTargetChased = newState.inningsNumber === 2 && newState.target && newState.totalRuns >= newState.target;

  if (newState.inningsNumber === 1) {
    if (isAllOut || isOversDone) {
      newState.matchStatus = 'INNINGS_BREAK';
      newState.firstInningsScore = {
        runs: newState.totalRuns,
        wickets: newState.wickets,
        overs: `${newState.currentOver}.${newState.currentBall}`,
        teamName: newState.battingTeam.name
      };
    }
  } else {
    // Innings 2
    if (isTargetChased) {
      newState.matchStatus = 'COMPLETED';
    } else if (isAllOut || isOversDone) {
       // Match end, target not reached
       newState.matchStatus = 'COMPLETED';
    }
  }

  return newState;
};

import React, { useState, useEffect, useRef } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Modal, Alert } from 'react-native';
import { MatchState, ExtraType, WicketType, Player, WicketDetails } from '../types';
import { processBall, getPlayer } from '../utils/cricketLogic';
import { generateCommentary, askRuleQuestion } from '../services/geminiService';
import { Mic, Info, RotateCcw, ChevronDown, Trophy, Plus, Minus } from 'lucide-react-native';

interface Props {
  matchState: MatchState;
  setMatchState: (state: MatchState) => void;
  onUndo: () => void;
  canUndo: boolean;
  onFinish: () => void;
}

export const ScoringDashboard: React.FC<Props> = ({ matchState, setMatchState, onUndo, canUndo, onFinish }) => {
  // Modal States
  const [wicketModalOpen, setWicketModalOpen] = useState(false);
  const [bowlerSelectOpen, setBowlerSelectOpen] = useState(false);

  // Wicket Flow States
  const [selectedWicketType, setSelectedWicketType] = useState<WicketType | null>(null);
  const [selectedFielder, setSelectedFielder] = useState<string>('');
  const [whoIsOut, setWhoIsOut] = useState<'striker' | 'nonStriker'>('striker');
  const [completedRuns, setCompletedRuns] = useState(0);

  const [extraType, setExtraType] = useState<ExtraType>(ExtraType.NONE);
  const [commentary, setCommentary] = useState<string>("Waiting for next ball...");
  const [aiLoading, setAiLoading] = useState(false);

  const striker = getPlayer(matchState.battingTeam.players, matchState.strikerId);
  const nonStriker = getPlayer(matchState.battingTeam.players, matchState.nonStrikerId);
  const bowler = getPlayer(matchState.bowlingTeam.players, matchState.currentBowlerId);

  // Auto-prompt for bowler change
  useEffect(() => {
    if (matchState.currentBall === 0 && matchState.currentOver > 0 && matchState.ballHistory.length > 0) {
      setBowlerSelectOpen(true);
    }
  }, [matchState.currentOver]);

  // Handle innings break or match end
  useEffect(() => {
    if (matchState.matchStatus === 'COMPLETED' || matchState.matchStatus === 'INNINGS_BREAK') {
      onFinish();
    }
  }, [matchState.matchStatus]);

  const resetWicketState = () => {
    setWicketModalOpen(false);
    setSelectedWicketType(null);
    setSelectedFielder('');
    setWhoIsOut('striker');
    setCompletedRuns(0);
  };

  const handleScore = (runs: number) => {
    processAndSetState(runs, false, undefined);
  };

  const handleWicketConfirm = () => {
    if (!selectedWicketType) return;

    const wicketDetails: WicketDetails = {
      type: selectedWicketType,
      fielderName: selectedFielder || undefined,
      isStrikerOut: whoIsOut === 'striker'
    };

    // For run outs, completed runs count.
    processAndSetState(completedRuns, true, wicketDetails);
    resetWicketState();
  };

  const processAndSetState = (runs: number, isWicket: boolean, wicketDetails: WicketDetails | undefined) => {
    let nextBatsmanId = undefined;

    if (isWicket) {
      // Find next batsman who is not out and not currently batting
      const nextBat = matchState.battingTeam.players.find(p => !p.isOut && p.id !== matchState.strikerId && p.id !== matchState.nonStrikerId);
      if (nextBat) nextBatsmanId = nextBat.id;
    }

    const newState = processBall(matchState, runs, extraType, isWicket, wicketDetails, nextBatsmanId);
    setMatchState(newState);

    setExtraType(ExtraType.NONE);

    setAiLoading(true);
    const lastEvent = newState.ballHistory[newState.ballHistory.length - 1];
    generateCommentary(lastEvent, newState).then(text => {
      setCommentary(text);
      setAiLoading(false);
    });
  };

  const handleChangeBowler = (bowlerId: string) => {
    const newState = { ...matchState, currentBowlerId: bowlerId };
    setMatchState(newState);
    setBowlerSelectOpen(false);
  };

  const getLabel = (runVal: number) => {
    if (extraType === ExtraType.WIDE) return `WD + ${runVal}`;
    if (extraType === ExtraType.NO_BALL) return `NB + ${runVal}`;
    if (extraType === ExtraType.BYE) return `${runVal} B`;
    if (extraType === ExtraType.LEG_BYE) return `${runVal} LB`;
    return runVal.toString();
  };

  const needsFielder = selectedWicketType === WicketType.CAUGHT || selectedWicketType === WicketType.RUN_OUT || selectedWicketType === WicketType.STUMPED;

  return (
    <View className="flex-1 bg-tiger-black">

      {/* HEADER */}
      <View className="bg-gray-900 border-b border-gray-700">
        <View className="px-4 py-2 flex-row justify-between items-center bg-black/40">
          <Text className="text-xs font-bold text-gray-400 uppercase">{matchState.battingTeam.name} vs {matchState.bowlingTeam.name}</Text>
          <View className="flex-row gap-2">
             <Text className="text-xs text-red-500 font-bold">• LIVE</Text>
          </View>
        </View>

        <View className="px-4 py-4 flex-row items-end justify-between">
          <View>
            <View className="flex-row items-baseline gap-2">
              <Text className="text-5xl font-black text-white">
                {matchState.totalRuns}/{matchState.wickets}
              </Text>
              <Text className="text-xl text-tiger-gold font-mono">
                {matchState.currentOver}.{matchState.currentBall} <Text className="text-sm text-gray-500">ov</Text>
              </Text>
            </View>
            <View className="flex-row gap-2 mt-1">
                 <Text className="text-xs text-gray-400">Extras: {matchState.extras.wides + matchState.extras.noBalls + matchState.extras.byes + matchState.extras.legByes}</Text>
                 {matchState.target && (
                    <Text className="text-xs text-tiger-gold font-bold ml-2">
                      Need {matchState.target - matchState.totalRuns}
                    </Text>
                 )}
            </View>
          </View>

          <View className="items-end gap-2">
            <TouchableOpacity 
                onPress={onUndo} 
                disabled={!canUndo}
                className={`px-3 py-1.5 rounded flex-row items-center gap-1 ${canUndo ? 'bg-gray-700' : 'bg-gray-800'}`}
            >
              <RotateCcw size={12} color={canUndo ? "white" : "gray"} /> 
              <Text className={`text-xs font-bold uppercase ${canUndo ? 'text-white' : 'text-gray-500'}`}>Undo</Text>
            </TouchableOpacity>
            <TouchableOpacity 
              onPress={() => setBowlerSelectOpen(true)}
              className="px-3 py-1.5 rounded bg-tiger-gold/10 border border-tiger-gold/30"
            >
              <Text className="text-tiger-gold text-xs font-bold uppercase">Change Bowler</Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* BATTER BOWLER STRIP */}
        <View className="flex-row border-t border-gray-700 bg-gray-800">
          <View className="flex-1 p-2 border-r border-gray-700 border-l-4 border-l-tiger-gold">
               <View className="flex-row items-center gap-1">
                 <Text className="text-sm font-bold text-white">{striker?.name}</Text>
                 <Trophy size={10} color="#fbbf24" fill="#fbbf24" />
               </View>
               <View className="flex-row justify-between mt-1">
                  <Text className="text-[10px] text-gray-400 uppercase">Striker</Text>
                  <Text className="text-sm font-bold text-tiger-gold">{striker?.runs} ({striker?.balls})</Text>
               </View>
          </View>

          <View className="flex-1 p-2 border-r border-gray-700 opacity-60">
            <Text className="text-sm font-semibold text-gray-300">{nonStriker?.name}</Text>
            <View className="flex-row justify-between mt-1">
               <Text className="text-[10px] text-gray-400 uppercase">Non-Striker</Text>
               <Text className="text-xs text-gray-400">{nonStriker?.runs} ({nonStriker?.balls})</Text>
            </View>
          </View>

          <View className="flex-1 p-2 bg-gray-900/40">
               <Text className="text-sm font-bold text-white text-right">{bowler?.name}</Text>
               <View className="flex-row justify-between mt-1">
                  <Text className="text-[10px] text-gray-400 uppercase">Bowler</Text>
                  <Text className="text-xs font-bold text-blue-400">{bowler?.wickets}-{bowler?.runsConceded} <Text className="font-normal text-gray-500">({Math.floor((bowler?.ballsBowled || 0)/6)}.{ (bowler?.ballsBowled || 0)%6 })</Text></Text>
               </View>
          </View>
        </View>
      </View>

      {/* TIMELINE */}
      <View className="bg-black/60 border-b border-gray-800 py-2">
        <ScrollView horizontal showsHorizontalScrollIndicator={false} className="px-2">
          <Text className="text-[10px] font-bold text-gray-500 uppercase mr-3 self-center">Last 12:</Text>
          {matchState.ballHistory.slice(-12).reverse().map((ball, idx) => (
            <View key={idx} className={`w-7 h-7 items-center justify-center rounded-full mr-2 border border-opacity-30 
              ${ball.isWicket ? 'bg-red-500/20 border-red-500' : 
                ball.runs >= 4 ? 'bg-tiger-gold border-tiger-gold' : 
                'bg-gray-800 border-gray-600'}`}>
              <Text className={`text-[10px] font-bold ${ball.isWicket ? 'text-red-400' : ball.runs >= 4 ? 'text-black' : 'text-gray-300'}`}>
                {ball.isWicket ? 'W' : ball.extraType !== ExtraType.NONE ? (ball.runs + ball.extraRuns) + (ball.extraType[0]) : ball.runs}
              </Text>
            </View>
          ))}
        </ScrollView>
      </View>

      {/* COMMENTARY */}
      <View className="px-4 py-3 bg-tiger-gold/5 border-b border-tiger-gold/10 flex-row items-start gap-2">
        <Mic size={14} color="#fbbf24" style={{ marginTop: 2 }} />
        <Text className="text-xs text-gray-300 leading-5 font-medium flex-1">
          {aiLoading ? "Thinking..." : commentary}
        </Text>
      </View>

      {/* CONTROLS */}
      <View className="flex-1 p-4 justify-end gap-3 bg-gray-900">
        {/* Extras Row */}
        <View className="flex-row gap-2 justify-between">
           {[ExtraType.WIDE, ExtraType.NO_BALL, ExtraType.BYE, ExtraType.LEG_BYE].map((type) => (
             <TouchableOpacity
                key={type}
                onPress={() => setExtraType(extraType === type ? ExtraType.NONE : type)}
                className={`flex-1 py-3 rounded-lg border items-center ${
                  extraType === type 
                  ? 'bg-tiger-orange border-tiger-gold' 
                  : 'bg-gray-800 border-gray-700'
                }`}
             >
               <Text className={`text-[10px] font-bold uppercase ${extraType === type ? 'text-white' : 'text-gray-400'}`}>
                  {type === ExtraType.NO_BALL ? 'NB' : type}
               </Text>
             </TouchableOpacity>
           ))}
        </View>

        {/* Main Keypad */}
        <View className="flex-row flex-wrap gap-2 justify-between">
          {[0, 1, 2, 3].map(run => (
            <TouchableOpacity key={run} onPress={() => handleScore(run)} className="w-[22%] h-14 rounded-lg bg-gray-800 border-b-4 border-gray-950 items-center justify-center">
               <Text className="text-xl font-bold text-white">{getLabel(run)}</Text>
            </TouchableOpacity>
          ))}
          <TouchableOpacity onPress={() => handleScore(4)} className="w-[22%] h-14 rounded-lg bg-tiger-gold border-b-4 border-tiger-orange items-center justify-center">
             <Text className="text-2xl font-black text-black">4</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={() => handleScore(6)} className="w-[22%] h-14 rounded-lg bg-tiger-gold border-b-4 border-tiger-orange items-center justify-center">
             <Text className="text-2xl font-black text-black">6</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={() => setWicketModalOpen(true)} className="flex-1 h-14 rounded-lg bg-red-600 border-b-4 border-red-800 items-center justify-center">
             <Text className="text-xl font-bold text-white tracking-widest">WICKET</Text>
          </TouchableOpacity>
        </View>

        <TouchableOpacity 
          onPress={() => {
            setAiLoading(true);
            askRuleQuestion("What is the fielding restriction in powerplay?").then(ans => {
               Alert.alert("AI Umpire", ans);
               setAiLoading(false);
            });
          }} 
          className="mt-2 w-full py-3 bg-gray-800/50 rounded-lg flex-row items-center justify-center gap-2 border border-dashed border-gray-700"
        >
          <Info size={14} color="gray" /> 
          <Text className="text-gray-500 text-xs">Ask AI Umpire</Text>
        </TouchableOpacity>
      </View>

      {/* WICKET MODAL */}
      <Modal visible={wicketModalOpen} transparent animationType="slide">
        <View className="flex-1 bg-black/90 justify-end">
          <View className="bg-gray-900 rounded-t-3xl p-6 h-[75%]">
            <View className="flex-row justify-between items-center mb-6">
               <Text className="text-xl font-bold text-red-500">Wicket Fall</Text>
               <TouchableOpacity onPress={resetWicketState}>
                  <Text className="text-gray-400 font-bold">Cancel</Text>
               </TouchableOpacity>
            </View>

            <ScrollView>
               <Text className="text-xs font-bold text-gray-500 uppercase mb-3">Dismissal Type</Text>
               <View className="flex-row flex-wrap gap-2 mb-6">
                  {Object.values(WicketType).map((w) => (
                    <TouchableOpacity 
                      key={w}
                      onPress={() => {
                        setSelectedWicketType(w);
                        if(w === WicketType.BOWLED || w === WicketType.LBW || w === WicketType.HIT_WICKET) {
                          setSelectedFielder('');
                        }
                      }}
                      className={`px-4 py-3 rounded-lg border ${selectedWicketType === w ? 'bg-red-600 border-red-500' : 'bg-gray-800 border-gray-700'}`}
                    >
                      <Text className={`font-bold ${selectedWicketType === w ? 'text-white' : 'text-gray-400'}`}>{w}</Text>
                    </TouchableOpacity>
                  ))}
               </View>

               {selectedWicketType && (
                 <View>
                    {/* Runs Completed Logic for Run Outs or Crossing */}
                    <View className="mb-6 bg-gray-800 p-4 rounded-xl border border-gray-700">
                       <Text className="text-xs font-bold text-gray-500 uppercase mb-3">Runs Completed Before Wicket</Text>
                       <View className="flex-row items-center justify-center gap-6">
                          <TouchableOpacity onPress={() => setCompletedRuns(Math.max(0, completedRuns - 1))} className="p-2 bg-gray-700 rounded-full">
                             <Minus size={20} color="white" />
                          </TouchableOpacity>
                          <Text className="text-3xl font-black text-white">{completedRuns}</Text>
                          <TouchableOpacity onPress={() => setCompletedRuns(completedRuns + 1)} className="p-2 bg-gray-700 rounded-full">
                             <Plus size={20} color="white" />
                          </TouchableOpacity>
                       </View>
                    </View>

                    {selectedWicketType === WicketType.RUN_OUT && (
                       <View className="mb-6">
                         <Text className="text-xs font-bold text-gray-500 uppercase mb-3">Who is Out?</Text>
                         <View className="flex-row gap-2">
                           <TouchableOpacity onPress={() => setWhoIsOut('striker')} className={`flex-1 p-3 rounded-lg border ${whoIsOut === 'striker' ? 'bg-blue-600 border-blue-500' : 'bg-gray-800 border-gray-700'}`}>
                             <Text className="text-white font-bold text-center">{striker?.name}</Text>
                           </TouchableOpacity>
                           <TouchableOpacity onPress={() => setWhoIsOut('nonStriker')} className={`flex-1 p-3 rounded-lg border ${whoIsOut === 'nonStriker' ? 'bg-blue-600 border-blue-500' : 'bg-gray-800 border-gray-700'}`}>
                             <Text className="text-white font-bold text-center">{nonStriker?.name}</Text>
                           </TouchableOpacity>
                         </View>
                       </View>
                    )}

                    {needsFielder && (
                      <View>
                         <Text className="text-xs font-bold text-gray-500 uppercase mb-3">Fielder Involved</Text>
                         <View className="flex-row flex-wrap gap-2">
                            {matchState.bowlingTeam.players.map(p => (
                              <TouchableOpacity
                                key={p.id}
                                onPress={() => setSelectedFielder(p.name)}
                                className={`px-3 py-2 rounded border ${selectedFielder === p.name ? 'bg-blue-600 border-blue-500' : 'bg-gray-800 border-gray-700'}`}
                              >
                                <Text className={selectedFielder === p.name ? 'text-white font-bold' : 'text-gray-400'}>{p.name}</Text>
                              </TouchableOpacity>
                            ))}
                         </View>
                      </View>
                    )}
                 </View>
               )}
            </ScrollView>

            <TouchableOpacity 
               disabled={!selectedWicketType || (needsFielder && !selectedFielder)}
               onPress={handleWicketConfirm}
               className={`w-full py-4 rounded-xl mt-4 items-center ${!selectedWicketType ? 'bg-gray-800' : 'bg-red-600'}`}
            >
               <Text className={`font-bold text-lg ${!selectedWicketType ? 'text-gray-500' : 'text-white'}`}>CONFIRM WICKET</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {/* BOWLER SELECT MODAL */}
      <Modal visible={bowlerSelectOpen} transparent animationType="fade">
        <View className="flex-1 bg-black/90 justify-center p-6">
           <View className="bg-gray-900 rounded-2xl border border-gray-800 p-6 max-h-[60%]">
             <Text className="text-xl font-bold text-white text-center mb-1">Select New Bowler</Text>
             <Text className="text-xs text-gray-500 text-center mb-4">Previous over completed</Text>
             <ScrollView>
                {matchState.bowlingTeam.players.filter(p => p.id !== matchState.currentBowlerId).map(p => (
                  <TouchableOpacity
                    key={p.id}
                    onPress={() => handleChangeBowler(p.id)}
                    className="p-4 bg-gray-800 rounded-xl mb-2 flex-row justify-between items-center border border-gray-700"
                  >
                    <View>
                       <Text className="font-bold text-white">{p.name}</Text>
                       <Text className="text-xs text-gray-500">{p.wickets} wkts • {Math.floor(p.ballsBowled/6)}.{p.ballsBowled%6} ov</Text>
                    </View>
                    <ChevronDown className="-rotate-90" size={16} color="gray" />
                  </TouchableOpacity>
                ))}
             </ScrollView>
           </View>
        </View>
      </Modal>
    </View>
  );
};

