const API_KEY = getApiKey();
let ai: GoogleGenAI | null = null;
if (API_KEY) {
  ai = new GoogleGenAI({ apiKey: API_KEY });
}

export const generateCommentary = async (lastBall: BallEvent, state: MatchState): Promise<string> => {
  if (!ai) return "Gemini AI: Add API Key to env to enable commentary.";

  const prompt = `
    Context: Cricket Match. 
    Score: ${state.totalRuns}/${state.wickets} in ${state.currentOver}.${state.currentBall}.
    Event: ${lastBall.description}.

    Write a short (max 12 words) energetic commentary line.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text ? response.text.trim() : "Great shot!";
  } catch (error) {
    return "What a delivery!";
  }
};

export const askRuleQuestion = async (query: string): Promise<string> => {
  if (!ai) return "AI service unavailable.";
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `Answer this cricket rule question briefly (ICC Conditions): ${query}`,
    });
    return response.text || "Rule check failed.";
  } catch (error) {
    return "Unable to fetch rule.";
  }
};

export const generateMatchSummary = async (state: MatchState): Promise<string> => {
  if (!ai) return "AI service unavailable.";

  const prompt = `Write a 2-sentence summary for a match where ${state.battingTeam.name} scored ${state.totalRuns}/${state.wickets}.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text || "Match Completed.";
  } catch (error) {
    return "Match concluded.";
  }
};

import AsyncStorage from '@react-native-async-storage/async-storage';
import { SavedTeam } from '../types';

const TEAMS_KEY = 'cricket_app_teams';

export const getSavedTeams = async (): Promise<SavedTeam[]> => {
  try {
    const data = await AsyncStorage.getItem(TEAMS_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    return [];
  }
};

export const saveTeam = async (team: SavedTeam) => {
  const teams = await getSavedTeams();
  const index = teams.findIndex(t => t.id === team.id);
  if (index >= 0) teams[index] = team;
  else teams.push(team);
  await AsyncStorage.setItem(TEAMS_KEY, JSON.stringify(teams));
};

export const deleteTeam = async (teamId: string) => {
  const teams = await getSavedTeams();
  const newTeams = teams.filter(t => t.id !== teamId);
  await AsyncStorage.setItem(TEAMS_KEY, JSON.stringify(newTeams));
};

export const seedDefaultTeams = async () => {
  const teams = await getSavedTeams();
  if (teams.length === 0) {
    const defaultTeam: SavedTeam = {
      id: 'taxila-tigers-default',
      name: 'Taxila Tigers',
      logoUrl: '',
      squad: Array.from({ length: 15 }, (_, i) => `Player ${i + 1}`)
    };
    await saveTeam(defaultTeam);
    await saveTeam({
        id: 'opponents-default',
        name: 'Royal Strikers',
        logoUrl: '',
        squad: Array.from({ length: 15 }, (_, i) => `Striker ${i + 1}`)
    });
  }
};

