export const MatchSetup: React.FC<Props> = ({ onNext, onViewStats, onManageTeams }) => {
  const [teams, setTeams] = useState<SavedTeam[]>([]);
  const [homeTeamId, setHomeTeamId] = useState('');
  const [awayTeamId, setAwayTeamId] = useState('');
  const [overs, setOvers] = useState('20');

  useEffect(() => {
    const init = async () => {
      await seedDefaultTeams();
      const saved = await getSavedTeams();
      setTeams(saved);
      if (saved.length > 0) setHomeTeamId(saved[0].id);
      if (saved.length > 1) setAwayTeamId(saved[1].id);
    };
    init();
  }, []);

  const handleNext = () => {
    const home = teams.find(t => t.id === homeTeamId);
    const away = teams.find(t => t.id === awayTeamId);
    if (!home || !away) return Alert.alert("Error", "Please select both teams.");
    if (home.id === away.id) return Alert.alert("Error", "Teams must be different.");
    onNext(home, away, parseInt(overs) || 20);
  };

  return (
    <ScrollView className="flex-1 bg-tiger-black" contentContainerStyle={{ padding: 24 }}>
        <View className="items-center mb-8 pt-8">
