import React, { useState } from 'react';
import { View, StatusBar } from 'react-native';
import { MatchSetup } from './components/MatchSetup';
import { TeamManager } from './components/TeamManager';
import { SquadSelection } from './components/SquadSelection';
import { TossScreen } from './components/TossScreen';
import { OpenerSelection } from './components/OpenerSelection';
import { ScoringDashboard } from './components/ScoringDashboard';
import { MatchSummary } from './components/MatchSummary';
import { StatsDashboard } from './components/StatsDashboard';
import { InningsBreak } from './components/InningsBreak';
import { MatchState, SavedTeam, Player } from './types';

type ViewState = 'setup' | 'teams' | 'stats' | 'squad' | 'toss' | 'openers' | 'scoring' | 'break' | 'summary';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('setup');
  const [setupData, setSetupData] = useState<{home: SavedTeam, away: SavedTeam, overs: number} | null>(null);
  const [squads, setSquads] = useState<{homeXI: string[], awayXI: string[]} | null>(null);
  const [matchState, setMatchState] = useState<MatchState | null>(null);
  const [undoStack, setUndoStack] = useState<MatchState[]>([]);
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);

  const createPlayers = (names: string[]): Player[] => names.map(name => ({
      id: Math.random().toString(36).substr(2, 9),
      name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false,
      ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0
  }));

  const handleSetupComplete = (home: SavedTeam, away: SavedTeam, overs: number) => {
    setSetupData({ home, away, overs });
    setView('squad');
  };

  const handleSquadConfirm = (homeXI: string[], awayXI: string[]) => {
    setSquads({ homeXI, awayXI });
    setView('toss');
  };

  const handleTossComplete = (winner: string, decision: 'bat' | 'bowl') => {
    if (!setupData || !squads) return;
    const isHomeBatting = (winner === setupData.home.name && decision === 'bat') || (winner === setupData.away.name && decision === 'bowl');

    const battingTeam = isHomeBatting ? setupData.home : setupData.away;
    const bowlingTeam = isHomeBatting ? setupData.away : setupData.home;
    const battingXI = isHomeBatting ? squads.homeXI : squads.awayXI;
    const bowlingXI = isHomeBatting ? squads.awayXI : squads.homeXI;

    const initialState: MatchState = {
      battingTeam: { name: battingTeam.name, players: createPlayers(battingXI), isBatting: true, logoUrl: battingTeam.logoUrl },
      bowlingTeam: { name: bowlingTeam.name, players: createPlayers(bowlingXI), isBatting: false, logoUrl: bowlingTeam.logoUrl },
      tossWinner: winner,
      tossDecision: decision,
      totalOvers: setupData.overs,
      currentOver: 0, currentBall: 0, totalRuns: 0, wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: '', nonStrikerId: '', currentBowlerId: '',
      ballHistory: [], matchStatus: 'LIVE', inningsNumber: 1
    };
    setMatchState(initialState);
    setView('openers');
  };

  const handleStartInnings = (strikerId: string, nonStrikerId: string, bowlerId: string) => {
    if (!matchState) return;
    setMatchState({ ...matchState, strikerId, nonStrikerId, currentBowlerId: bowlerId });
    setUndoStack([]);
    setView('scoring');
  };

  const startSecondInnings = () => {
    if (!matchState) return;
    const newBatting = { ...matchState.bowlingTeam, isBatting: true };
    const newBowling = { ...matchState.battingTeam, isBatting: false };

    // Reset stats for new innings
    newBatting.players.forEach(p => { p.runs=0; p.balls=0; p.fours=0; p.sixes=0; p.isOut=false; });
    newBowling.players.forEach(p => { p.ballsBowled=0; p.runsConceded=0; p.wickets=0; p.maidens=0; });

    const nextState: MatchState = {
      ...matchState,
      battingTeam: newBatting,
      bowlingTeam: newBowling,
      currentOver: 0, currentBall: 0, totalRuns: 0, wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      ballHistory: [], matchStatus: 'LIVE', inningsNumber: 2,
      target: matchState.totalRuns + 1,
      strikerId: '', nonStrikerId: '', currentBowlerId: ''
    };
    setMatchState(nextState);
    setView('openers');
  };

  const handleStateUpdate = (newState: MatchState) => {
    if (matchState) setUndoStack([...undoStack, matchState]);
    setMatchState(newState);
  };

  const handleUndo = () => {
    if (undoStack.length > 0) {
      const prev = undoStack[undoStack.length - 1];
      setMatchState(prev);
      setUndoStack(undoStack.slice(0, -1));
    }
  };

  return (
    <View className="flex-1 bg-tiger-black h-full w-full">
      <StatusBar barStyle="light-content" backgroundColor="#0f172a" />
      {view === 'setup' && <MatchSetup onNext={handleSetupComplete} onViewStats={() => setView('stats')} onManageTeams={() => setView('teams')} />}
      {view === 'teams' && <TeamManager onBack={() => setView('setup')} />}
      {view === 'stats' && <StatsDashboard matchHistory={matchHistory} onBack={() => setView('setup')} />}
      {view === 'squad' && setupData && <SquadSelection homeTeam={setupData.home} awayTeam={setupData.away} onConfirm={handleSquadConfirm} onBack={() => setView('setup')} />}
      {view === 'toss' && setupData && <TossScreen homeTeam={setupData.home.name} awayTeam={setupData.away.name} onTossComplete={handleTossComplete} onBack={() => setView('squad')} />}
      {view === 'openers' && matchState && <OpenerSelection battingTeamName={matchState.battingTeam.name} bowlingTeamName={matchState.bowlingTeam.name} battingPlayers={matchState.battingTeam.players} bowlingPlayers={matchState.bowlingTeam.players} inningsNumber={matchState.inningsNumber} onStart={handleStartInnings} />}
      {view === 'scoring' && matchState && <ScoringDashboard matchState={matchState} setMatchState={handleStateUpdate} onUndo={handleUndo} canUndo={undoStack.length > 0} onFinish={() => setView(matchState.matchStatus === 'INNINGS_BREAK' ? 'break' : 'summary')} />}
      {view === 'break' && matchState && <InningsBreak matchState={matchState} onStartSecondInnings={startSecondInnings} />}
      {view === 'summary' && matchState && <MatchSummary matchState={matchState} onSaveAndExit={(s) => { setMatchHistory([...matchHistory, s]); setView('setup'); }} />}
    </View>
  );
};

export default App;

