import { MatchState, Player } from '../types';

export interface CareerStats {
  name: string;
  matches: number;
  runs: number;
  wickets: number;
  highestScore: number;
  bestBowling: { wickets: number; runs: number };
}

export const aggregateStats = (history: MatchState[], teamFilter: string): CareerStats[] => {
  const statsMap = new Map<string, CareerStats>();

  const update = (p: Player) => {
    const key = p.name.trim();
    if (!statsMap.has(key)) {
      statsMap.set(key, { name: key, matches: 0, runs: 0, wickets: 0, highestScore: 0, bestBowling: { wickets: 0, runs: 999 } });
    }
    const s = statsMap.get(key)!;
    s.matches++;
    s.runs += p.runs;
    s.wickets += p.wickets;
    if (p.runs > s.highestScore) s.highestScore = p.runs;
    if (p.wickets > s.bestBowling.wickets || (p.wickets === s.bestBowling.wickets && p.runsConceded < s.bestBowling.runs)) {
      s.bestBowling = { wickets: p.wickets, runs: p.runsConceded };
    }
  };

  history.forEach(m => {
    if (m.battingTeam.name === teamFilter) m.battingTeam.players.forEach(update);
    if (m.bowlingTeam.name === teamFilter) m.bowlingTeam.players.forEach(update);
  });

  return Array.from(statsMap.values());
};

