export const TeamManager: React.FC<Props> = ({ onBack }) => {
  const [teams, setTeams] = useState<SavedTeam[]>([]);
  const [editing, setEditing] = useState<SavedTeam | null>(null);
  const [name, setName] = useState('');
  const [squad, setSquad] = useState('');

  useEffect(() => { load(); }, []);
  const load = async () => { setTeams(await getSavedTeams()); };

  const handleSave = async () => {
    if (!name || squad.split('\n').length < 11) return Alert.alert("Invalid", "Name + 11 players required");
    await saveTeam({ id: editing?.id || Date.now().toString(), name, logoUrl: '', squad: squad.split('\n').filter(x => x) });
