  if (editing) return (
      <View className="flex-1 bg-tiger-black p-4">
         <TextInput value={name} onChangeText={setName} placeholder="Team Name" placeholderTextColor="gray" className="bg-gray-800 text-white p-4 rounded-xl mb-4" />
