    <View className="flex-1 bg-tiger-black p-4">
       <View className="flex-row justify-between mb-4">
         <TouchableOpacity onPress={onBack}><ArrowLeft color="white" /></TouchableOpacity>
         <TouchableOpacity onPress={() => { setEditing({ id: '', name: '', logoUrl: '', squad: [] }); setName(''); setSquad(''); }}><Plus color="#fbbf24" /></TouchableOpacity>
       </View>
       <ScrollView>
         {teams.map(t => (
            <View key={t.id} className="bg-gray-800 p-4 rounded-xl mb-2 flex-row justify-between">
