import React, { useState } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Alert } from 'react-native';
import { SavedTeam } from '../types';

interface Props { homeTeam: SavedTeam; awayTeam: SavedTeam; onConfirm: (h: string[], a: string[]) => void; onBack: () => void; }

export const SquadSelection: React.FC<Props> = ({ homeTeam, awayTeam, onConfirm, onBack }) => {
  const [homeXI, setHomeXI] = useState<string[]>([]);
  const [awayXI, setAwayXI] = useState<string[]>([]);
  const [tab, setTab] = useState<'home'|'away'>('home');

  const toggle = (p: string) => {
    const list = tab === 'home' ? homeXI : awayXI;
    const setList = tab === 'home' ? setHomeXI : setAwayXI;
    if (list.includes(p)) setList(list.filter(x => x !== p));
    else if (list.length < 11) setList([...list, p]);
  };

  return (
    <View className="flex-1 bg-tiger-black p-4">
      <View className="flex-row bg-gray-800 p-1 rounded mb-4">
         <TouchableOpacity onPress={() => setTab('home')} className={`flex-1 p-2 items-center ${tab === 'home' ? 'bg-tiger-gold' : ''}`}><Text>{homeTeam.name}</Text></TouchableOpacity>
         <TouchableOpacity onPress={() => setTab('away')} className={`flex-1 p-2 items-center ${tab === 'away' ? 'bg-tiger-gold' : ''}`}><Text>{awayTeam.name}</Text></TouchableOpacity>
      </View>
      <ScrollView>
         {(tab === 'home' ? homeTeam : awayTeam).squad.map((p, i) => (
            <TouchableOpacity key={i} onPress={() => toggle(p)} className={`p-4 mb-2 rounded border ${ (tab === 'home' ? homeXI : awayXI).includes(p) ? 'bg-tiger-gold border-tiger-gold' : 'border-gray-700'}`}>
               <Text className={(tab === 'home' ? homeXI : awayXI).includes(p) ? 'text-black font-bold' : 'text-gray-400'}>{p}</Text>
            </TouchableOpacity>
         ))}
      </ScrollView>
      <TouchableOpacity onPress={() => homeXI.length === 11 && awayXI.length === 11 ? onConfirm(homeXI, awayXI) : Alert.alert("Select 11 players each")} className="bg-tiger-gold p-4 rounded-xl items-center mt-4"><Text className="font-bold">Confirm Squads</Text></TouchableOpacity>
    </View>
  );
};

