import React, { useState, useEffect, useMemo } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Modal } from 'react-native';
import { MatchState, ExtraType, WicketType, WicketDetails } from '../types';
import { processBall, getPlayer, calculateStrikeRate, calculateEconomy } from '../utils/cricketLogic';
import { generateCommentary } from '../services/geminiService';
import { Mic, RotateCcw, Activity, Users, Circle, Trophy, ChevronDown, RefreshCw } from 'lucide-react-native';

interface Props {
  matchState: MatchState;
  setMatchState: (state: MatchState) => void;
  onUndo: () => void;
  canUndo: boolean;
  onFinish: () => void;
}

export const ScoringDashboard: React.FC<Props> = ({ matchState, setMatchState, onUndo, canUndo, onFinish }) => {
  const [wicketModalOpen, setWicketModalOpen] = useState(false);
  const [bowlerSelectOpen, setBowlerSelectOpen] = useState(false);
  const [selectedWicketType, setSelectedWicketType] = useState<WicketType | null>(null);
  const [selectedFielder, setSelectedFielder] = useState<string>('');
  const [completedRuns, setCompletedRuns] = useState(0);

  const [extraType, setExtraType] = useState<ExtraType>(ExtraType.NONE);
  const [commentary, setCommentary] = useState<string>("Ready for the first ball...");

  const striker = getPlayer(matchState.battingTeam.players, matchState.strikerId);
  const nonStriker = getPlayer(matchState.battingTeam.players, matchState.nonStrikerId);
  const bowler = getPlayer(matchState.bowlingTeam.players, matchState.currentBowlerId);

  // Derived Stats
  const oversBowled = matchState.currentOver + (matchState.currentBall / 6);
  const crr = oversBowled > 0 ? (matchState.totalRuns / oversBowled).toFixed(2) : '0.00';

  const ballsRemaining = (matchState.totalOvers * 6) - (matchState.currentOver * 6 + matchState.currentBall);
  const runsRequired = matchState.target ? matchState.target - matchState.totalRuns : 0;
  const rrr = (matchState.inningsNumber === 2 && ballsRemaining > 0) 
    ? ((runsRequired / ballsRemaining) * 6).toFixed(2) 
    : null;

  // "This Over" History
  const thisOverBalls = useMemo(() => {
    return matchState.ballHistory.filter(
      b => b.inningsNumber === matchState.inningsNumber && b.overNumber === matchState.currentOver
    );
  }, [matchState.ballHistory, matchState.currentOver, matchState.inningsNumber]);

  useEffect(() => {
    // Prompt for new bowler at start of new over (if history exists)
    if (matchState.currentBall === 0 && matchState.currentOver > 0 && matchState.ballHistory.length > 0) {
      setBowlerSelectOpen(true);
    }
  }, [matchState.currentOver]);

  useEffect(() => {
    if (matchState.matchStatus !== 'LIVE') onFinish();
  }, [matchState.matchStatus]);

  const handleScore = (runs: number) => {
    processAndSetState(runs, false, undefined);
  };

  const handleWicketConfirm = () => {
    if (!selectedWicketType) return;
    const details: WicketDetails = {
      type: selectedWicketType,
      fielderName: selectedFielder || undefined,
      isStrikerOut: true // Default to striker for UI simplicity
    };
    processAndSetState(completedRuns, true, details);
    setWicketModalOpen(false);
    setSelectedWicketType(null);
    setCompletedRuns(0);
  };

  const processAndSetState = (runs: number, isWicket: boolean, wicketDetails: WicketDetails | undefined) => {
    let nextBatsmanId = undefined;
    if (isWicket) {
      const nextBat = matchState.battingTeam.players.find(p => !p.isOut && p.id !== matchState.strikerId && p.id !== matchState.nonStrikerId);
      if (nextBat) nextBatsmanId = nextBat.id;
    }

    const newState = processBall(matchState, runs, extraType, isWicket, wicketDetails, nextBatsmanId);
    setMatchState(newState);
    setExtraType(ExtraType.NONE); // Reset extra selection

    generateCommentary(newState.ballHistory[newState.ballHistory.length - 1], newState).then(setCommentary);
  };

  const handleChangeBowler = (bowlerId: string) => {
    setMatchState({ ...matchState, currentBowlerId: bowlerId });
    setBowlerSelectOpen(false);
  };

  const renderBallBadge = (ball: any, index: number) => {
    let text = ball.runs.toString();
    let bgClass = "bg-gray-700";
    let textClass = "text-white";

    if (ball.isWicket) {
      text = "W";
      bgClass = "bg-red-600";
    } else if (ball.extraType !== ExtraType.NONE) {
      text = ball.extraType === ExtraType.WIDE ? "wd" : ball.extraType === ExtraType.NO_BALL ? "nb" : ball.extraType === ExtraType.BYE ? "b" : "lb";
      if (ball.runs > 0 && (ball.extraType === ExtraType.WIDE || ball.extraType === ExtraType.NO_BALL)) {
          text += `+${ball.runs}`;
      }
      if (ball.extraType === ExtraType.BYE || ball.extraType === ExtraType.LEG_BYE) {
        text = ball.runs + (ball.extraType === ExtraType.BYE ? "b" : "lb");
      }
      bgClass = "bg-blue-600";
    } else if (ball.runs === 4) {
      bgClass = "bg-green-600";
    } else if (ball.runs === 6) {
      bgClass = "bg-tiger-gold";
      textClass = "text-black";
    } else if (ball.runs === 0) {
      text = "•";
      textClass = "text-gray-400";
    }

    return (
      <View key={index} className={`w-8 h-8 rounded-full items-center justify-center mr-2 ${bgClass}`}>
        <Text className={`text-xs font-bold ${textClass}`}>{text}</Text>
      </View>
    );
  };

  return (
    <View className="flex-1 bg-tiger-black">
      {/* --- HEADER SECTION: Scoreboard --- */}
      <View className="bg-gray-900 pb-2 shadow-lg z-10">
        {/* Top Row: Team & Main Score */}
        <View className="flex-row justify-between items-start px-4 pt-4 pb-2">
          <View>
            <Text className="text-gray-400 font-bold uppercase text-xs tracking-widest mb-1">
              {matchState.battingTeam.name}
            </Text>
            <View className="flex-row items-baseline gap-2">
              <Text className="text-5xl font-black text-white leading-tight">
                {matchState.totalRuns}<Text className="text-gray-500">/</Text>{matchState.wickets}
              </Text>
              <Text className="text-lg text-tiger-gold font-mono font-bold">
                {matchState.currentOver}.{matchState.currentBall} <Text className="text-xs text-gray-500 font-sans">Ov</Text>
              </Text>
            </View>
          </View>

          <View className="items-end space-y-1">
             <View className="flex-row items-center gap-1 bg-gray-800 px-2 py-1 rounded">
               <Activity size={12} color="#fbbf24" />
               <Text className="text-xs text-tiger-gold font-bold">CRR {crr}</Text>
             </View>
             {matchState.inningsNumber === 2 && (
               <View className="flex-row items-center gap-1 bg-gray-800 px-2 py-1 rounded">
                  <Trophy size={12} color="#60a5fa" />
                  <Text className="text-xs text-blue-400 font-bold">Target {matchState.target}</Text>
               </View>
             )}
             {rrr && (
                <Text className="text-[10px] text-red-400 font-bold uppercase">Req {rrr}</Text>
             )}
          </View>
        </View>

        {/* This Over Strip */}
        <View className="px-4 py-2 border-t border-gray-800 flex-row items-center">
          <Text className="text-xs text-gray-500 font-bold uppercase mr-3 w-16">This Over</Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-1">
             {thisOverBalls.length === 0 ? (
               <Text className="text-gray-600 text-xs italic">New over starting...</Text>
             ) : (
               thisOverBalls.map((b, i) => renderBallBadge(b, i))
             )}
          </ScrollView>
        </View>
      </View>

      {/* --- STATS CARD SECTION --- */}
      <View className="flex-1 bg-tiger-black">
        {/* Batsmen Table */}
        <View className="bg-gray-900/50 mb-1 border-b border-gray-800">
           <View className="flex-row px-4 py-2 border-b border-gray-800/50 bg-gray-800/30">
              <Text className="flex-[3] text-[10px] text-gray-500 font-bold uppercase">Batter</Text>
              <Text className="flex-1 text-[10px] text-gray-500 font-bold text-center uppercase">R</Text>
              <Text className="flex-1 text-[10px] text-gray-500 font-bold text-center uppercase">B</Text>
              <Text className="flex-1 text-[10px] text-gray-500 font-bold text-center uppercase">4s</Text>
              <Text className="flex-1 text-[10px] text-gray-500 font-bold text-center uppercase">6s</Text>
              <Text className="flex-1 text-[10px] text-gray-500 font-bold text-right uppercase">SR</Text>
           </View>

           {[striker, nonStriker].map((p, i) => (
             p ? (
              <View key={p.id} className={`flex-row px-4 py-3 items-center ${i === 0 ? 'bg-tiger-gold/5 border-l-2 border-tiger-gold' : 'border-l-2 border-transparent'}`}>
                <View className="flex-[3] flex-row items-center gap-1">
                  <Text className={`font-bold ${i === 0 ? 'text-white' : 'text-gray-400'}`}>{p.name}</Text>
                  {i === 0 && <Activity size={10} color="#fbbf24" />}
                </View>
                <Text className="flex-1 text-white font-bold text-center">{p.runs}</Text>
                <Text className="flex-1 text-gray-400 text-center text-xs">{p.balls}</Text>
                <Text className="flex-1 text-gray-400 text-center text-xs">{p.fours}</Text>
                <Text className="flex-1 text-gray-400 text-center text-xs">{p.sixes}</Text>
                <Text className="flex-1 text-gray-400 text-right text-xs">{calculateStrikeRate(p.runs, p.balls)}</Text>
              </View>
             ) : null
           ))}
        </View>

        {/* Bowler Stats */}
        <View className="bg-gray-900/50 border-b border-gray-800">
          <TouchableOpacity onPress={() => setBowlerSelectOpen(true)} className="flex-row px-4 py-3 items-center justify-between">
              <View className="flex-row items-center gap-2">
                 <View>
                   <Text className="text-white font-bold text-sm">{bowler?.name}</Text>
                   <Text className="text-[10px] text-blue-400 font-bold uppercase">Bowling Now</Text>
                 </View>
                 <ChevronDown size={14} color="gray" />
              </View>

              <View className="flex-row gap-4">
                 <View className="items-end">
                    <Text className="text-[10px] text-gray-500 uppercase font-bold">Fig</Text>
                    <Text className="text-white font-bold">{bowler?.wickets}-{bowler?.runsConceded}</Text>
                 </View>
                 <View className="items-end">
                    <Text className="text-[10px] text-gray-500 uppercase font-bold">Ov</Text>
                    <Text className="text-white font-bold">{bowler ? Math.floor(bowler.ballsBowled/6) + '.' + (bowler.ballsBowled%6) : '0.0'}</Text>
                 </View>
                 <View className="items-end">
                    <Text className="text-[10px] text-gray-500 uppercase font-bold">Eco</Text>
                    <Text className="text-white font-bold">{bowler ? calculateEconomy(bowler.runsConceded, bowler.ballsBowled) : '0.00'}</Text>
                 </View>
              </View>
          </TouchableOpacity>
        </View>

        {/* Commentary Ticker */}
        <View className="flex-1 p-4">
           <View className="bg-gray-800/60 p-3 rounded-xl border border-gray-700/50 flex-row gap-3">
              <Mic size={16} color="#fbbf24" className="mt-1" />
              <Text className="text-gray-300 text-sm italic leading-5 flex-1">{commentary}</Text>
           </View>
        </View>
      </View>

      {/* --- CONTROLS SECTION --- */}
      <View className="bg-gray-900 p-4 pb-8 rounded-t-3xl border-t border-gray-800">

         {/* Extras Row */}
         <View className="flex-row gap-2 mb-4">
            {[ExtraType.WIDE, ExtraType.NO_BALL, ExtraType.BYE, ExtraType.LEG_BYE].map((type) => {
              const isActive = extraType === type;
              return (
                <TouchableOpacity 
                  key={type} 
                  onPress={() => setExtraType(isActive ? ExtraType.NONE : type)} 
                  className={`flex-1 py-2 rounded-lg border items-center justify-center ${isActive ? 'bg-blue-600 border-blue-400' : 'bg-gray-800 border-gray-700'}`}
                >
                  <Text className={`text-[10px] font-black uppercase ${isActive ? 'text-white' : 'text-gray-400'}`}>
                    {type === ExtraType.NO_BALL ? 'NB' : type}
                  </Text>
                </TouchableOpacity>
              )
            })}
         </View>

         {/* Scoring Grid */}
         <View className="flex-row gap-3 h-48">
             {/* Left Column: Runs */}
             <View className="flex-[3] gap-3">
                <View className="flex-1 flex-row gap-3">
                   {[0, 1, 2].map(run => (
                     <TouchableOpacity key={run} onPress={() => handleScore(run)} className="flex-1 bg-gray-800 rounded-xl items-center justify-center border-b-4 border-gray-950 active:border-b-0 active:mt-1">
                        <Text className="text-2xl font-bold text-white">{run}</Text>
                     </TouchableOpacity>
                   ))}
                </View>
                <View className="flex-1 flex-row gap-3">
                   {[3, 4, 6].map(run => (
                     <TouchableOpacity key={run} onPress={() => handleScore(run)} className={`flex-1 rounded-xl items-center justify-center border-b-4 active:border-b-0 active:mt-1 ${run >= 4 ? 'bg-tiger-gold border-tiger-orange' : 'bg-gray-800 border-gray-950'}`}>
                        <Text className={`text-2xl font-black ${run >= 4 ? 'text-black' : 'text-white'}`}>{run}</Text>
                     </TouchableOpacity>
                   ))}
                </View>
             </View>

             {/* Right Column: Actions */}
             <View className="flex-1 gap-3">
                <TouchableOpacity onPress={() => setWicketModalOpen(true)} className="flex-1 bg-red-600 rounded-xl items-center justify-center border-b-4 border-red-800 active:border-b-0 active:mt-1">
                   <Text className="text-white font-black text-xs uppercase">OUT</Text>
                </TouchableOpacity>
                <TouchableOpacity onPress={onUndo} disabled={!canUndo} className={`flex-1 rounded-xl items-center justify-center border-b-4 active:border-b-0 active:mt-1 ${canUndo ? 'bg-gray-700 border-gray-900' : 'bg-gray-800/50 border-transparent'}`}>
                   <RotateCcw size={20} color={canUndo ? "white" : "gray"} />
                </TouchableOpacity>
             </View>
         </View>
      </View>

      {/* --- MODALS --- */}

      {/* Wicket Modal */}
      <Modal visible={wicketModalOpen} transparent animationType="slide">
        <View className="flex-1 bg-black/80 justify-end">
          <View className="bg-gray-900 rounded-t-3xl p-6">
            <Text className="text-xl font-bold text-white mb-6 text-center">How was he out?</Text>
            <View className="flex-row flex-wrap gap-2 mb-6 justify-center">
                {Object.values(WicketType).map((w) => (
                  <TouchableOpacity key={w} onPress={() => setSelectedWicketType(w)} className={`px-5 py-3 rounded-full border ${selectedWicketType === w ? 'bg-red-600 border-red-500' : 'bg-gray-800 border-gray-700'}`}>
