             <View className="flex-row justify-between items-center mb-6">
                <Text className="text-xl font-bold text-white">Select Bowler</Text>
                <RefreshCw size={18} color="#fbbf24" />
             </View>
             <ScrollView>
                {matchState.bowlingTeam.players.filter(p => p.id !== matchState.currentBowlerId).map(p => (
                  <TouchableOpacity key={p.id} onPress={() => handleChangeBowler(p.id)} className="p-4 bg-gray-800 rounded-xl mb-2 flex-row justify-between items-center border border-gray-700">
                     <View>
                        <Text className="font-bold text-white text-lg">{p.name}</Text>
                        <Text className="text-xs text-gray-500 mt-1">{p.wickets} Wickets • {calculateEconomy(p.runsConceded, p.ballsBowled)} Eco</Text>
                     </View>
                     <View className="bg-gray-700 px-3 py-1 rounded">
                        <Text className="text-xs text-gray-300">{Math.floor(p.ballsBowled/6)}.{p.ballsBowled%6} Ov</Text>
                     </View>
                  </TouchableOpacity>
                ))}
             </ScrollView>
           </View>
        </View>
      </Modal>
    </View>
  );
};

