                                            {idx + 1}
                                        </span>
                                        <span className="truncate">{p.name}</span>
                                    </div>
                                    <div className="font-bold text-tiger-gold">{p.runs}</div>
                                    <div className="text-gray-400">{p.ballsFaced}</div>
                                    <div className="text-gray-300 font-mono">{calcBatAvg(p.runs, p.outs)}</div>
                                    <div className="text-gray-300 font-mono">{calcBatSR(p.runs, p.ballsFaced)}</div>
