                ) : (
                    <>
                    <div className="grid grid-cols-6 bg-gray-750 p-3 border-b border-gray-700 text-[10px] sm:text-xs font-bold text-gray-400 uppercase tracking-wider text-center">
                        <div className="col-span-2 text-left pl-2">Player</div>
                        <div>Wkts</div>
                        <div>Runs</div>
                        <div>Econ</div>
                        <div>SR</div>
                    </div>
                    <div className="divide-y divide-gray-700/50">
                        {sortedPlayers.filter(p => p.ballsBowled > 0).length === 0 ? (
                             <div className="p-8 text-center text-gray-500 text-xs">No bowling records found.</div>
                        ) : (
                            sortedPlayers.filter(p => p.ballsBowled > 0).map((p, idx) => (
                                <div key={p.name} className="grid grid-cols-6 p-3 items-center text-xs sm:text-sm text-center hover:bg-gray-700/30 transition-colors">
                                    <div className="col-span-2 text-left font-bold text-white pl-2 flex items-center gap-2 overflow-hidden">
                                        <span className={`w-4 h-4 sm:w-5 sm:h-5 flex-shrink-0 flex items-center justify-center rounded-full text-[8px] sm:text-[10px] font-bold ${idx < 3 ? 'bg-tiger-gold text-black' : 'bg-gray-700 text-gray-400'}`}>
                                            {idx + 1}
                                        </span>
                                        <span className="truncate">{p.name}</span>
                                    </div>
                                    <div className="font-bold text-blue-400">{p.wickets}</div>
                                    <div className="text-gray-400">{p.runsConceded}</div>
                                    <div className="text-gray-300 font-mono">{calcBowlEcon(p.runsConceded, p.ballsBowled)}</div>
                                    <div className="text-gray-300 font-mono">{calcBowlSR(p.ballsBowled, p.wickets)}</div>
                                </div>
                            ))
                        )}
                    </div>
                    </>
                )}
            </div>

            <div className="text-[10px] text-center text-gray-500 mt-4 italic">
                * Avg: Average | SR: Strike Rate | Econ: Economy Rate
