import React, { useEffect, useState, useMemo } from 'react';
import { MatchState, Player } from '../types';
import { generateMatchSummary } from '../services/geminiService';
import { Share2, Save, Trophy, Medal, Crown, Home } from 'lucide-react';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface Props {
  matchState: MatchState;
  onSaveAndExit: (match: MatchState) => void;
}

export const MatchSummary: React.FC<Props> = ({ matchState, onSaveAndExit }) => {
  const [report, setReport] = useState("Generating AI Match Report...");

  useEffect(() => {
    generateMatchSummary(matchState).then(setReport);
  }, []);

  // --- RESULT LOGIC ---
  const result = useMemo(() => {
    const { inningsNumber, totalRuns, wickets, target, firstInningsScore, battingTeam, bowlingTeam } = matchState;

    if (inningsNumber === 1) {
       return {
         winner: 'Innings Break',
         margin: 'First Innings Completed',
         winnerTeam: battingTeam.name,
         isTie: false,
         color: 'text-gray-400'
       };
    }

    const teamBattingSecond = battingTeam.name;
    const teamBattingFirst = firstInningsScore?.teamName || bowlingTeam.name;
    const targetScore = target || 0;

    // Logic: 
    // Batting Team (Chaser) Wins if totalRuns >= target
    // Bowling Team (Defender) Wins if totalRuns < target - 1
    // Tie if totalRuns === target - 1

    if (totalRuns >= targetScore) {
       const wicketsLeft = 10 - wickets;
       return {
         winner: teamBattingSecond,
         margin: `won by ${wicketsLeft} wicket${wicketsLeft !== 1 ? 's' : ''}`,
         winnerTeam: teamBattingSecond,
         isTie: false,
         color: 'text-tiger-gold'
       };
    } else if (totalRuns < targetScore - 1) {
       const runDiff = (targetScore - 1) - totalRuns;
       return {
         winner: teamBattingFirst,
         margin: `won by ${runDiff} run${runDiff !== 1 ? 's' : ''}`,
         winnerTeam: teamBattingFirst,
         isTie: false,
         color: 'text-tiger-gold'
       };
    } else {
       return {
         winner: 'Match Tied',
         margin: 'Scores Level',
         winnerTeam: 'Draw',
         isTie: true,
         color: 'text-gray-200'
       };
    }
  }, [matchState]);

  // --- MVP LOGIC ---
  const mvp = useMemo(() => {
    // Combine players from both teams. 
    // Note: In 2nd innings, battingTeam is Team B, bowlingTeam is Team A. Both have full match stats.
    const allPlayers = [
        ...matchState.battingTeam.players.map(p => ({...p, teamName: matchState.battingTeam.name})), 
        ...matchState.bowlingTeam.players.map(p => ({...p, teamName: matchState.bowlingTeam.name}))
    ];

    // Score = Runs + (Wickets * 20)
    const scored = allPlayers.map(p => ({
        ...p,
        points: (p.runs * 1) + (p.wickets * 20) + (p.isOut ? 0 : 5) + (p.runs >= 50 ? 10 : 0) + (p.wickets >= 3 ? 10 : 0)
    }));

    // Sort desc
    return scored.sort((a, b) => b.points - a.points)[0];
  }, [matchState]);

  // --- DATA PREP ---
  const team1 = matchState.bowlingTeam; // Batted 1st
  const team2 = matchState.battingTeam; // Batted 2nd

  // If innings 1, setup is simpler
  const isInnings1 = matchState.inningsNumber === 1;

  return (
    <div className="flex flex-col h-full bg-tiger-black font-sans text-white overflow-y-auto">

      {/* --- HERO SECTION --- */}
      <div className="relative overflow-hidden bg-gradient-to-b from-gray-800 to-gray-900 border-b border-gray-800 p-8 text-center">
         {/* Background Decoration */}
         <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-20 pointer-events-none">
            <div className="absolute top-[-50%] left-[-50%] w-[200%] h-[200%] bg-[radial-gradient(circle,rgba(251,191,36,0.2)_0%,transparent_70%)] animate-pulse" />
         </div>

         <div className="relative z-10">
            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Match Result</h2>

            {result.isTie ? (
               <div className="text-5xl font-black text-white uppercase tracking-tighter mb-2">MATCH TIED</div>
            ) : (
               <div className="flex flex-col items-center gap-2">
                 <Trophy size={48} className="text-tiger-gold mb-2 drop-shadow-[0_0_15px_rgba(251,191,36,0.6)]" />
                 <h1 className="text-4xl sm:text-5xl font-black text-white uppercase italic tracking-tight leading-none">
                    {result.winner}
                 </h1>
                 <div className={`text-xl font-bold ${result.color} uppercase tracking-widest bg-black/30 px-4 py-1 rounded-full mt-2 border border-white/10`}>
                    {result.margin}
                 </div>
               </div>
            )}
         </div>
      </div>

      <div className="p-4 sm:p-6 space-y-6 max-w-4xl mx-auto w-full">

        {/* --- SCORE SUMMARY CARDS --- */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
           {/* Team 1 (Batted First) */}
           <div className={`p-4 rounded-xl border ${result.winnerTeam === team1.name ? 'bg-gradient-to-br from-gray-800 to-gray-900 border-tiger-gold shadow-[0_0_15px_rgba(251,191,36,0.1)]' : 'bg-gray-800 border-gray-700 opacity-80'}`}>
              <div className="flex justify-between items-start mb-2">
                 <span className="font-bold text-lg text-gray-200">{matchState.firstInningsScore?.teamName || team1.name}</span>
                 {result.winnerTeam === team1.name && <Crown size={16} className="text-tiger-gold" />}
              </div>
              <div className="flex items-baseline gap-2">
                 <span className="text-3xl font-black text-white">
                   {matchState.firstInningsScore ? matchState.firstInningsScore.runs : matchState.totalRuns}
                   <span className="text-xl text-gray-400">/{matchState.firstInningsScore ? matchState.firstInningsScore.wickets : matchState.wickets}</span>
                 </span>
                 <span className="text-xs text-gray-500 font-mono">
                   ({matchState.firstInningsScore ? matchState.firstInningsScore.overs : `${matchState.currentOver}.${matchState.currentBall}`})
                 </span>
              </div>
              <div className="text-xs text-gray-500 mt-2 uppercase tracking-wide font-bold">1st Innings</div>
           </div>

           {/* Team 2 (Batted Second) */}
           {!isInnings1 && (
             <div className={`p-4 rounded-xl border ${result.winnerTeam === team2.name ? 'bg-gradient-to-br from-gray-800 to-gray-900 border-tiger-gold shadow-[0_0_15px_rgba(251,191,36,0.1)]' : 'bg-gray-800 border-gray-700 opacity-80'}`}>
                <div className="flex justify-between items-start mb-2">
                   <span className="font-bold text-lg text-gray-200">{team2.name}</span>
                   {result.winnerTeam === team2.name && <Crown size={16} className="text-tiger-gold" />}
                </div>
                <div className="flex items-baseline gap-2">
                   <span className="text-3xl font-black text-white">
                     {matchState.totalRuns}
                     <span className="text-xl text-gray-400">/{matchState.wickets}</span>
                   </span>
                   <span className="text-xs text-gray-500 font-mono">
                     ({matchState.currentOver}.{matchState.currentBall})
                   </span>
                </div>
                <div className="text-xs text-gray-500 mt-2 uppercase tracking-wide font-bold">2nd Innings</div>
             </div>
           )}
        </div>

        {/* --- MAN OF THE MATCH --- */}
        {mvp && (
          <div className="bg-gradient-to-r from-gray-800 via-gray-900 to-gray-800 rounded-xl p-1 border border-tiger-gold/30 shadow-lg relative overflow-hidden group">
             <div className="absolute inset-0 bg-tiger-gold/5 opacity-0 group-hover:opacity-100 transition-opacity" />
             <div className="p-4 flex items-center gap-4 relative z-10">
                <div className="w-16 h-16 rounded-full bg-tiger-gold flex items-center justify-center text-black shadow-lg shadow-yellow-500/20">
                   <Medal size={32} />
                </div>
                <div className="flex-1">
                   <div className="text-xs font-bold text-tiger-gold uppercase tracking-widest mb-1">Player of the Match</div>
                   <div className="text-xl font-black text-white">{mvp.name}</div>
                   <div className="text-xs text-gray-400 font-medium">{mvp.teamName}</div>
                </div>
                <div className="text-right">
                   <div className="text-sm font-bold text-white">{mvp.runs} Runs</div>
                   {mvp.wickets > 0 && <div className="text-sm font-bold text-white">{mvp.wickets} Wickets</div>}
                   <div className="text-[10px] text-gray-500 mt-1">{mvp.points} Pts</div>
                </div>
             </div>
          </div>
        )}

        {/* --- AI REPORT --- */}
        <div className="bg-gray-800 rounded-xl p-6 border border-gray-700 shadow-md">
          <h3 className="text-xs font-bold text-tiger-gold uppercase tracking-widest mb-3 flex items-center gap-2">
            <span className="w-2 h-2 bg-tiger-gold rounded-full animate-pulse" /> AI Match Analysis
          </h3>
          <p className="text-gray-300 text-sm leading-relaxed pl-4 border-l-2 border-gray-600 italic">
            "{report}"
          </p>
        </div>

        {/* --- TOP PERFORMERS (Chart) --- */}
        <div className="bg-gray-800 rounded-xl p-6 border border-gray-700">
          <h3 className="text-xs font-bold text-gray-400 uppercase mb-4">Top Run Scorers</h3>
          <div className="h-48 w-full">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={[...team1.players, ...team2.players].sort((a,b) => b.runs - a.runs).slice(0, 5).map(p => ({ name: p.name.split(' ').pop(), runs: p.runs }))}>
                 <XAxis dataKey="name" stroke="#6b7280" fontSize={10} tickLine={false} axisLine={false} />
                 <Tooltip 
                   cursor={{fill: 'transparent'}}
                   contentStyle={{ backgroundColor: '#111827', border: '1px solid #374151', borderRadius: '8px', fontSize: '12px' }}
                   itemStyle={{ color: '#fff' }}
                 />
                 <Bar dataKey="runs" radius={[4, 4, 0, 0]}>
                   {[...Array(5)].map((_, index) => (
                     <Cell key={`cell-${index}`} fill={index === 0 ? '#fbbf24' : '#4b5563'} />
                   ))}
                 </Bar>
               </BarChart>
             </ResponsiveContainer>
          </div>
        </div>

        {/* --- FOOTER ACTIONS --- */}
        <div className="flex gap-4 pt-4 pb-8">
          <button className="flex-1 bg-gray-800 hover:bg-gray-750 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 border border-gray-700 transition-all">
             <Share2 size={18} /> Share Result
          </button>
          <button onClick={() => onSaveAndExit(matchState)} className="flex-1 bg-gradient-to-r from-tiger-gold to-tiger-orange text-black font-bold py-4 rounded-xl flex items-center justify-center gap-2 shadow-lg hover:shadow-yellow-500/20 hover:scale-[1.02] transition-all">
             <Home size={18} /> Return Home
          </button>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { MatchState, Player } from '../types';
import { aggregateStats, CareerStats } from '../utils/statsLogic';
import { ArrowLeft, Trophy, Calendar, ChevronRight, X } from 'lucide-react';

interface Props {
  matchHistory: MatchState[];
  onBack: () => void;
}

export const StatsDashboard: React.FC<Props> = ({ matchHistory, onBack }) => {
  const [activeTab, setActiveTab] = useState<'players' | 'matches'>('players');
  const [statType, setStatType] = useState<'batting' | 'bowling'>('batting');
  const [selectedMatch, setSelectedMatch] = useState<MatchState | null>(null);

  const HOME_TEAM_NAME = 'Taxila Tigers';

  // --- CAREER STATS LOGIC ---
  const playerStats = useMemo(() => aggregateStats(matchHistory, HOME_TEAM_NAME), [matchHistory]);

  const sortedCareerPlayers = useMemo(() => {
    return [...playerStats].sort((a, b) => {
      if (statType === 'batting') return b.runs - a.runs;
      return b.wickets - a.wickets;
    });
  }, [playerStats, statType]);

  // --- MATCH DETAIL LOGIC ---
  // Get the home team player objects from a specific match state
  const getMatchPlayers = (match: MatchState) => {
    if (match.battingTeam.name === HOME_TEAM_NAME) return match.battingTeam.players;
    if (match.bowlingTeam.name === HOME_TEAM_NAME) return match.bowlingTeam.players;
    return []; // Should not happen if home team played
  };

  const sortedMatchPlayers = useMemo(() => {
    if (!selectedMatch) return [];
    const players = getMatchPlayers(selectedMatch);
    // Return a shallow copy sorted by the current stat type
    return [...players].sort((a, b) => {
      if (statType === 'batting') return b.runs - a.runs;
      return b.wickets - a.wickets; 
    });
  }, [selectedMatch, statType]);


  // --- HELPERS ---
  const calcBatAvg = (runs: number, outs: number) => {
    if (outs === 0) return runs === 0 ? '-' : runs.toFixed(2);
    return (runs / outs).toFixed(2);
  };

  const calcBatSR = (runs: number, balls: number) => {
    if (balls === 0) return '-';
    return ((runs / balls) * 100).toFixed(2);
  };

  const calcBowlEcon = (runs: number, balls: number) => {
    if (balls === 0) return '-';
    return ((runs / balls) * 6).toFixed(2);
  };

  const calcBowlSR = (balls: number, wickets: number) => {
    if (wickets === 0) return '-';
    return (balls / wickets).toFixed(2);
  };

  const calcOvers = (balls: number) => `${Math.floor(balls/6)}.${balls%6}`;

  const getMatchResult = (match: MatchState) => {
    if (match.matchStatus !== 'COMPLETED') return { text: 'In Progress / Abandoned', color: 'text-gray-500' };
    if (!match.firstInningsScore) return { text: 'Result Unknown', color: 'text-gray-500' };

    const scoreFirst = match.firstInningsScore.runs;
    const scoreSecond = match.totalRuns;
    const teamBattingSecond = match.battingTeam.name;
    const teamBattingFirst = match.firstInningsScore.teamName;

    let winner = '';
    let margin = '';

    if (scoreSecond > scoreFirst) {
      winner = teamBattingSecond;
      margin = `${10 - match.wickets} wickets`;
    } else if (scoreFirst > scoreSecond) {
      winner = teamBattingFirst;
      margin = `${scoreFirst - scoreSecond} runs`;
    } else {
      return { text: 'Match Tied', color: 'text-gray-400' };
    }

    if (winner === HOME_TEAM_NAME) {
       return { text: `Won by ${margin}`, color: 'text-green-400' };
    } else {
       return { text: `Lost by ${margin}`, color: 'text-red-400' };
    }
  };

  // --- RENDERERS ---

  const renderBattingTable = (data: (CareerStats | Player)[], isCareer: boolean) => (
    <>
      <div className="grid grid-cols-7 bg-gray-750 p-3 border-b border-gray-700 text-[10px] sm:text-xs font-bold text-gray-400 uppercase tracking-wider text-center sticky top-0">
        <div className="col-span-2 text-left pl-2">Player</div>
        <div>{isCareer ? 'Mat' : ''}</div>
        <div>Runs</div>
        <div>Balls</div>
        <div>{isCareer ? 'HS' : 'SR'}</div>
        <div>{isCareer ? 'Avg' : ''}</div>
      </div>
      <div className="divide-y divide-gray-700/50">
        {data.filter(p => (isCareer ? (p as CareerStats).matches > 0 : (p as Player).balls > 0 || (p as Player).isOut)).length === 0 ? (
           <div className="p-8 text-center text-gray-500 text-xs">No batting records.</div>
        ) : (
          data.filter(p => (isCareer ? (p as CareerStats).matches > 0 : (p as Player).balls > 0 || (p as Player).isOut)).map((p, idx) => {
            // Type guard helpers
            const runs = p.runs;
            const balls = isCareer ? (p as CareerStats).ballsFaced : (p as Player).balls;
            const matches = isCareer ? (p as CareerStats).matches : 1;
            const hs = isCareer ? (p as CareerStats).highestScore : runs; // In match, HS is just runs
            const outs = isCareer ? (p as CareerStats).outs : ((p as Player).isOut ? 1 : 0);
            const sr = calcBatSR(runs, balls);
            const avg = calcBatAvg(runs, outs);

            return (
              <div key={p.name} className="grid grid-cols-7 p-3 items-center text-xs sm:text-sm text-center hover:bg-gray-700/30 transition-colors">
                <div className="col-span-2 text-left font-bold text-white pl-2 flex items-center gap-2 overflow-hidden">
                   <span className="truncate">{p.name}</span>
                   {!isCareer && !(p as Player).isOut && <span className="text-[10px] text-green-400">*</span>}
                </div>
                <div className="text-gray-500">{isCareer ? matches : ''}</div>
                <div className="font-bold text-tiger-gold">{runs}</div>
                <div className="text-gray-400">{balls}</div>
                <div className="text-gray-300 font-mono">{isCareer ? hs : sr}</div>
                <div className="text-gray-300 font-mono">{isCareer ? avg : ''}</div>
              </div>
            );
          })
        )}
      </div>
      {/* Footer for extra metric context if needed */}
      {!isCareer && <div className="p-2 text-[10px] text-gray-500 text-center italic">SR displayed in column 6</div>}
    </>
  );

  const renderBowlingTable = (data: (CareerStats | Player)[], isCareer: boolean) => (
    <>
      <div className="grid grid-cols-8 bg-gray-750 p-3 border-b border-gray-700 text-[10px] sm:text-xs font-bold text-gray-400 uppercase tracking-wider text-center sticky top-0">
        <div className="col-span-2 text-left pl-2">Player</div>
        <div>{isCareer ? 'Mat' : ''}</div>
        <div>Overs</div>
        <div>Wkts</div>
        <div>Runs</div>
        <div>Econ</div>
        <div>SR</div>
      </div>
      <div className="divide-y divide-gray-700/50">
        {data.filter(p => p.ballsBowled > 0).length === 0 ? (
           <div className="p-8 text-center text-gray-500 text-xs">No bowling records.</div>
        ) : (
          data.filter(p => p.ballsBowled > 0).map((p, idx) => {
            const wickets = p.wickets;
            const runs = p.runsConceded;
            const balls = p.ballsBowled;
            const matches = isCareer ? (p as CareerStats).matches : 1;
            const econ = calcBowlEcon(runs, balls);
            const sr = calcBowlSR(balls, wickets);
            const overs = calcOvers(balls);

            return (
              <div key={p.name} className="grid grid-cols-8 p-3 items-center text-xs sm:text-sm text-center hover:bg-gray-700/30 transition-colors">
                <div className="col-span-2 text-left font-bold text-white pl-2 flex items-center gap-2 overflow-hidden">
                   <span className="truncate">{p.name}</span>
                </div>
                <div className="text-gray-500">{isCareer ? matches : ''}</div>
                <div className="text-gray-400">{overs}</div>
                <div className="font-bold text-blue-400">{wickets}</div>
                <div className="text-gray-400">{runs}</div>
                <div className="text-gray-300 font-mono">{econ}</div>
                <div className="text-gray-300 font-mono">{sr}</div>
              </div>
            );
          })
        )}
      </div>
    </>
  );

  return (
    <div className="flex flex-col h-full bg-tiger-black text-white font-sans relative">

      {/* Header */}
      <div className="bg-tiger-card p-4 border-b border-gray-700 flex items-center gap-4 sticky top-0 z-10">
        <button onClick={onBack} className="p-2 rounded-full hover:bg-gray-700 transition-colors">
          <ArrowLeft size={20} className="text-tiger-gold" />
        </button>
        <h2 className="text-xl font-bold text-white truncate">
          {selectedMatch ? 'Match Details' : 'Taxila Tigers Hub'}
        </h2>
      </div>

      {selectedMatch ? (
        // --- MATCH DETAIL VIEW ---
        <div className="flex-1 flex flex-col overflow-hidden animate-in slide-in-from-right duration-300">
           {/* Match Info Header */}
           <div className="p-4 bg-gray-900 border-b border-gray-800">
              <div className="flex justify-between items-start mb-2">
                 <div>
                    <h3 className="font-bold text-white text-lg">{selectedMatch.battingTeam.name} vs {selectedMatch.bowlingTeam.name}</h3>
                    <p className="text-xs text-gray-500">{new Date(selectedMatch.ballHistory[0]?.timestamp || Date.now()).toLocaleDateString()}</p>
                 </div>
                 <button onClick={() => setSelectedMatch(null)} className="p-2 bg-gray-800 rounded-full text-gray-400 hover:text-white">
                    <X size={16} />
                 </button>
              </div>
              <div className="text-sm">
                 <span className={`${getMatchResult(selectedMatch).color} font-bold uppercase`}>{getMatchResult(selectedMatch).text}</span>
              </div>
           </div>

           {/* Stat Toggle */}
           <div className="p-4 bg-gray-900/50">
             <div className="flex bg-gray-800 p-1 rounded-xl border border-gray-700 w-full max-w-sm mx-auto">
                <button 
                  onClick={() => setStatType('batting')}
                  className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'batting' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                >
                  Batting
                </button>
                <button 
                  onClick={() => setStatType('bowling')}
                  className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'bowling' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                >
                  Bowling
                </button>
             </div>
           </div>

           {/* Table */}
           <div className="flex-1 overflow-y-auto p-4 pt-0">
              <div className="bg-gray-800 rounded-xl border border-gray-700 shadow-xl overflow-hidden">
                {statType === 'batting' 
                  ? renderBattingTable(sortedMatchPlayers, false) 
                  : renderBowlingTable(sortedMatchPlayers, false)
                }
              </div>
              <div className="text-center text-[10px] text-gray-500 mt-4">
                 Showing stats for {HOME_TEAM_NAME} players in this match.
              </div>
           </div>
        </div>
      ) : (
        // --- MAIN DASHBOARD VIEW ---
        <>
          {/* Tabs */}
          <div className="flex bg-gray-900 border-b border-gray-800">
            <button 
              onClick={() => setActiveTab('players')}
              className={`flex-1 py-4 font-bold text-xs sm:text-sm uppercase tracking-wider border-b-2 transition-all ${activeTab === 'players' ? 'border-tiger-gold text-tiger-gold bg-gray-800' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
            >
              Career Stats
            </button>
            <button 
              onClick={() => setActiveTab('matches')}
              className={`flex-1 py-4 font-bold text-xs sm:text-sm uppercase tracking-wider border-b-2 transition-all ${activeTab === 'matches' ? 'border-tiger-gold text-tiger-gold bg-gray-800' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
            >
              Match History
            </button>
          </div>

          <div className="flex-1 overflow-y-auto bg-gray-900/50">
            {activeTab === 'players' ? (
              <div className="p-4 space-y-4">
                {/* Stat Type Toggle */}
                <div className="flex bg-gray-800 p-1 rounded-xl border border-gray-700 w-full max-w-sm mx-auto">
                  <button 
                    onClick={() => setStatType('batting')}
                    className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'batting' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                  >
                    Batting
                  </button>
                  <button 
                    onClick={() => setStatType('bowling')}
                    className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'bowling' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                  >
                    Bowling
                  </button>
                </div>

                {/* Stats Table */}
                <div className="bg-gray-800 rounded-xl border border-gray-700 shadow-xl overflow-hidden">
                    {statType === 'batting' 
                      ? renderBattingTable(sortedCareerPlayers, true)
                      : renderBowlingTable(sortedCareerPlayers, true)
                    }
                </div>

                <div className="text-[10px] text-center text-gray-500 mt-4 italic">
                    * Mat: Matches | HS: Highest Score | Avg: Average | Econ: Economy Rate
                </div>
              </div>
            ) : (
              <div className="p-4 space-y-4">
                {matchHistory.length === 0 ? (
                    <div className="text-center text-gray-500 py-10">No matches played yet.</div>
                ) : (
                  matchHistory.slice().reverse().map((match, idx) => {
                    const result = getMatchResult(match);
                    const date = new Date(match.ballHistory[0]?.timestamp || Date.now()).toLocaleDateString();

                    return (
                      <button 
                        key={idx} 
                        onClick={() => setSelectedMatch(match)}
                        className="w-full text-left bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-lg relative overflow-hidden group hover:border-tiger-gold transition-all hover:scale-[1.01]"
                      >
                        <div className="absolute top-0 right-0 w-20 h-20 bg-gradient-to-bl from-white/5 to-transparent rounded-bl-full pointer-events-none" />

                        <div className="flex justify-between items-center mb-2">
                          <span className="text-[10px] font-bold text-gray-500 uppercase flex items-center gap-1">
                            <Calendar size={10} /> {date}
                          </span>
                          <span className={`text-[10px] px-2 py-0.5 rounded border font-bold uppercase ${result.color} bg-black/20 border-current`}>
                            {result.text}
                          </span>
                        </div>
                        <div className="flex flex-col gap-2 mt-2">
                            {match.firstInningsScore && (
                              <div className="flex justify-between items-center text-xs text-gray-400">
                                  <span>{match.firstInningsScore.teamName}</span>
                                  <span className="font-mono">{match.firstInningsScore.runs}/{match.firstInningsScore.wickets} <span className="text-[10px]">({match.firstInningsScore.overs})</span></span>
                              </div>
                            )}
                            <div className="flex justify-between items-center text-xs text-white font-semibold">
                                <span>{match.battingTeam.name}</span>
                                <span className="font-mono">{match.totalRuns}/{match.wickets} <span className="text-[10px] text-gray-400">({match.currentOver}.{match.currentBall})</span></span>
                            </div>
                        </div>

                        <div className="mt-3 flex items-center justify-end text-tiger-gold text-[10px] font-bold uppercase tracking-wider gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                           View Stats <ChevronRight size={12} />
                        </div>
                      </button>
                    );
                  })
                )}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MatchState, ExtraType, WicketType, Player, WicketDetails } from '../types';
import { processBall, getPlayer, calculateEconomy } from '../utils/cricketLogic';
import { generateCommentary, askRuleQuestion } from '../services/geminiService';
import { Mic, Info, RotateCcw, ChevronDown, CheckCircle2, User, Trophy, Handshake } from 'lucide-react';

interface Props {
  matchState: MatchState;
  setMatchState: (state: MatchState) => void;
  onUndo: () => void;
  canUndo: boolean;
  onFinish: () => void;
}

export const ScoringDashboard: React.FC<Props> = ({ matchState, setMatchState, onUndo, canUndo, onFinish }) => {
  // Modal States
  const [wicketModalOpen, setWicketModalOpen] = useState(false);
  const [bowlerSelectOpen, setBowlerSelectOpen] = useState(false);

  // Wicket Flow States
  const [selectedWicketType, setSelectedWicketType] = useState<WicketType | null>(null);
  const [selectedFielder, setSelectedFielder] = useState<string>('');
  const [whoIsOut, setWhoIsOut] = useState<'striker' | 'nonStriker'>('striker');

  const [extraType, setExtraType] = useState<ExtraType>(ExtraType.NONE);
  const [commentary, setCommentary] = useState<string>("Waiting for next ball...");
  const [aiLoading, setAiLoading] = useState(false);

  const timelineRef = useRef<HTMLDivElement>(null);

  const striker = getPlayer(matchState.battingTeam.players, matchState.strikerId);
  const nonStriker = getPlayer(matchState.battingTeam.players, matchState.nonStrikerId);
  const bowler = getPlayer(matchState.bowlingTeam.players, matchState.currentBowlerId);

  // Auto-prompt for bowler change
  useEffect(() => {
    if (matchState.currentBall === 0 && matchState.currentOver > 0 && matchState.ballHistory.length > 0) {
      setBowlerSelectOpen(true);
    }
  }, [matchState.currentOver]);

  // Handle innings break or match end
  useEffect(() => {
    if (matchState.matchStatus === 'COMPLETED' || matchState.matchStatus === 'INNINGS_BREAK') {
      onFinish();
    }
  }, [matchState.matchStatus]);

  // --- PARTNERSHIP LOGIC ---
  const currentPartnership = useMemo(() => {
    const history = matchState.ballHistory;
    let runs = 0;
    let balls = 0;

    // Iterate backwards until the last wicket or start of innings
    for (let i = history.length - 1; i >= 0; i--) {
      const ball = history[i];
      // Note: If we are in 2nd innings, we must stop if we hit the boundary of 1st innings
      // The history contains both innings mixed if we don't clear it, 
      // but App.tsx clears history on innings break for 2nd innings state? 
      // Actually App.tsx keeps separate matchState, but let's be safe:
      if (ball.inningsNumber !== matchState.inningsNumber) break; 

      if (ball.isWicket) break;

      runs += ball.runs + ball.extraRuns;
      if (ball.isLegalBall) balls++;
    }
    return { runs, balls };
  }, [matchState.ballHistory, matchState.inningsNumber]);


  const resetWicketState = () => {
    setWicketModalOpen(false);
    setSelectedWicketType(null);
    setSelectedFielder('');
    setWhoIsOut('striker');
  };

  const handleScore = (runs: number) => {
    processAndSetState(runs, false, undefined);
  };

  const handleWicketConfirm = () => {
    if (!selectedWicketType) return;

    const wicketDetails: WicketDetails = {
      type: selectedWicketType,
      fielderName: selectedFielder || undefined,
      isStrikerOut: whoIsOut === 'striker'
    };

    processAndSetState(0, true, wicketDetails);
    resetWicketState();
  };

  const processAndSetState = (runs: number, isWicket: boolean, wicketDetails: WicketDetails | undefined) => {
    let nextBatsmanId = undefined;

    if (isWicket) {
      // Find next batsman who is not out and not currently batting
      const nextBat = matchState.battingTeam.players.find(p => !p.isOut && p.id !== matchState.strikerId && p.id !== matchState.nonStrikerId);
      if (nextBat) nextBatsmanId = nextBat.id;
      // If no next batsman, processBall will handle All Out logic (wickets=10)
    }

    const newState = processBall(matchState, runs, extraType, isWicket, wicketDetails, nextBatsmanId);
    setMatchState(newState);

    setExtraType(ExtraType.NONE);

    setAiLoading(true);
    const lastEvent = newState.ballHistory[newState.ballHistory.length - 1];
    generateCommentary(lastEvent, newState).then(text => {
      setCommentary(text);
      setAiLoading(false);
    });
  };

  const handleChangeBowler = (bowlerId: string) => {
    const newState = { ...matchState, currentBowlerId: bowlerId };
    setMatchState(newState);
    setBowlerSelectOpen(false);
  };

  const getLabel = (runVal: number) => {
    if (extraType === ExtraType.WIDE) return `WD + ${runVal}`;
    if (extraType === ExtraType.NO_BALL) return `NB + ${runVal}`;
    if (extraType === ExtraType.BYE) return `${runVal} B`;
    if (extraType === ExtraType.LEG_BYE) return `${runVal} LB`;
    return runVal.toString();
  };

  const needsFielder = selectedWicketType === WicketType.CAUGHT || selectedWicketType === WicketType.RUN_OUT || selectedWicketType === WicketType.STUMPED;

  return (
    <div className="flex flex-col h-full bg-tiger-black font-sans text-white relative">

      {/* PROFESSIONAL SCOREBOARD HEADER */}
      <div className="bg-gradient-to-b from-gray-900 to-gray-800 shadow-xl border-b border-gray-700">

        {/* Top Bar: Match Overview */}
        <div className="px-4 py-2 flex justify-between items-center bg-black/40 text-xs font-semibold tracking-wider text-gray-400 uppercase">
          <div>{matchState.battingTeam.name} vs {matchState.bowlingTeam.name}</div>
          <div className="flex gap-4">
             <span className="text-tiger-gold">{matchState.tossWinner} chose to {matchState.tossDecision}</span>
             <span className="text-red-500 font-bold">• LIVE</span>
          </div>
        </div>

        {/* Main Score Area */}
        <div className="px-4 py-4 flex items-end justify-between">
          <div className="flex flex-col">
            <div className="flex items-baseline gap-3">
              <span className="text-5xl font-black text-white tabular-nums tracking-tight">
                {matchState.totalRuns}/{matchState.wickets}
              </span>
              <span className="text-xl text-tiger-gold font-mono">
                {matchState.currentOver}.{matchState.currentBall} <span className="text-sm text-gray-500">ov</span>
              </span>
            </div>
            <div className="text-xs font-medium text-gray-400 mt-1 flex flex-col gap-1">
              <div className="flex gap-2">
                 <span>CRR: {((matchState.totalRuns / (matchState.currentOver * 6 + matchState.currentBall || 1)) * 6).toFixed(2)}</span>
                 <span>•</span>
                 <span>Extras: {matchState.extras.wides + matchState.extras.noBalls + matchState.extras.byes + matchState.extras.legByes}</span>
              </div>
              {matchState.target && (
                 <div className="text-tiger-gold font-bold">
                    Need {matchState.target - matchState.totalRuns} runs in { (matchState.totalOvers * 6) - (matchState.currentOver * 6 + matchState.currentBall) } balls
                 </div>
              )}
            </div>
          </div>

          <div className="flex flex-col items-end gap-2">
            {/* PARTNERSHIP WIDGET */}
            <div className="bg-gray-800/80 rounded-lg p-2 border border-gray-700/50 mb-1 flex items-center gap-3">
               <div className="flex items-center gap-1.5 text-[10px] text-gray-400 font-bold uppercase tracking-wider">
                  <Handshake size={12} className="text-tiger-gold" /> P'ship
               </div>
               <div className="text-sm font-bold text-white tabular-nums">
                  {currentPartnership.runs} <span className="text-[10px] text-gray-500 font-normal">({currentPartnership.balls})</span>
               </div>
            </div>

            <div className="flex gap-2">
              <button 
                  onClick={onUndo} 
                  disabled={!canUndo}
                  className={`px-3 py-1.5 rounded text-xs font-bold uppercase tracking-wider flex items-center gap-1 transition-colors ${canUndo ? 'bg-gray-700 text-white hover:bg-gray-600' : 'bg-gray-800 text-gray-600'}`}
              >
                <RotateCcw size={12} /> Undo
              </button>
              <button 
                onClick={() => setBowlerSelectOpen(true)}
                className="px-3 py-1.5 rounded bg-tiger-gold/10 text-tiger-gold border border-tiger-gold/30 text-xs font-bold uppercase tracking-wider hover:bg-tiger-gold/20 transition-colors"
              >
                Change Bowler
              </button>
            </div>
          </div>
        </div>

        {/* Broadcast Strip: Batter & Bowler Stats */}
        <div className="grid grid-cols-12 border-t border-gray-700/50 bg-gray-800/50 backdrop-blur-sm">
          {/* Striker */}
          <div className="col-span-5 p-3 border-r border-gray-700/50 flex justify-between items-center relative overflow-hidden group">
            <div className="absolute left-0 top-0 bottom-0 w-1 bg-tiger-gold"></div>
            <div>
               <div className="text-sm font-bold text-white flex items-center gap-1">
                 {striker?.name} <Trophy size={10} className="text-tiger-gold fill-current" />
               </div>
               <div className="text-[10px] text-gray-400 uppercase tracking-widest mt-0.5">Striker</div>
            </div>
            <div className="text-right">
              <div className="text-xl font-bold text-tiger-gold tabular-nums">{striker?.runs}</div>
              <div className="text-[10px] text-gray-500">{striker?.balls} balls</div>
            </div>
          </div>

          {/* Non-Striker */}
          <div className="col-span-3 p-3 border-r border-gray-700/50 flex flex-col justify-center opacity-70">
            <div className="text-xs font-semibold text-gray-300 truncate">{nonStriker?.name}</div>
            <div className="text-xs text-gray-500">{nonStriker?.runs} ({nonStriker?.balls})</div>
          </div>

          {/* Bowler */}
          <div className="col-span-4 p-3 flex justify-between items-center bg-gray-900/40">
            <div className="truncate pr-2">
               <div className="text-sm font-bold text-white truncate">{bowler?.name}</div>
               <div className="text-[10px] text-gray-400 uppercase tracking-widest mt-0.5">Bowler</div>
            </div>
            <div className="text-right whitespace-nowrap">
              <div className="text-sm font-bold text-blue-400 tabular-nums">{bowler?.wickets}-{bowler?.runsConceded}</div>
              <div className="text-[10px] text-gray-500">{Math.floor((bowler?.ballsBowled || 0)/6)}.{ (bowler?.ballsBowled || 0)%6 } ov</div>
            </div>
          </div>
        </div>
      </div>

      {/* Action Timeline */}
      <div className="bg-black/60 backdrop-blur border-b border-gray-800 p-2 overflow-x-auto whitespace-nowrap no-scrollbar flex items-center" ref={timelineRef}>
        <span className="text-[10px] font-bold text-gray-500 uppercase mr-3 sticky left-0 bg-transparent pl-2">Last 12:</span>
        {matchState.ballHistory.slice(-12).reverse().map((ball, idx) => (
          <div key={idx} className={`flex-shrink-0 w-7 h-7 flex items-center justify-center rounded-full text-[10px] font-bold mr-2 border border-opacity-30 
            ${ball.isWicket ? 'bg-red-500/20 border-red-500 text-red-400' : 
              ball.runs >= 4 ? 'bg-tiger-gold text-black border-tiger-gold' : 
              'bg-gray-800 border-gray-600 text-gray-300'}`}>
            {ball.isWicket ? 'W' : ball.extraType !== ExtraType.NONE ? (ball.runs + ball.extraRuns) + (ball.extraType[0]) : ball.runs}
          </div>
        ))}
      </div>

      {/* Commentary Strip */}
      <div className="px-4 py-3 bg-tiger-gold/5 border-b border-tiger-gold/10 flex items-start gap-3">
        <Mic size={14} className={`text-tiger-gold mt-1 flex-shrink-0 ${aiLoading ? 'animate-pulse' : ''}`} />
        <p className="text-xs text-gray-300 leading-relaxed font-medium">
          {commentary}
        </p>
      </div>

      {/* CONTROLS AREA */}
      <div className="flex-1 p-4 pb-8 flex flex-col justify-end gap-3 bg-gradient-to-t from-black to-gray-900">

        {/* Extras Row */}
        <div className="grid grid-cols-4 gap-2">
           {[ExtraType.WIDE, ExtraType.NO_BALL, ExtraType.BYE, ExtraType.LEG_BYE].map((type) => (
             <button
                key={type}
                onClick={() => setExtraType(extraType === type ? ExtraType.NONE : type)}
                className={`py-3 text-[10px] font-bold uppercase rounded-lg transition-all border ${
                  extraType === type 
                  ? 'bg-tiger-orange border-tiger-gold text-white shadow-[0_0_10px_rgba(251,191,36,0.5)]' 
                  : 'bg-gray-800 border-gray-700 text-gray-400 hover:bg-gray-700'
                }`}
             >
               {type === ExtraType.NO_BALL ? 'No Ball' : type}
             </button>
           ))}
        </div>

        {/* Main Runs Grid */}
        <div className="grid grid-cols-4 gap-3">
          <button onClick={() => handleScore(0)} className="h-14 rounded-lg bg-gray-800 border-b-4 border-gray-950 hover:bg-gray-700 active:border-b-0 active:translate-y-1 transition-all text-xl font-bold text-white shadow-lg">{getLabel(0)}</button>
          <button onClick={() => handleScore(1)} className="h-14 rounded-lg bg-gray-800 border-b-4 border-gray-950 hover:bg-gray-700 active:border-b-0 active:translate-y-1 transition-all text-xl font-bold text-white shadow-lg">{getLabel(1)}</button>
          <button onClick={() => handleScore(2)} className="h-14 rounded-lg bg-gray-800 border-b-4 border-gray-950 hover:bg-gray-700 active:border-b-0 active:translate-y-1 transition-all text-xl font-bold text-white shadow-lg">{getLabel(2)}</button>
          <button onClick={() => handleScore(3)} className="h-14 rounded-lg bg-gray-800 border-b-4 border-gray-950 hover:bg-gray-700 active:border-b-0 active:translate-y-1 transition-all text-xl font-bold text-white shadow-lg">{getLabel(3)}</button>

          <button onClick={() => handleScore(4)} className="h-14 rounded-lg bg-tiger-gold border-b-4 border-tiger-orange hover:bg-yellow-400 active:border-b-0 active:translate-y-1 transition-all text-2xl font-black text-black shadow-lg">4</button>
          <button onClick={() => handleScore(6)} className="h-14 rounded-lg bg-tiger-gold border-b-4 border-tiger-orange hover:bg-yellow-400 active:border-b-0 active:translate-y-1 transition-all text-2xl font-black text-black shadow-lg">6</button>

