};

import React, { useEffect, useState, useMemo } from 'react';
import { MatchState, Player } from '../types';
import { generateMatchSummary } from '../services/geminiService';
import { Share2, Save, Trophy, Medal, Crown, Home, TrendingUp } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, LineChart, Line, Legend } from 'recharts';

interface Props {
  matchState: MatchState;
  onSaveAndExit: (match: MatchState) => void;
}

export const MatchSummary: React.FC<Props> = ({ matchState, onSaveAndExit }) => {
  const [report, setReport] = useState("Generating AI Match Report...");

  useEffect(() => {
    generateMatchSummary(matchState).then(setReport);
  }, []);

  // --- RESULT LOGIC ---
  const result = useMemo(() => {
    const { inningsNumber, totalRuns, wickets, target, firstInningsScore, battingTeam, bowlingTeam } = matchState;

    if (inningsNumber === 1) {
       return {
         winner: 'Innings Break',
         margin: 'First Innings Completed',
         winnerTeam: battingTeam.name,
         isTie: false,
         color: 'text-gray-400'
       };
    }

    const teamBattingSecond = battingTeam.name;
    const teamBattingFirst = firstInningsScore?.teamName || bowlingTeam.name;
    const targetScore = target || 0;

    // Logic: 
    // Batting Team (Chaser) Wins if totalRuns >= target
    // Bowling Team (Defender) Wins if totalRuns < target - 1
    // Tie if totalRuns === target - 1

    if (totalRuns >= targetScore) {
       const wicketsLeft = 10 - wickets;
       return {
         winner: teamBattingSecond,
         margin: `won by ${wicketsLeft} wicket${wicketsLeft !== 1 ? 's' : ''}`,
         winnerTeam: teamBattingSecond,
         isTie: false,
         color: 'text-tiger-gold'
       };
    } else if (totalRuns < targetScore - 1) {
       const runDiff = (targetScore - 1) - totalRuns;
       return {
         winner: teamBattingFirst,
         margin: `won by ${runDiff} run${runDiff !== 1 ? 's' : ''}`,
         winnerTeam: teamBattingFirst,
         isTie: false,
         color: 'text-tiger-gold'
       };
    } else {
       return {
         winner: 'Match Tied',
         margin: 'Scores Level',
         winnerTeam: 'Draw',
         isTie: true,
         color: 'text-gray-200'
       };
    }
  }, [matchState]);

  // --- MVP LOGIC ---
  const mvp = useMemo(() => {
    // Combine players from both teams. 
    // Note: In 2nd innings, battingTeam is Team B, bowlingTeam is Team A. Both have full match stats.
    const allPlayers = [
        ...matchState.battingTeam.players.map(p => ({...p, teamName: matchState.battingTeam.name})), 
        ...matchState.bowlingTeam.players.map(p => ({...p, teamName: matchState.bowlingTeam.name}))
    ];

    // Score = Runs + (Wickets * 20)
    const scored = allPlayers.map(p => ({
        ...p,
        points: (p.runs * 1) + (p.wickets * 20) + (p.isOut ? 0 : 5) + (p.runs >= 50 ? 10 : 0) + (p.wickets >= 3 ? 10 : 0)
    }));

    // Sort desc
    return scored.sort((a, b) => b.points - a.points)[0];
  }, [matchState]);

  // --- DATA PREP ---
  const team1 = matchState.bowlingTeam; // Batted 1st
  const team2 = matchState.battingTeam; // Batted 2nd

  // If innings 1, setup is simpler
  const isInnings1 = matchState.inningsNumber === 1;

  // --- WORM CHART DATA ---
  const wormData = useMemo(() => {
    // We need to reconstruct the cumulative score per over for both innings.
    // This is tricky because we only have current matchState history (usually just the active innings or combined).
    // The current 'ballHistory' contains events. We need to filter by inningsNumber.

    // Note: App.tsx resets ballHistory for 2nd innings? 
    // Actually, looking at App.tsx, `handleStartSecondInnings` sets `totalRuns: 0` but doesn't explicitly clear ballHistory?
    // Wait, `newState` spreads `matchState` but if ballHistory isn't reset, it keeps old balls.
    // Assuming `ballHistory` contains ALL balls with `inningsNumber`.

    const getDataForInnings = (inningsNum: number) => {
        const events = matchState.ballHistory.filter(b => b.inningsNumber === inningsNum);
        if (events.length === 0 && inningsNum === 1 && matchState.firstInningsScore) {
           // If history was cleared (likely in App.tsx implementation logic which might have cleared it in a real app, 
           // but here `handleStartSecondInnings` in App.tsx creates a NEW object but doesn't explicitly empty ballHistory array in the snippet I saw?
           // Wait, App.tsx: `ballHistory: [],` IS NOT in the `handleStartSecondInnings` spread override.
           // However, if we assume `matchState` only holds CURRENT innings history in a typical react state update unless persisted...
           // Let's assume ballHistory has everything if we didn't clear it.
           // If it's missing, we can't plot innings 1.
           return [];
        }

        let cumulativeRun = 0;
        let currentOver = 0;
        const dataPoints: {over: number, runs: number}[] = [{over: 0, runs: 0}];

        events.forEach(ball => {
            cumulativeRun += ball.runs + ball.extraRuns;
            // Check if over changed. A ball doesn't explicitly store "over number" but we can derive or simplify.
            // Simplified: Push data point every 6 legal balls or just aggregate.
            // Better: Iterate and just push a point at the end of the array.
            // Let's just create a point for every event for smoothness? No, charts get busy.
            // Let's group by over.
        });

        // Re-loop to group by overs properly
        cumulativeRun = 0;
        let legalBalls = 0;

        events.forEach(ball => {
           cumulativeRun += ball.runs + ball.extraRuns;
           if (ball.isLegalBall) {
             legalBalls++;
             if (legalBalls % 6 === 0) {
                dataPoints.push({ over: legalBalls / 6, runs: cumulativeRun });
             }
           }
        });
        // Add final state
        if (legalBalls % 6 !== 0) {
           dataPoints.push({ over: parseFloat((legalBalls/6).toFixed(1)), runs: cumulativeRun });
        }
        return dataPoints;
    };

    const inn1Data = getDataForInnings(1);
    const inn2Data = getDataForInnings(2);

    // Merge for Recharts
    // Find max overs
    const maxOvers = Math.max(
        inn1Data.length > 0 ? inn1Data[inn1Data.length-1].over : 0,
        inn2Data.length > 0 ? inn2Data[inn2Data.length-1].over : 0
    );

    const merged = [];
    // We need integer overs 1..N roughly
    for (let i = 0; i <= Math.ceil(maxOvers); i++) {
        const d1 = inn1Data.find(d => Math.floor(d.over) === i || (i > 0 && Math.floor(d.over) === i-1 && d.over > i-1)); // Rough matching
        // Actually, let's just use the index if array is sequential overs.
        const point1 = inn1Data.find(p => p.over === i);
        const point2 = inn2Data.find(p => p.over === i);

        if (point1 || point2 || i === 0) {
             merged.push({
               name: i.toString(),
               [matchState.firstInningsScore?.teamName || 'Team 1']: point1?.runs,
               [matchState.battingTeam.name]: point2?.runs
             });
        }
    }
    return merged;

  }, [matchState]);


  return (
    <div className="flex flex-col h-full bg-tiger-black font-sans text-white overflow-y-auto">

      {/* --- HERO SECTION --- */}
      <div className="relative overflow-hidden bg-gradient-to-b from-gray-800 to-gray-900 border-b border-gray-800 p-8 text-center">
         {/* Background Decoration */}
         <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-20 pointer-events-none">
            <div className="absolute top-[-50%] left-[-50%] w-[200%] h-[200%] bg-[radial-gradient(circle,rgba(251,191,36,0.2)_0%,transparent_70%)] animate-pulse" />
         </div>

         <div className="relative z-10">
            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Match Result</h2>

            {result.isTie ? (
               <div className="text-5xl font-black text-white uppercase tracking-tighter mb-2">MATCH TIED</div>
            ) : (
               <div className="flex flex-col items-center gap-2">
                 <Trophy size={48} className="text-tiger-gold mb-2 drop-shadow-[0_0_15px_rgba(251,191,36,0.6)]" />
                 <h1 className="text-4xl sm:text-5xl font-black text-white uppercase italic tracking-tight leading-none">
                    {result.winner}
                 </h1>
                 <div className={`text-xl font-bold ${result.color} uppercase tracking-widest bg-black/30 px-4 py-1 rounded-full mt-2 border border-white/10`}>
                    {result.margin}
                 </div>
               </div>
            )}
         </div>
      </div>

      <div className="p-4 sm:p-6 space-y-6 max-w-4xl mx-auto w-full">

        {/* --- SCORE SUMMARY CARDS --- */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
           {/* Team 1 (Batted First) */}
           <div className={`p-4 rounded-xl border ${result.winnerTeam === team1.name ? 'bg-gradient-to-br from-gray-800 to-gray-900 border-tiger-gold shadow-[0_0_15px_rgba(251,191,36,0.1)]' : 'bg-gray-800 border-gray-700 opacity-80'}`}>
              <div className="flex justify-between items-start mb-2">
                 <span className="font-bold text-lg text-gray-200">{matchState.firstInningsScore?.teamName || team1.name}</span>
                 {result.winnerTeam === team1.name && <Crown size={16} className="text-tiger-gold" />}
              </div>
              <div className="flex items-baseline gap-2">
                 <span className="text-3xl font-black text-white">
                   {matchState.firstInningsScore ? matchState.firstInningsScore.runs : matchState.totalRuns}
                   <span className="text-xl text-gray-400">/{matchState.firstInningsScore ? matchState.firstInningsScore.wickets : matchState.wickets}</span>
                 </span>
                 <span className="text-xs text-gray-500 font-mono">
                   ({matchState.firstInningsScore ? matchState.firstInningsScore.overs : `${matchState.currentOver}.${matchState.currentBall}`})
                 </span>
              </div>
              <div className="text-xs text-gray-500 mt-2 uppercase tracking-wide font-bold">1st Innings</div>
           </div>

           {/* Team 2 (Batted Second) */}
           {!isInnings1 && (
             <div className={`p-4 rounded-xl border ${result.winnerTeam === team2.name ? 'bg-gradient-to-br from-gray-800 to-gray-900 border-tiger-gold shadow-[0_0_15px_rgba(251,191,36,0.1)]' : 'bg-gray-800 border-gray-700 opacity-80'}`}>
                <div className="flex justify-between items-start mb-2">
                   <span className="font-bold text-lg text-gray-200">{team2.name}</span>
                   {result.winnerTeam === team2.name && <Crown size={16} className="text-tiger-gold" />}
                </div>
                <div className="flex items-baseline gap-2">
                   <span className="text-3xl font-black text-white">
                     {matchState.totalRuns}
                     <span className="text-xl text-gray-400">/{matchState.wickets}</span>
                   </span>
                   <span className="text-xs text-gray-500 font-mono">
                     ({matchState.currentOver}.{matchState.currentBall})
                   </span>
                </div>
                <div className="text-xs text-gray-500 mt-2 uppercase tracking-wide font-bold">2nd Innings</div>
             </div>
           )}
        </div>

        {/* --- MAN OF THE MATCH --- */}
        {mvp && (
          <div className="bg-gradient-to-r from-gray-800 via-gray-900 to-gray-800 rounded-xl p-1 border border-tiger-gold/30 shadow-lg relative overflow-hidden group">
             <div className="absolute inset-0 bg-tiger-gold/5 opacity-0 group-hover:opacity-100 transition-opacity" />
             <div className="p-4 flex items-center gap-4 relative z-10">
                <div className="w-16 h-16 rounded-full bg-tiger-gold flex items-center justify-center text-black shadow-lg shadow-yellow-500/20">
                   <Medal size={32} />
                </div>
                <div className="flex-1">
                   <div className="text-xs font-bold text-tiger-gold uppercase tracking-widest mb-1">Player of the Match</div>
                   <div className="text-xl font-black text-white">{mvp.name}</div>
                   <div className="text-xs text-gray-400 font-medium">{mvp.teamName}</div>
                </div>
                <div className="text-right">
                   <div className="text-sm font-bold text-white">{mvp.runs} Runs</div>
                   {mvp.wickets > 0 && <div className="text-sm font-bold text-white">{mvp.wickets} Wickets</div>}
                   <div className="text-[10px] text-gray-500 mt-1">{mvp.points} Pts</div>
                </div>
             </div>
          </div>
        )}

        {/* --- AI REPORT --- */}
        <div className="bg-gray-800 rounded-xl p-6 border border-gray-700 shadow-md">
          <h3 className="text-xs font-bold text-tiger-gold uppercase tracking-widest mb-3 flex items-center gap-2">
            <span className="w-2 h-2 bg-tiger-gold rounded-full animate-pulse" /> AI Match Analysis
          </h3>
          <p className="text-gray-300 text-sm leading-relaxed pl-4 border-l-2 border-gray-600 italic">
            "{report}"
          </p>
        </div>

        {/* --- WORM GRAPH --- */}
        {!isInnings1 && (
            <div className="bg-gray-800 rounded-xl p-6 border border-gray-700">
                <h3 className="text-xs font-bold text-gray-400 uppercase mb-4 flex items-center gap-2">
                    <TrendingUp size={14} /> Run Rate Comparison (The Worm)
                </h3>
                <div className="h-64 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={wormData}>
                            <XAxis dataKey="name" stroke="#6b7280" fontSize={10} tickLine={false} axisLine={false} label={{ value: 'Overs', position: 'insideBottom', offset: -5, fill: '#6b7280', fontSize: 10 }} />
                            <YAxis stroke="#6b7280" fontSize={10} tickLine={false} axisLine={false} />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#111827', border: '1px solid #374151', borderRadius: '8px', fontSize: '12px' }}
                            />
                            <Legend wrapperStyle={{ fontSize: '12px', paddingTop: '10px' }} />
                            <Line type="monotone" dataKey={matchState.firstInningsScore?.teamName || 'Team 1'} stroke="#9ca3af" strokeWidth={2} dot={false} />
                            <Line type="monotone" dataKey={matchState.battingTeam.name} stroke="#fbbf24" strokeWidth={2} dot={false} />
                        </LineChart>
                    </ResponsiveContainer>
                </div>
            </div>
        )}

        {/* --- TOP PERFORMERS (Chart) --- */}
        <div className="bg-gray-800 rounded-xl p-6 border border-gray-700">
          <h3 className="text-xs font-bold text-gray-400 uppercase mb-4">Top Run Scorers</h3>
          <div className="h-48 w-full">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={[...team1.players, ...team2.players].sort((a,b) => b.runs - a.runs).slice(0, 5).map(p => ({ name: p.name.split(' ').pop(), runs: p.runs }))}>
                 <XAxis dataKey="name" stroke="#6b7280" fontSize={10} tickLine={false} axisLine={false} />
                 <Tooltip 
                   cursor={{fill: 'transparent'}}
                   contentStyle={{ backgroundColor: '#111827', border: '1px solid #374151', borderRadius: '8px', fontSize: '12px' }}
                   itemStyle={{ color: '#fff' }}
                 />
                 <Bar dataKey="runs" radius={[4, 4, 0, 0]}>
                   {[...Array(5)].map((_, index) => (
                     <Cell key={`cell-${index}`} fill={index === 0 ? '#fbbf24' : '#4b5563'} />
                   ))}
                 </Bar>
               </BarChart>
             </ResponsiveContainer>
          </div>
        </div>

        {/* --- FOOTER ACTIONS --- */}
        <div className="flex gap-4 pt-4 pb-8">
          <button className="flex-1 bg-gray-800 hover:bg-gray-750 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 border border-gray-700 transition-all">
             <Share2 size={18} /> Share Result
          </button>
          <button onClick={() => onSaveAndExit(matchState)} className="flex-1 bg-gradient-to-r from-tiger-gold to-tiger-orange text-black font-bold py-4 rounded-xl flex items-center justify-center gap-2 shadow-lg hover:shadow-yellow-500/20 hover:scale-[1.02] transition-all">
             <Home size={18} /> Return Home
          </button>
        </div>

      </div>
    </div>
  );
};

import { SavedTeam, MatchState } from '../types';

const TEAMS_KEY = 'cricket_app_teams';
const MATCHES_KEY = 'cricket_app_matches';

export const getSavedTeams = (): SavedTeam[] => {
  try {
    const data = localStorage.getItem(TEAMS_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error("Failed to load teams", error);
    return [];
  }
};

export const saveTeam = (team: SavedTeam) => {
  const teams = getSavedTeams();
  // Check if update or new
  const index = teams.findIndex(t => t.id === team.id);
  if (index >= 0) {
    teams[index] = team;
  } else {
    teams.push(team);
  }
  localStorage.setItem(TEAMS_KEY, JSON.stringify(teams));
};

export const deleteTeam = (teamId: string) => {
  const teams = getSavedTeams().filter(t => t.id !== teamId);
  localStorage.setItem(TEAMS_KEY, JSON.stringify(teams));
};

// --- MATCH HISTORY STORAGE ---

export const getSavedMatches = (): MatchState[] => {
  try {
    const data = localStorage.getItem(MATCHES_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error("Failed to load match history", error);
    return [];
  }
};

export const saveMatch = (match: MatchState) => {
  const matches = getSavedMatches();
  matches.push(match);
  localStorage.setItem(MATCHES_KEY, JSON.stringify(matches));
};

export const clearMatches = () => {
  localStorage.removeItem(MATCHES_KEY);
};

export const seedDefaultTeams = () => {
  const teams = getSavedTeams();
  if (teams.length === 0) {
    const defaultTeam: SavedTeam = {
      id: 'taxila-tigers-default',
      name: 'Taxila Tigers',
      logoUrl: 'https://files.oaiusercontent.com/file-2p5s5S4jKqvqYw',
      squad: Array.from({ length: 15 }, (_, i) => `Tiger Player ${i + 1}`)
    };
    saveTeam(defaultTeam);
  }
};

import React, { useState, useEffect } from 'react';
import { MatchSetup } from './components/MatchSetup';
import { SquadSelection } from './components/SquadSelection';
import { TossScreen } from './components/TossScreen';
import { OpenerSelection } from './components/OpenerSelection';
import { ScoringDashboard } from './components/ScoringDashboard';
import { InningsBreak } from './components/InningsBreak';
import { StatsDashboard } from './components/StatsDashboard';
import { TeamManager } from './components/TeamManager';
import { MatchState, Player, Team, SavedTeam } from './types';
import { MatchSummary } from './components/MatchSummary';
import { getSavedMatches, saveMatch } from './utils/storage';

interface SetupData {
  homeTeam: SavedTeam;
  awayTeam: SavedTeam;
  overs: number;
  homeXI?: string[]; 
  awayXI?: string[];
  homeReserves?: string[]; 
  awayReserves?: string[];
}

const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'team-manager' | 'squad-select' | 'toss' | 'openers' | 'scoring' | 'innings-break' | 'summary' | 'stats'>('setup');
  const [matchState, setMatchState] = useState<MatchState | null>(null);
  const [setupData, setSetupData] = useState<SetupData | null>(null);
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);
  const [history, setHistory] = useState<MatchState[]>([]);

  // Load saved matches on startup
  useEffect(() => {
    const saved = getSavedMatches();
    setMatchHistory(saved);
  }, []);

  // 1. Initial Setup
  const handleSetupComplete = (
    homeTeam: SavedTeam,
    awayTeam: SavedTeam,
    overs: number
  ) => {
    setSetupData({ homeTeam, awayTeam, overs });
    setView('squad-select');
  };

  // 2. Select 11 Players + Reserves
  const handleSquadConfirm = (homeXI: string[], awayXI: string[], homeReserves: string[], awayReserves: string[]) => {
    setSetupData(prev => prev ? ({ ...prev, homeXI, awayXI, homeReserves, awayReserves }) : null);
    setView('toss');
  };

  // 3. Toss Logic
  const handleTossComplete = (winner: string, decision: 'bat' | 'bowl') => {
    if (!setupData || !setupData.homeXI || !setupData.awayXI) return;

    const isHomeBattingFirst = (winner === setupData.homeTeam.name && decision === 'bat') || (winner === setupData.awayTeam.name && decision === 'bowl');

    const battingTeamPlayers = isHomeBattingFirst ? setupData.homeXI : setupData.awayXI;
    const bowlingTeamPlayers = isHomeBattingFirst ? setupData.awayXI : setupData.homeXI;
    const battingTeamObj = isHomeBattingFirst ? setupData.homeTeam : setupData.awayTeam;
    const bowlingTeamObj = isHomeBattingFirst ? setupData.awayTeam : setupData.homeTeam;

    const battingTeam: Team = {
      name: battingTeamObj.name,
      logoUrl: battingTeamObj.logoUrl,
      players: battingTeamPlayers.map((name, id) => ({ id: `bat${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: true,
    };

    const bowlingTeam: Team = {
      name: bowlingTeamObj.name,
      logoUrl: bowlingTeamObj.logoUrl,
      players: bowlingTeamPlayers.map((name, id) => ({ id: `bowl${id}`, name, runs: 0, balls: 0, fours: 0, sixes: 0, isOut: false, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 })),
      isBatting: false,
    };

    const initialState: MatchState = {
      battingTeam,
      bowlingTeam,
      tossWinner: winner,
      tossDecision: decision,
      totalOvers: setupData.overs,
      currentOver: 0,
      currentBall: 0,
      totalRuns: 0,
      wickets: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: '', 
      nonStrikerId: '', 
      currentBowlerId: '', 
      ballHistory: [],
      matchStatus: 'LIVE',
      inningsNumber: 1
    };

    setMatchState(initialState);
    setView('openers');
  };

  // 4. Start Innings
  const handleStartInnings = (strikerId: string, nonStrikerId: string, bowlerId: string) => {
    if (!matchState) return;
    setMatchState({
      ...matchState,
      strikerId,
      nonStrikerId,
      currentBowlerId: bowlerId,
      matchStatus: 'LIVE'
    });
    setView('scoring');
  };

  // 5. Innings/Match Flow
  const handleScoringFinish = () => {
    if (!matchState) return;
    if (matchState.matchStatus === 'INNINGS_BREAK') {
      setView('innings-break');
    } else if (matchState.matchStatus === 'COMPLETED') {
      setView('summary');
    }
  };

  // 6. Start 2nd Innings
  const handleStartSecondInnings = () => {
    if (!matchState) return;

    const oldBatting = matchState.battingTeam;
    const oldBowling = matchState.bowlingTeam;

    // Swap Roles
    const newBattingTeam: Team = { ...oldBowling, isBatting: true };
    const newBowlingTeam: Team = { ...oldBatting, isBatting: false };

    const newState: MatchState = {
      ...matchState,
      battingTeam: newBattingTeam,
      bowlingTeam: newBowlingTeam,
      totalRuns: 0,
      wickets: 0,
      currentOver: 0,
      currentBall: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 },
      strikerId: '',
      nonStrikerId: '',
      currentBowlerId: '',
      inningsNumber: 2,
      target: matchState.totalRuns + 1,
      matchStatus: 'LIVE'
    };

    setMatchState(newState);
    setHistory([]);
    setView('openers');
  };

  const handleUpdateScore = (newState: MatchState) => {
    if (matchState) setHistory(prev => [...prev, matchState].slice(-50));
    setMatchState(newState);
  };

  const handleUndo = () => {
    if (history.length === 0) return;
    const previousState = history[history.length - 1];
    setHistory(prev => prev.slice(0, -1));
    setMatchState(previousState);
  };

  const handleSaveAndExit = (finalState: MatchState) => {
    saveMatch(finalState);
    setMatchHistory(prev => [...prev, finalState]);
    setView('setup');
  };

  return (
    <div className="h-screen w-full bg-tiger-black text-white flex flex-col font-sans">
      {view === 'setup' && (
        <MatchSetup 
          onNext={handleSetupComplete} 
          onViewStats={() => setView('stats')}
          onManageTeams={() => setView('team-manager')}
        />
      )}

      {view === 'team-manager' && (
        <TeamManager onBack={() => setView('setup')} />
      )}

      {view === 'squad-select' && setupData && (
        <SquadSelection
           homeTeam={setupData.homeTeam}
           awayTeam={setupData.awayTeam}
           onConfirm={handleSquadConfirm}
           onBack={() => setView('setup')}
        />
      )}

      {view === 'toss' && setupData && (
        <TossScreen 
          homeTeam={setupData.homeTeam.name} 
          awayTeam={setupData.awayTeam.name} 
          onTossComplete={handleTossComplete}
          onBack={() => setView('setup')}
        />
      )}

      {view === 'openers' && matchState && (
        <OpenerSelection
          inningsNumber={matchState.inningsNumber}
          battingTeamName={matchState.battingTeam.name}
          bowlingTeamName={matchState.bowlingTeam.name}
          battingPlayers={matchState.battingTeam.players}
          bowlingPlayers={matchState.bowlingTeam.players}
          onStart={handleStartInnings}
        />
      )}

      {view === 'scoring' && matchState && (
        <ScoringDashboard 
          matchState={matchState} 
          setMatchState={handleUpdateScore} 
          onUndo={handleUndo}
          canUndo={history.length > 0}
          onFinish={handleScoringFinish}
        />
      )}

      {view === 'innings-break' && matchState && (
        <InningsBreak 
          matchState={matchState}
          onStartSecondInnings={handleStartSecondInnings}
        />
      )}

      {view === 'summary' && matchState && (
        <MatchSummary 
          matchState={matchState} 
          onSaveAndExit={handleSaveAndExit} 
        />
      )}

      {view === 'stats' && (
        <StatsDashboard 
          matchHistory={matchHistory} 
          onBack={() => setView('setup')} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { MatchState, Player } from '../types';
import { aggregateStats, CareerStats } from '../utils/statsLogic';
import { ArrowLeft, Trophy, Calendar, ChevronRight, X, FileText, Download, UserCheck, ArrowUpRight } from 'lucide-react';

interface Props {
  matchHistory: MatchState[];
  onBack: () => void;
}

export const StatsDashboard: React.FC<Props> = ({ matchHistory, onBack }) => {
  const [activeTab, setActiveTab] = useState<'players' | 'matches'>('players');
  const [statType, setStatType] = useState<'batting' | 'bowling'>('batting');
  const [selectedMatch, setSelectedMatch] = useState<MatchState | null>(null);
  const [highlightedPlayer, setHighlightedPlayer] = useState<string | null>(null);

  const HOME_TEAM_NAME = 'Taxila Tigers';

  // Clear highlight when tab changes manually
  useEffect(() => {
    if (activeTab === 'matches') setHighlightedPlayer(null);
  }, [activeTab]);

  // --- CAREER STATS LOGIC ---
  const playerStats = useMemo(() => aggregateStats(matchHistory, HOME_TEAM_NAME), [matchHistory]);

  const sortedCareerPlayers = useMemo(() => {
    return [...playerStats].sort((a, b) => {
      if (statType === 'batting') return b.runs - a.runs;
      return b.wickets - a.wickets;
    });
  }, [playerStats, statType]);

  // --- MATCH DETAIL LOGIC ---
  const getMatchPlayers = (match: MatchState) => {
    if (match.battingTeam.name === HOME_TEAM_NAME) return match.battingTeam.players;
    if (match.bowlingTeam.name === HOME_TEAM_NAME) return match.bowlingTeam.players;
    return []; 
  };

  const sortedMatchPlayers = useMemo(() => {
    if (!selectedMatch) return [];
    const players = getMatchPlayers(selectedMatch);
    return [...players].sort((a, b) => {
      if (statType === 'batting') return b.runs - a.runs;
      return b.wickets - a.wickets; 
    });
  }, [selectedMatch, statType]);

  const goToCareer = (playerName: string) => {
    setHighlightedPlayer(playerName);
    setActiveTab('players');
    setSelectedMatch(null);
    // Auto scroll to player if needed (simplified here)
  };

  const handleDownloadPDF = () => {
    window.print();
  };

  // --- HELPERS ---
  const calcBatAvg = (runs: number, outs: number) => {
    if (outs === 0) return runs === 0 ? '-' : runs.toFixed(2);
    return (runs / outs).toFixed(2);
  };

  const calcBatSR = (runs: number, balls: number) => {
    if (balls === 0) return '-';
    return ((runs / balls) * 100).toFixed(2);
  };

  const calcBowlEcon = (runs: number, balls: number) => {
    if (balls === 0) return '-';
    return ((runs / balls) * 6).toFixed(2);
  };

  const calcBowlSR = (balls: number, wickets: number) => {
    if (wickets === 0) return '-';
    return (balls / wickets).toFixed(2);
  };

  const calcOvers = (balls: number) => `${Math.floor(balls/6)}.${balls%6}`;

  const getMatchResult = (match: MatchState) => {
    if (match.matchStatus !== 'COMPLETED') return { text: 'In Progress / Abandoned', color: 'text-gray-500' };
    if (!match.firstInningsScore) return { text: 'Result Unknown', color: 'text-gray-500' };

    const scoreFirst = match.firstInningsScore.runs;
    const scoreSecond = match.totalRuns;
    const teamBattingSecond = match.battingTeam.name;
    const teamBattingFirst = match.firstInningsScore.teamName;

    let winner = '';
    let margin = '';

    if (scoreSecond > scoreFirst) {
      winner = teamBattingSecond;
      margin = `${10 - match.wickets} wickets`;
    } else if (scoreFirst > scoreSecond) {
      winner = teamBattingFirst;
      margin = `${scoreFirst - scoreSecond} runs`;
    } else {
      return { text: 'Match Tied', color: 'text-gray-400' };
    }

    if (winner === HOME_TEAM_NAME) {
       return { text: `Won by ${margin}`, color: 'text-green-400' };
    } else {
       return { text: `Lost by ${margin}`, color: 'text-red-400' };
    }
  };

  // --- RENDERERS ---

  const renderBattingTable = (data: (CareerStats | Player)[], isCareer: boolean) => (
    <>
      <div className="grid grid-cols-8 bg-gray-750 p-3 border-b border-gray-700 text-[10px] sm:text-xs font-bold text-gray-400 uppercase tracking-wider text-center sticky top-0 print-table-header">
        <div className="col-span-2 text-left pl-2">Player</div>
        <div>{isCareer ? 'Mat' : ''}</div>
        <div>Runs</div>
        <div>Balls</div>
        <div>{isCareer ? 'HS' : 'SR'}</div>
        <div>{isCareer ? 'Avg' : ''}</div>
        <div className="no-print"></div>
      </div>
      <div className="divide-y divide-gray-700/50">
        {data.filter(p => (isCareer ? (p as CareerStats).matches > 0 : (p as Player).balls > 0 || (p as Player).isOut)).map((p, idx) => {
          const runs = p.runs;
          const balls = isCareer ? (p as CareerStats).ballsFaced : (p as Player).balls;
          const matches = isCareer ? (p as CareerStats).matches : 1;
          const hs = isCareer ? (p as CareerStats).highestScore : runs;
          const outs = isCareer ? (p as CareerStats).outs : ((p as Player).isOut ? 1 : 0);
          const sr = calcBatSR(runs, balls);
          const avg = calcBatAvg(runs, outs);
          const isHighlighted = highlightedPlayer === p.name;

          return (
            <div key={p.name} className={`grid grid-cols-8 p-3 items-center text-xs sm:text-sm text-center transition-colors ${isHighlighted ? 'bg-tiger-gold/20' : 'hover:bg-gray-700/30'}`}>
              <div className="col-span-2 text-left font-bold text-white pl-2 flex items-center gap-2 overflow-hidden">
                 <span className="truncate">{p.name}</span>
                 {isHighlighted && <UserCheck size={12} className="text-tiger-gold flex-shrink-0" />}
              </div>
              <div className="text-gray-500">{isCareer ? matches : ''}</div>
              <div className="font-bold text-tiger-gold">{runs}</div>
              <div className="text-gray-400">{balls}</div>
              <div className="text-gray-300 font-mono">{isCareer ? hs : sr}</div>
              <div className="text-gray-300 font-mono">{isCareer ? avg : ''}</div>
              <div className="no-print flex justify-center">
                 {!isCareer && (
                   <button onClick={() => goToCareer(p.name)} className="p-1 hover:text-tiger-gold text-gray-500" title="View Career Stats">
                     <ArrowUpRight size={16} />
                   </button>
                 )}
              </div>
            </div>
          );
        })}
      </div>
    </>
  );

  const renderBowlingTable = (data: (CareerStats | Player)[], isCareer: boolean) => (
    <>
      <div className="grid grid-cols-9 bg-gray-750 p-3 border-b border-gray-700 text-[10px] sm:text-xs font-bold text-gray-400 uppercase tracking-wider text-center sticky top-0 print-table-header">
        <div className="col-span-2 text-left pl-2">Player</div>
        <div>{isCareer ? 'Mat' : ''}</div>
        <div>Overs</div>
        <div>Wkts</div>
        <div>Runs</div>
        <div>Econ</div>
        <div>SR</div>
        <div className="no-print"></div>
      </div>
      <div className="divide-y divide-gray-700/50">
        {data.filter(p => p.ballsBowled > 0).map((p, idx) => {
          const wickets = p.wickets;
          const runs = p.runsConceded;
          const balls = p.ballsBowled;
          const matches = isCareer ? (p as CareerStats).matches : 1;
          const econ = calcBowlEcon(runs, balls);
          const sr = calcBowlSR(balls, wickets);
          const overs = calcOvers(balls);
          const isHighlighted = highlightedPlayer === p.name;

          return (
            <div key={p.name} className={`grid grid-cols-9 p-3 items-center text-xs sm:text-sm text-center transition-colors ${isHighlighted ? 'bg-tiger-gold/20' : 'hover:bg-gray-700/30'}`}>
              <div className="col-span-2 text-left font-bold text-white pl-2 flex items-center gap-2 overflow-hidden">
                 <span className="truncate">{p.name}</span>
                 {isHighlighted && <UserCheck size={12} className="text-tiger-gold flex-shrink-0" />}
              </div>
              <div className="text-gray-500">{isCareer ? matches : ''}</div>
              <div className="text-gray-400">{overs}</div>
              <div className="font-bold text-blue-400">{wickets}</div>
              <div className="text-gray-400">{runs}</div>
              <div className="text-gray-300 font-mono">{econ}</div>
              <div className="text-gray-300 font-mono">{sr}</div>
              <div className="no-print flex justify-center">
                 {!isCareer && (
                   <button onClick={() => goToCareer(p.name)} className="p-1 hover:text-tiger-gold text-gray-500" title="View Career Stats">
                     <ArrowUpRight size={16} />
                   </button>
                 )}
              </div>
            </div>
          );
        })}
      </div>
    </>
  );

  return (
    <div className="flex flex-col h-full bg-tiger-black text-white font-sans relative">

      {/* Header */}
      <div className="bg-tiger-card p-4 border-b border-gray-700 flex items-center justify-between sticky top-0 z-10 no-print">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 rounded-full hover:bg-gray-700 transition-colors">
            <ArrowLeft size={20} className="text-tiger-gold" />
          </button>
          <h2 className="text-xl font-bold text-white truncate">
            {selectedMatch ? 'Match Details' : 'Taxila Tigers Hub'}
          </h2>
        </div>

        <button onClick={handleDownloadPDF} className="flex items-center gap-2 bg-gray-800 hover:bg-gray-700 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-all border border-gray-700 text-gray-300">
           <Download size={14} /> PDF Report
        </button>
      </div>

      {selectedMatch ? (
        // --- MATCH DETAIL VIEW ---
        <div className="flex-1 flex flex-col overflow-hidden animate-in slide-in-from-right duration-300 print-container">
           {/* Match Info Header */}
           <div className="p-4 bg-gray-900 border-b border-gray-800">
              <div className="flex justify-between items-start mb-2">
                 <div>
                    <h3 className="font-bold text-white text-lg print:text-black">{selectedMatch.battingTeam.name} vs {selectedMatch.bowlingTeam.name}</h3>
                    <p className="text-xs text-gray-500">{new Date(selectedMatch.ballHistory[0]?.timestamp || Date.now()).toLocaleDateString()}</p>
                 </div>
                 <button onClick={() => setSelectedMatch(null)} className="p-2 bg-gray-800 rounded-full text-gray-400 hover:text-white no-print">
                    <X size={16} />
                 </button>
              </div>
              <div className="text-sm">
                 <span className={`${getMatchResult(selectedMatch).color} font-bold uppercase`}>{getMatchResult(selectedMatch).text}</span>
              </div>
           </div>

           {/* Stat Toggle */}
           <div className="p-4 bg-gray-900/50 no-print">
             <div className="flex bg-gray-800 p-1 rounded-xl border border-gray-700 w-full max-w-sm mx-auto">
                <button 
                  onClick={() => setStatType('batting')}
                  className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'batting' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                >
                  Batting
                </button>
                <button 
                  onClick={() => setStatType('bowling')}
                  className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'bowling' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                >
                  Bowling
                </button>
             </div>
           </div>

           {/* Table */}
           <div className="flex-1 overflow-y-auto p-4 pt-0">
              <div className="bg-gray-800 rounded-xl border border-gray-700 shadow-xl overflow-hidden print:border-black print:border-t">
                {statType === 'batting' 
                  ? renderBattingTable(sortedMatchPlayers, false) 
                  : renderBowlingTable(sortedMatchPlayers, false)
                }
              </div>
           </div>
        </div>
      ) : (
        // --- MAIN DASHBOARD VIEW ---
        <div className="flex-1 flex flex-col overflow-hidden print-container">
          {/* Tabs */}
          <div className="flex bg-gray-900 border-b border-gray-800 no-print">
            <button 
              onClick={() => setActiveTab('players')}
              className={`flex-1 py-4 font-bold text-xs sm:text-sm uppercase tracking-wider border-b-2 transition-all ${activeTab === 'players' ? 'border-tiger-gold text-tiger-gold bg-gray-800' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
            >
              Career Stats
            </button>
            <button 
              onClick={() => setActiveTab('matches')}
              className={`flex-1 py-4 font-bold text-xs sm:text-sm uppercase tracking-wider border-b-2 transition-all ${activeTab === 'matches' ? 'border-tiger-gold text-tiger-gold bg-gray-800' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
            >
              Match History
            </button>
          </div>

          <div className="flex-1 overflow-y-auto bg-gray-900/50">
            {activeTab === 'players' ? (
              <div className="p-4 space-y-4">
                {/* Stat Type Toggle */}
                <div className="flex bg-gray-800 p-1 rounded-xl border border-gray-700 w-full max-w-sm mx-auto no-print">
                  <button 
                    onClick={() => setStatType('batting')}
                    className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'batting' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                  >
                    Batting
                  </button>
                  <button 
                    onClick={() => setStatType('bowling')}
                    className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${statType === 'bowling' ? 'bg-tiger-gold text-black shadow-lg' : 'text-gray-400 hover:text-white'}`}
                  >
                    Bowling
                  </button>
                </div>

                <div className="print-only mb-6">
                   <h1 className="text-2xl font-black uppercase text-black">Career Stats Report</h1>
                   <p className="text-sm text-gray-600">Generated for {HOME_TEAM_NAME} on {new Date().toLocaleDateString()}</p>
                </div>

                {/* Stats Table */}
                <div className="bg-gray-800 rounded-xl border border-gray-700 shadow-xl overflow-hidden print:border-black">
                    {statType === 'batting' 
                      ? renderBattingTable(sortedCareerPlayers, true)
                      : renderBowlingTable(sortedCareerPlayers, true)
                    }
                </div>

                <div className="text-[10px] text-center text-gray-500 mt-4 italic no-print">
                    * Mat: Matches | HS: Highest Score | Avg: Average | Econ: Economy Rate
                </div>
              </div>
            ) : (
              <div className="p-4 space-y-4 no-print">
                {matchHistory.length === 0 ? (
                    <div className="text-center text-gray-500 py-10">No matches played yet.</div>
                ) : (
                  matchHistory.slice().reverse().map((match, idx) => {
                    const result = getMatchResult(match);
                    const date = new Date(match.ballHistory[0]?.timestamp || Date.now()).toLocaleDateString();

                    return (
                      <button 
                        key={idx} 
                        onClick={() => setSelectedMatch(match)}
                        className="w-full text-left bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-lg relative overflow-hidden group hover:border-tiger-gold transition-all hover:scale-[1.01]"
                      >
                        <div className="absolute top-0 right-0 w-20 h-20 bg-gradient-to-bl from-white/5 to-transparent rounded-bl-full pointer-events-none" />

                        <div className="flex justify-between items-center mb-2">
                          <span className="text-[10px] font-bold text-gray-500 uppercase flex items-center gap-1">
                            <Calendar size={10} /> {date}
                          </span>
                          <span className={`text-[10px] px-2 py-0.5 rounded border font-bold uppercase ${result.color} bg-black/20 border-current`}>
                            {result.text}
                          </span>
                        </div>
                        <div className="flex flex-col gap-2 mt-2">
                            {match.firstInningsScore && (
                              <div className="flex justify-between items-center text-xs text-gray-400">
                                  <span>{match.firstInningsScore.teamName}</span>
                                  <span className="font-mono">{match.firstInningsScore.runs}/{match.firstInningsScore.wickets} <span className="text-[10px]">({match.firstInningsScore.overs})</span></span>
                              </div>
                            )}
                            <div className="flex justify-between items-center text-xs text-white font-semibold">
                                <span>{match.battingTeam.name}</span>
                                <span className="font-mono">{match.totalRuns}/{match.wickets} <span className="text-[10px] text-gray-400">({match.currentOver}.{match.currentBall})</span></span>
                            </div>
                        </div>

                        <div className="mt-3 flex items-center justify-end text-tiger-gold text-[10px] font-bold uppercase tracking-wider gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                           View Stats <ChevronRight size={12} />
                        </div>
                      </button>
                    );
                  })
                )}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};
